DROP PROCEDURE IF EXISTS adm.ana_cx_qtr_bank_card;

CREATE PROCEDURE adm.ana_cx_qtr_bank_card(
     IN V_ACCT_ID    VARCHAR(8),
     IN V_ORG_ID     VARCHAR(14),
     IN V_PARM_TYPE  VARCHAR(1),
     IN V_AREA_ID    VARCHAR(14)
)
AS
    V_PROC_NAME     VARCHAR(80) := 'adm.ana_cx_qtr_bank_card.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;
    P_RESULT        INT := 0;
    V_DATES         VARCHAR(20) := 0;
    V_STATE CHAR(1);
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 杨开泰
     Name      : adm.ana_cx_qtr_bank_card.PRC
     Functions : 交易偏好-银行卡受理市场建设情况
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
    /* ------------------------------------------------------------------------ */
    /* EXCEPTION HANDLER  */
    P_RESULT := 0;
    V_DATES := CONCAT(V_ACCT_ID,'01');
    /* ------------------------------------------------------------------------ */
    V_STEP_ID := 1;
    DELETE FROM adm.ana_cx_qtr_bank_dq_card WHERE QUARTER = SUBSTR(V_ACCT_ID,1,6);
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
   V_STEP_ID := 2;
  -- 银行卡受理市场建设情况 当期数据
INSERT INTO adm.ana_cx_qtr_bank_dq_card 
SELECT
DATA_DATE,      
QUARTER,        
CITY_CODE,      
CITY_NAME,      
COUNTY_CODE,    
COUNTY_NAME,    
AREA_TYPE_CODE, 
BCARD_TYPE_DSCR,
SUM(NUMBER),         
SUM(COUNT),          
SUM(MONEY)            
FROM
(SELECT 
  DATE_FORMAT(V_DATES, '%Y-%m-%d') AS data_date,
  data_date AS QUARTER,
CASE WHEN AREA_ID LIKE '%4401%' THEN '440100' ELSE AREA_ID END AS CITY_CODE,    
CASE WHEN AREA_NAME LIKE '%区%' THEN '广州市' ELSE AREA_NAME END AS CITY_NAME,   
'' AS COUNTY_CODE,
'' AS COUNTY_NAME, 
  CASE
    WHEN AREA_TYPE_CODE = '1' 
    THEN '农村' 
    ELSE '贫困' 
  END AS AREA_TYPE_CODE,
  CASE
    BCARD_TYPE_DSCR 
    WHEN '04' 
    THEN 'ATM' 
    WHEN '05' 
    THEN 'POS' 
    WHEN '06' 
    THEN '其他银行卡受理终端' 
  END AS BCARD_TYPE_DSCR,
  NUMBER,
  COUNT,
  MONEY 
FROM
  edw.py_cx_envbld_rural_cards_mkt 
WHERE data_date = SUBSTR(V_ACCT_ID, 1, 6) 
  AND BCARD_TYPE_DSCR IN ('04', '05', '06') 
  AND area_id != '' ) m
  GROUP BY DATA_DATE,      
QUARTER,        
CITY_CODE,      
CITY_NAME,      
COUNTY_CODE,    
COUNTY_NAME,    
AREA_TYPE_CODE, 
BCARD_TYPE_DSCR ;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
     DELETE FROM adm.ana_cx_qtr_bank_card WHERE QUARTER = SUBSTR(V_ACCT_ID,1,6);
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
  -- 取银行卡受理市场建设情况 同比
  INSERT INTO adm.ana_cx_qtr_bank_card 
SELECT 
  a.data_date,
  -- 账期
  a.quarter,
  -- 季度
  a.city_code,
  -- 地市编码
  a.city_name,
  -- 地市名称
  a.county_code,
  -- 区县编码
  a.county_name,
  -- 区县名称
  a.area_type_code,
  -- 农村贫困地区标准
  a.business_dscr_2,
  -- 业务量描述/支付类型
  a.number,
  a.count,
  b.count,
  a.money,
  b.money 
FROM
  adm.ana_cx_qtr_bank_dq_card a 
  LEFT JOIN 
    (SELECT 
      * 
    FROM
      adm.ana_cx_qtr_bank_dq_card 
    WHERE QUARTER = DATE_FORMAT(
        DATE_SUB(V_DATES, INTERVAL 12 MONTH),
        '%Y%m'
      )) b 
    ON a.city_code = b.city_code 
    AND a.area_type_code = b.area_type_code 
    AND a.business_dscr_2 = b.business_dscr_2 
WHERE a.quarter = SUBSTR(V_ACCT_ID, 1, 6) ;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
    
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
END;
/

