INSERT INTO adm.ana_cx_qtr_bank_cards
SELECT 
DATA_DATE,
QUARTER,
d.area_no_id_2 AS CITY_CODE,     
d.area_dscr_2 AS CITY_NAME,
COUNTY_CODE,
COUNTY_NAME,
AREA_TYPE_CODE,
TYPE,
