 WHERE t.data_date = SUBSTR(V_ACCT_ID,1,6)
 UNION ALL
 
SELECT 
DATE_FORMAT(CONCAT(t.data_date,'01'), '%Y-%m-%d') AS DATA_DATE,      
t.data_date AS QUARTER,           
t.area_id  AS CITY_CODE,    
t.area_name  AS CITY_NAME,   
