(SELECT DISTINCT zone_name FROM edw.py_cx_area_code)  AS CITY_NAME,    
t.area_id AS COUNTY_CODE,
t.area_name AS COUNTY_NAME,
CASE WHEN t.area_type_code='1' THEN '农村'
      WHEN t.area_type_code='2' THEN '贫困' ELSE '' END AS AREA_TYPE_CODE, 
'信用卡' AS TYPE,    
t.credit_card AS CARD
FROM  edw.py_cx_envbld_rural_bnk_cards t  
    WHERE t.data_date = SUBSTR(V_ACCT_ID,1,6)
UNION ALL
 
SELECT 
DATE_FORMAT(CONCAT(t.data_date,'01'), '%Y-%m-%d') AS DATA_DATE,      
t.data_date AS QUARTER,           
(SELECT DISTINCT zone_code FROM edw.py_cx_area_code)  AS CITY_CODE,    
(SELECT DISTINCT zone_name FROM edw.py_cx_area_code)  AS CITY_NAME,    
t.area_id AS COUNTY_CODE,
t.area_name AS COUNTY_NAME,
CASE WHEN t.area_type_code='1' THEN '农村'
      WHEN t.area_type_code='2' THEN '贫困' ELSE '' END AS AREA_TYPE_CODE, 
'借贷合一卡' AS TYPE,    
t.debit_credit AS CARD
FROM  edw.py_cx_envbld_rural_bnk_cards t 
 WHERE t.data_date = SUBSTR(V_ACCT_ID,1,6)) t   
       LEFT JOIN dmcode.t_area_code d
  ON t.county_code=d.area_no_id   
GROUP BY DATA_DATE,
QUARTER,
CITY_CODE,
CITY_NAME,
COUNTY_CODE,
COUNTY_NAME,
AREA_TYPE_CODE,
TYPE;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
     
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
       CALL etl.edw_proc_error_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
END;
/

DROP PROCEDURE IF EXISTS adm.ana_cx_qtr_cls;

CREATE PROCEDURE adm.ana_cx_qtr_cls(
     IN  V_ACCT_ID VARCHAR(8)
    ,OUT P_RESULT    INT
)
AS
    V_PROC_NAME     VARCHAR(80) := 'adm.ana_cx_qtr_cls.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;
    P_RESULT        INT := 0;
    V_DATES         VARCHAR(20) := 0;
    V_STATE CHAR(1);
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 杨开泰
     Name      : adm.ana_cx_qtr_cls.PRC
     Functions : 交易偏好-支付清算大小额系统
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
    /* ------------------------------------------------------------------------ */
    /* EXCEPTION HANDLER  */
    P_RESULT := 0;
    V_DATES := V_ACCT_ID;
    /* ------------------------------------------------------------------------ */
    V_STEP_ID := 1;
    DELETE FROM adm.ana_cx_qtr_dq_cls WHERE QUARTER = SUBSTR(V_ACCT_ID,1,6);
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    -- edw汇总到adm，添加地区名称，区分地区类型--插入农村数据
   V_STEP_ID := 2;
  -- 取非支付现金业务 当期数据
INSERT INTO adm.ana_cx_qtr_dq_cls 
SELECT
DATA_DATE,     
QUARTER,       
d.area_no_id_2 AS CITY_CODE,     
d.area_dscr_2 AS CITY_NAME,      
COUNTY_CODE,   
COUNTY_NAME,   
AREA_TYPE_CODE,
SUM(BANK_BRANCH),
SUM(AGENCY_BRANCH),
SUM(COUNT),
SUM(MONEY)
FROM 
(SELECT 
  DATE_FORMAT(CONCAT(data_date,'01'), '%Y-%m-%d') AS DATA_DATE,
  data_date AS QUARTER,
  '' AS CITY_CODE,    
  '' AS CITY_NAME, 
  area_id AS COUNTY_CODE,
  area_name AS COUNTY_NAME,
  CASE
    WHEN AREA_TYPE_CODE = '1' 
    THEN '农村' 
    ELSE '贫困' 
  END AS AREA_TYPE_CODE,
  BANK_BRANCH,
  AGENCY_BRANCH,
  COUNT,
  MONEY 
FROM
  edw.py_cx_envbld_rural_cls) c
    LEFT JOIN dmcode.t_area_code d
  ON c.county_code=d.area_no_id 
WHERE QUARTER = SUBSTR(V_ACCT_ID, 1, 6) 
GROUP BY DATA_DATE,     
QUARTER,       
CITY_CODE,     
CITY_NAME,     
COUNTY_CODE,   
COUNTY_NAME,   
AREA_TYPE_CODE;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
     DELETE FROM adm.ana_cx_qtr_cls WHERE QUARTER = SUBSTR(V_ACCT_ID,1,6);
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
  -- 取非支付现金业务 同比数据 市-市
  INSERT INTO adm.ana_cx_qtr_cls 
SELECT 
  a.data_date,
  -- 账期
  a.quarter,
  -- 季度
  a.city_code,
  -- 地市编码
  a.city_name,
  -- 地市名称
  a.county_code,
  -- 区县编码
  a.county_name,
  -- 区县名称
  a.area_type_code,
  -- 农村贫困地区标准
  a.bank_branch,
  a.agency_branch,
  a.count,
  b.count,
  a.money,
  b.money 
FROM
  adm.ana_cx_qtr_dq_cls a 
  LEFT JOIN 
    (SELECT 
      * 
    FROM
      adm.ana_cx_qtr_dq_cls 
    WHERE QUARTER = DATE_FORMAT(
        DATE_SUB(V_DATES, INTERVAL 12 MONTH),
        '%Y%m'
      )) b 
    ON a.city_code = b.city_code 
    AND a.area_type_code = b.area_type_code 
WHERE a.quarter = SUBSTR(V_DATES, 1, 6) ;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
  -- 取非支付现金业务 同比数据 省-市
  INSERT INTO adm.ana_cx_qtr_cls 
SELECT 
  a.data_date,
  -- 账期
  a.quarter,
  -- 季度
(SELECT DISTINCT zone_code FROM edw.py_cx_area_code),
 (SELECT DISTINCT zone_name FROM edw.py_cx_area_code),
  a.city_code,
  -- 区县编码
  a.city_name,
  -- 区县名称
  a.area_type_code,
  -- 农村贫困地区标准
  a.bank_branch,
  a.agency_branch,
  a.count,
  b.count,
  a.money,
  b.money 
FROM
  adm.ana_cx_qtr_dq_cls a 
  LEFT JOIN 
    (SELECT 
      * 
    FROM
      adm.ana_cx_qtr_dq_cls 
    WHERE QUARTER = DATE_FORMAT(
        DATE_SUB(V_DATES, INTERVAL 12 MONTH),
        '%Y%m'
      )) b 
    ON a.city_code = b.city_code 
    AND a.area_type_code = b.area_type_code 
WHERE a.quarter = SUBSTR(V_DATES, 1, 6) ;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
       
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
END;
/

DROP PROCEDURE IF EXISTS adm.ana_cx_qtr_non_cash_pay;

CREATE PROCEDURE adm.ana_cx_qtr_non_cash_pay(
     IN  V_ACCT_ID VARCHAR(8)
    ,OUT P_RESULT    INT
)
AS
    V_PROC_NAME     VARCHAR(80) := 'adm.ana_cx_qtr_non_cash_pay.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;
    P_RESULT        INT := 0;
    V_DATES         VARCHAR(20) := 0;
    V_STATE CHAR(1);
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 杨开泰
     Name      : adm.ana_cx_qtr_non_cash_pay.PRC
     Functions : 非现金支付
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
    /* ------------------------------------------------------------------------ */
    /* EXCEPTION HANDLER  */
    P_RESULT := 0;
    V_DATES := V_ACCT_ID;
    /* ------------------------------------------------------------------------ */
    V_STEP_ID := 1;
    DELETE FROM adm.ana_cx_qtr_non_cash_dq_pay WHERE QUARTER = SUBSTR(V_ACCT_ID,1,6);
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
   V_STEP_ID := 2;
  -- 银行卡受理市场建设情况 当期数据
INSERT INTO adm.ana_cx_qtr_non_cash_dq_pay 
SELECT
DATA_DATE,      
QUARTER,
d.area_no_id_2 AS CITY_CODE,     
d.area_dscr_2 AS CITY_NAME,            
COUNTY_CODE,    
COUNTY_NAME,    
AREA_TYPE_CODE, 
PAY_CODE,         
SUM(COUNT),          
SUM(MONEY)            
FROM
(SELECT 
   DATE_FORMAT(CONCAT(SUBSTR(V_ACCT_ID,1,6),'01'), '%Y-%m-%d') AS data_date,  
  data_date AS QUARTER,
AREA_ID AS CITY_CODE,    
AREA_NAME AS CITY_NAME,   
AREA_ID AS COUNTY_CODE,
AREA_NAME AS COUNTY_NAME, 
  CASE
    WHEN AREA_TYPE_CODE = '1' 
    THEN '农村' 
    ELSE '贫困' 
  END AS AREA_TYPE_CODE,
  CASE
    PAY_CODE 
    WHEN '07' 
    THEN '网上支付' 
    WHEN '08' 
    THEN '移动支付' 
    WHEN '09' 
    THEN '电话支付' 
  END AS PAY_CODE,
  COUNT,
  MONEY 
FROM
  edw.py_cx_envbld_rural_ncpi_tltyp 
WHERE data_date = SUBSTR(V_ACCT_ID, 1, 6) 
  AND PAY_CODE IN ('07', '08', '09','网上支付','移动支付','电话支付') 
  AND area_id != '' ) m
       LEFT JOIN dmcode.t_area_code d
  ON m.county_code=d.area_no_id 
  GROUP BY DATA_DATE,      
QUARTER,        
CITY_CODE,      
CITY_NAME,      
COUNTY_CODE,    
COUNTY_NAME,    
AREA_TYPE_CODE, 
PAY_CODE 
UNION ALL
SELECT
DATA_DATE,      
QUARTER,        
  d.area_no_id_2 AS CITY_CODE,     
d.area_dscr_2 AS CITY_NAME,            
COUNTY_CODE,    
COUNTY_NAME,     
AREA_TYPE_CODE, 
BUSINESS_CODE,       
SUM(COUNT),          
SUM(MONEY)            
FROM
(SELECT 
  DATE_FORMAT(CONCAT(SUBSTR(V_ACCT_ID,1,6),'01'), '%Y-%m-%d') AS data_date,    
  data_date AS QUARTER,
AREA_ID AS CITY_CODE,    
AREA_NAME AS CITY_NAME,   
AREA_ID AS COUNTY_CODE,
AREA_NAME AS COUNTY_NAME, 
  CASE
    WHEN AREA_TYPE_CODE = '1' 
    THEN '农村' 
    ELSE '贫困' 
  END AS AREA_TYPE_CODE,
  CASE
    BUSINESS_CODE 
    WHEN '01' 
    THEN '银行卡' 
    WHEN '02' 
    THEN '票据' 
  END AS BUSINESS_CODE,
  COUNT,
  MONEY 
FROM
  edw.py_cx_envbld_rural_ncpi_tltyp 
WHERE data_date = SUBSTR(V_ACCT_ID, 1, 6) 
  AND BUSINESS_CODE IN ('01', '02','银行卡业务量','票据业务量') 
  AND area_id != '' ) m
         LEFT JOIN dmcode.t_area_code d
  ON m.county_code=d.area_no_id 
  GROUP BY m.data_date,      
QUARTER,        
m.city_code,      
m.city_name,      
m.county_code,    
m.county_name,    
m.area_type_code, 
m.business_code;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
     DELETE FROM adm.ana_cx_qtr_non_cash_pay WHERE QUARTER = SUBSTR(V_ACCT_ID,1,6);
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
  -- 取银行卡受理市场建设情况 同比 --地市-地市
  INSERT INTO adm.ana_cx_qtr_non_cash_pay 
SELECT 
  a.data_date, -- 账期
  a.quarter,  -- 季度
  a.city_code,  -- 地市编码
  a.city_name, -- 地市名称
  a.county_code, -- 区县编码
  a.county_name, -- 区县名称
  a.area_type_code, -- 农村贫困地区标准
  a.business_dscr_1, -- 业务量描述/支付类型
  a.count,
  b.count,
  a.money,
  b.money 
FROM
  adm.ana_cx_qtr_non_cash_dq_pay a 
  LEFT JOIN 
    (SELECT  *   FROM  adm.ana_cx_qtr_non_cash_dq_pay 
    WHERE QUARTER = DATE_FORMAT( DATE_SUB(V_DATES, INTERVAL 12 MONTH),  '%Y%m'  )) b 
    ON a.city_code = b.city_code 
    AND a.area_type_code = b.area_type_code 
    AND a.business_dscr_1 = b.business_dscr_1 
WHERE a.quarter = SUBSTR(V_ACCT_ID, 1, 6) ;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 insert into adm.ana_cx_qtr_non_cash_pay
 select data_date,QUARTER,(SELECT DISTINCT zone_code FROM edw.py_cx_area_code),
 (SELECT DISTINCT zone_name FROM edw.py_cx_area_code),
   a.city_code,  -- 地市编码
  a.city_name, -- 地市名称
     a.area_type_code, -- 农村贫困地区标准
  a.business_dscr_1, -- 业务量描述/支付类型 
  sum(count),sum(COUNT_LY),sum(MONEY),sum(MONEY_LY)
  from adm.ana_cx_qtr_non_cash_pay a
  where a.quarter = SUBSTR(V_ACCT_ID, 1, 6)
  group by  data_date,QUARTER, 
   a.city_code,  
  a.city_name, 
     a.area_type_code,  
  a.business_dscr_1  ;
      CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
      
         -- 修改专题URL 链接 默认为数据表中最大一个月
      DELETE FROM  adm.py_cx_menu_zt  WHERE  url_type ='QUARTER' AND url_pro='RPY';  
    
     INSERT INTO  adm.py_cx_menu_zt
  SELECT menu_id,CONCAT(SUBSTR(a.url,1,LENGTH(SUBSTRING_INDEX(a.url,'QUARTER',1))+43),
 (SELECT MAX(QUARTER) FROM adm.ana_cx_qtr_non_cash_pay),
 SUBSTR(a.url,LENGTH(SUBSTRING_INDEX(a.url,'QUARTER',1))+50,10000)) ,'QUARTER','RPY'
  FROM  dps.t_sc_menu a 
  WHERE  SUBSTR(a.url,-3) ='RPY' AND a.url LIKE '%QUARTER%' ;
  
  UPDATE dps.t_sc_menu a  
  SET a.url= (SELECT b.url FROM adm.py_cx_menu_zt b WHERE a.menu_id=b.menu_id)
  WHERE SUBSTR(a.url,-3) ='RPY' AND a.url LIKE '%QUARTER%' ;   
  
  
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
END;
/

DROP PROCEDURE IF EXISTS adm.ana_cx_qtr_non_cash_pay_kh;

CREATE PROCEDURE adm.ana_cx_qtr_non_cash_pay_kh(
     IN  V_ACCT_ID VARCHAR(8)
    ,OUT P_RESULT    INT
)
AS
    V_PROC_NAME     VARCHAR(80) := 'adm.ana_cx_qtr_non_cash_pay_kh.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;
    P_RESULT        INT := 0;
    V_DATES         VARCHAR(20) := 0;
    V_STATE CHAR(1);
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 宋楠
     Name      : adm.ana_cx_qtr_non_cash_pay_kh.PRC
     Functions : 
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
    /* ------------------------------------------------------------------------ */
    /* EXCEPTION HANDLER  */
    P_RESULT := 0;
    V_DATES := V_ACCT_ID;
    /* ------------------------------------------------------------------------ */
    V_STEP_ID := 1;
    DELETE FROM adm.ana_cx_qtr_non_cash_pay_kh WHERE QUARTER = SUBSTR(V_ACCT_ID,1,6);
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    
   V_STEP_ID := 2;
  -- 取非支付现金业务 当期数据 地市-地市
INSERT INTO adm.ana_cx_qtr_non_cash_pay_kh
SELECT DISTINCT
  DATE_FORMAT(concat(t.data_date,'01'), '%Y-%m-%d') AS data_date,
  t.data_date AS QUARTER,
d.area_no_id_2 AS CITY_CODE,     
d.area_dscr_2 AS CITY_NAME, 
 t.area_id,    
t.area_name, 
CASE WHEN t.area_type_code='1' THEN '农村'
      WHEN t.area_type_code='2' THEN '贫困' ELSE '' END AS AREA_TYPE_CODE, 
p.business_type,
t.account_number 
FROM  adm.py_cx_envbld_rural_ncpi_tltyp t
LEFT JOIN edw.py_cx_bus_type p
ON t.pay_code=p.business_code
     LEFT JOIN dmcode.t_area_code d
  ON t.area_id=d.area_no_id 
WHERE t.pay_code!='0'  and t.data_date = SUBSTR(V_ACCT_ID,1,6) AND p.business_type IS NOT NULL ;
 
  -- 取非支付现金业务 当期数据 省-地市
INSERT INTO adm.ana_cx_qtr_non_cash_pay_kh
SELECT DISTINCT
  DATE_FORMAT(CONCAT(t.data_date,'01'), '%Y-%m-%d') AS data_date,
  t.data_date AS QUARTER,
(SELECT DISTINCT zone_code FROM edw.py_cx_area_code),
 (SELECT DISTINCT zone_name FROM edw.py_cx_area_code),   
d.area_no_id_2 AS CITY_CODE,     
d.area_dscr_2 AS CITY_NAME,  
CASE WHEN t.area_type_code='1' THEN '农村'
      WHEN t.area_type_code='2' THEN '贫困' ELSE '' END AS AREA_TYPE_CODE, 
p.business_type,
t.account_number 
FROM  adm.py_cx_envbld_rural_ncpi_tltyp t
     LEFT JOIN dmcode.t_area_code d
  ON t.area_id=d.area_no_id 
LEFT JOIN edw.py_cx_bus_type p
ON t.pay_code=p.business_code
WHERE t.pay_code!='0'  AND t.data_date = SUBSTR(V_ACCT_ID,1,6) AND p.business_type IS NOT NULL ;
   CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
       CALL etl.edw_proc_error_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
END;
/

DROP PROCEDURE IF EXISTS adm.ana_cx_qtr_static;

CREATE PROCEDURE adm.ana_cx_qtr_static(
     IN  V_ACCT_ID VARCHAR(8)
    ,OUT P_RESULT    INT
)
AS
    V_PROC_NAME     VARCHAR(80) := 'adm.ana_cx_qtr_static.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;
    P_RESULT        INT := 0;
    V_DATES         VARCHAR(20) := 0;
    V_STATE CHAR(1);
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 杨开泰
     Name      : adm.ana_cx_qtr_static.PRC
     Functions : 行政村覆盖率及空白行政村数量统计表
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
    /* ------------------------------------------------------------------------ */
    /* EXCEPTION HANDLER  */
    P_RESULT := 0;
    V_DATES := V_ACCT_ID;
    /* ------------------------------------------------------------------------ */
    V_STEP_ID := 1;
    DELETE FROM adm.ana_cx_qtr_static WHERE QUARTER = SUBSTR(V_ACCT_ID,1,6);
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
   V_STEP_ID := 2;
  -- 行政村覆盖率及空白行政村数量统计表  市-市
INSERT INTO adm.ana_cx_qtr_static
SELECT STR_TO_DATE(CONCAT(LEFT(V_ACCT_ID,4),'-',SUBSTR(V_ACCT_ID,5,2),'-01'),'%Y-%m-%d') AS DATA_DATE,
SUBSTR(V_ACCT_ID,1,6) AS QUARTER,
a.city_code,
a.city_name,
a.area_id,
a.area_name,
CASE a.area_type_code WHEN '1' THEN '农村' ELSE  '贫困' END,
b.county_num ,  -- 空白服务点个数
a.country_num  , --  行政村总数(个)
b.village_num  , -- 服务点数量(个)
a.population_num  ,
a.outlets_num 
 FROM  (SELECT DATA_DATE,d.area_no_id_2 AS CITY_CODE,     
d.area_dscr_2 AS CITY_NAME,AREA_ID,AREA_NAME,AREA_TYPE_CODE,
SUM(COUNTY_NUM+COUNTRY_NUM+VILLAGE_NUM) AS COUNTRY_NUM,
SUM(POPULATION_NUM) AS POPULATION_NUM,
SUM(OUTLETS_NUM) AS OUTLETS_NUM
 FROM edw.py_cx_envbld_rural_static a
     LEFT JOIN dmcode.t_area_code d
  ON a.area_id=d.area_no_id 
WHERE DATA_DATE=SUBSTR(V_ACCT_ID,1,6) 
GROUP BY DATA_DATE,AREA_ID,AREA_NAME,AREA_TYPE_CODE) a
 LEFT JOIN (SELECT  DATA_DATE,
area_id,
area_name,
CASE WHEN t.area_type_code='1' THEN 1  ELSE 2 END AS AREA_TYPE_CODE, 
SUM(CASE WHEN FARM_DRAWAL_CODE='30' THEN COUNT ELSE 0 END) AS COUNTY_NUM,
SUM(CASE WHEN FARM_DRAWAL_CODE='10' THEN COUNT ELSE 0 END) AS VILLAGE_NUM
FROM edw.py_cx_envbld_hf_wd t
WHERE FARM_DRAWAL_CODE  IN ('30','10') 
AND DATA_DATE=SUBSTR(V_ACCT_ID,1,6) 
GROUP BY   t.data_date ,area_id,area_name,t.area_type_code) b
 ON  a.area_id=b.area_id AND a.area_type_code=b.area_type_code  ;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
  -- 行政村覆盖率及空白行政村数量统计表  市-市
INSERT INTO adm.ana_cx_qtr_static
SELECT STR_TO_DATE(CONCAT(LEFT(V_ACCT_ID,4),'-',SUBSTR(V_ACCT_ID,5,2),'-01'),'%Y-%m-%d') AS DATA_DATE,
SUBSTR(V_ACCT_ID,1,6) AS QUARTER,
(SELECT DISTINCT zone_code FROM edw.py_cx_area_code),
 (SELECT DISTINCT zone_name FROM edw.py_cx_area_code),
d.area_no_id_2 AS CITY_CODE,     
d.area_dscr_2 AS CITY_NAME,
CASE a.area_type_code WHEN '1' THEN '农村' ELSE  '贫困' END,
b.county_num ,  -- 空白服务点个数
a.country_num  , --  行政村总数(个)
b.village_num  , -- 服务点数量(个)
a.population_num  ,
a.outlets_num 
 FROM  (SELECT DATA_DATE,AREA_ID,AREA_NAME,AREA_TYPE_CODE,
SUM(COUNTY_NUM+COUNTRY_NUM+VILLAGE_NUM) AS COUNTRY_NUM,
SUM(POPULATION_NUM) AS POPULATION_NUM,
SUM(OUTLETS_NUM) AS OUTLETS_NUM
 FROM edw.py_cx_envbld_rural_static
WHERE DATA_DATE=SUBSTR(V_ACCT_ID,1,6) 
GROUP BY DATA_DATE,AREA_ID,AREA_NAME,AREA_TYPE_CODE) a
 LEFT JOIN dmcode.t_area_code d
  ON a.area_id=d.area_no_id 
 LEFT JOIN (SELECT  DATA_DATE,
area_id,
area_name,
CASE WHEN t.area_type_code='1' THEN 1  ELSE 2 END AS AREA_TYPE_CODE, 
SUM(CASE WHEN FARM_DRAWAL_CODE='30' THEN COUNT ELSE 0 END) AS COUNTY_NUM,
SUM(CASE WHEN FARM_DRAWAL_CODE='10' THEN COUNT ELSE 0 END) AS VILLAGE_NUM
FROM edw.py_cx_envbld_hf_wd t
WHERE FARM_DRAWAL_CODE  IN ('30','10') 
AND DATA_DATE=SUBSTR(V_ACCT_ID,1,6) 
GROUP BY   t.data_date ,area_id,area_name,t.area_type_code) b
 ON  a.area_id=b.area_id AND a.area_type_code=b.area_type_code  ;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
END;
/

DROP PROCEDURE IF EXISTS adm.ana_cx_qtr_trade_all;

CREATE PROCEDURE adm.ana_cx_qtr_trade_all(
     IN V_ACCT_ID    VARCHAR(8),
     OUT P_RESULT    INT
)
AS
    V_PROC_NAME     VARCHAR(80) := 'adm.ana_cx_qtr_trade_all.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;
    P_RESULT        INT := 0;
    V_DATES         VARCHAR(20) := 0;
    V_STATE CHAR(1);
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 杨开拓
     Name      : adm.ana_cx_qtr_trade_all.PRC
     Functions : 农村支付上报交易总览
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
    /* ------------------------------------------------------------------------ */
    /* EXCEPTION HANDLER  */
    P_RESULT := 0;
    V_DATES := V_ACCT_ID;
    /* ------------------------------------------------------------------------ */
     V_STEP_ID := 1;
    DELETE FROM adm.ana_cx_qtr_trade_all WHERE QUARTER = SUBSTR(V_ACCT_ID,1,6);
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
   V_STEP_ID := 2;
  --  农村支付上报交易总览					
 INSERT INTO adm.ana_cx_qtr_trade_all 
SELECT data_date,QUARTER,city_code,city_name,county_code,county_name,area_type_code,'支付清算',SUM(COUNT),SUM(count_ly),SUM(money),SUM(money_ly)
FROM adm.ana_cx_qtr_cls
GROUP BY data_date,QUARTER,city_code,city_name,county_code,county_name,area_type_code
UNION ALL
SELECT data_date,QUARTER,city_code,city_name,county_code,county_name,AREA_TYPE_CODE,'银行卡受理终端',SUM(COUNT),SUM(count_ly),SUM(money),SUM(money_ly)
FROM adm.ana_cx_qtr_bank_card
GROUP BY data_date,QUARTER,city_code,city_name,county_code,county_name,area_type_code
UNION ALL
SELECT data_date,QUARTER,city_code,city_name,county_code,county_name,AREA_TYPE_CODE,'非现金支付',SUM(COUNT),SUM(count_ly),SUM(money),SUM(money_ly)
FROM adm.ana_cx_qtr_non_cash_pay
GROUP BY data_date,QUARTER,city_code,city_name,county_code,county_name,area_type_code;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
   
 
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
END;
/

DROP PROCEDURE IF EXISTS adm.loop_tjzh;

CREATE PROCEDURE adm.loop_tjzh(IN s_date DATE,IN edate DATE)
AS
  V_START_TIME    CHAR(19) := NOW();
  V_PROC_NAME     VARCHAR(80) := 'adm.loop_tjzh.PRC';
  V_STEP_ID       INT := 0;
  V_SQL_INSERT    LONGTEXT := ''; -- 插数语句SQL
  V_SQLTXT        LONGTEXT := ''; -- 执行SQL
BEGIN
  -- DECLARE  data_date DATE ;  -- 数据日期
  -- SET data_date =  '2018-01-01';
  WHILE s_date <= edate
  LOOP
	  V_STEP_ID := 1;
 DELETE FROM adm.trs_budget_summary_all_daily WHERE D_REPORTDATE = s_date;
  
	  V_STEP_ID := 2;
		-- (多维)库存分账户统计表
	-- 2018年3月30日之后取(含30日)
	INSERT INTO adm.trs_budget_summary_all_daily
(
D_REPORTDATE       ,          
S_TRECODE          ,          
GUOKU_DSCR         ,          
C_BUDGETLEVEL      ,          
S_BUDGETSUBJECTCODE,          
S_BUDGETSUBJECTNAME,          
THIS_PERIOD_AMT    ,          
LAST_PERIOD_AMT    ,          
THIS_PERIOD_YEARAMT,          
LAST_PERIOD_YEARAMT,          
UPDATE_DATE        
)
SELECT
  aa.d_reportdate AS D_REPORTDATE,
  aa.s_trecode AS S_TRECODE,
  dt1.guoku_dscr AS GUOKU_DSCR,
  aa.c_budgetlevel AS C_BUDGETLEVEL,
  aa.s_budgetsubjectcode AS S_BUDGETSUBJECTCODE,
  aa.s_budgetsubjectname AS S_BUDGETSUBJECTNAME,
  SUM(THIS_PERIOD_AMT)     AS THIS_PERIOD_AMT,
  SUM(LAST_PERIOD_AMT)     AS LAST_PERIOD_AMT,
  SUM(THIS_PERIOD_YEARAMT) AS THIS_PERIOD_YEARAMT,
  SUM(LAST_PERIOD_YEARAMT) AS LAST_PERIOD_YEARAMT,
 CURRENT_TIMESTAMP AS UPDATE_DATE
FROM
(
  -- -- 本期预算收入
         SELECT 
	 t1.d_reportdate AS D_REPORTDATE,
	 t1.s_trecode AS S_TRECODE,
	 t1.c_budgetlevel AS C_BUDGETLEVEL,
	 t1.s_budgetsubjectcode AS S_BUDGETSUBJECTCODE,
	 t1.s_budgetsubjectname AS S_BUDGETSUBJECTNAME,
	 SUM(t1.f_dayamt)  AS THIS_PERIOD_AMT,
	 SUM(t1.f_yearamt) AS THIS_PERIOD_YEARAMT,
	 0 		   AS LAST_PERIOD_AMT,
	 0 		   AS LAST_PERIOD_YEARAMT
	FROM edw.trs_d003_tr_budget_income t1
	WHERE  D_REPORTDATE = s_date
	AND S_TAXORGCODE NOT IN('000000000000','XXXXXXXXXXXX') 
	AND S_TRECODE <> '2200000000'
	GROUP BY
	t1.d_reportdate,
	t1.s_trecode,
	t1.c_budgetlevel,
	t1.s_budgetsubjectcode,
	t1.s_budgetsubjectname
	UNION ALL
	SELECT 
	 t1.d_reportdate AS D_REPORTDATE,
	 t1.s_trecode AS S_TRECODE,
	 t1.c_budgetlevel AS C_BUDGETLEVEL,
	 t1.s_budgetsubjectcode AS S_BUDGETSUBJECTCODE,
	 t1.s_budgetsubjectname AS S_BUDGETSUBJECTNAME,
	 SUM(t1.f_dayamt)  AS  THIS_PERIOD_AMT,
	 SUM(t1.f_yearamt) AS THIS_PERIOD_YEARAMT,
	 0 		   AS LAST_PERIOD_AMT,
	 0 		   AS LAST_PERIOD_YEARAMT
	FROM edw.trs_d003_tr_budget_income t1
	WHERE  D_REPORTDATE = s_date
	AND S_TAXORGCODE  IN('XXXXXXXXXXXX') 
	AND S_TRECODE = '2200000000'
	GROUP BY
	t1.d_reportdate,
	t1.s_trecode,
	t1.c_budgetlevel,
	t1.s_budgetsubjectcode,
	t1.s_budgetsubjectname
	UNION ALL
   -- -- 调拨收入（转移性收入）
	SELECT 
	 t1.d_reportdate AS D_REPORTDATE,
	 t1.s_trecode AS S_TRECODE,
	 t1.c_budgetlevel AS C_BUDGETLEVEL,
	 t1.s_budgetsubjectcode AS S_BUDGETSUBJECTCODE,
	 t1.s_budgetsubjectname AS S_BUDGETSUBJECTNAME,
	 SUM(t1.f_dayamt)  AS  THIS_PERIOD_AMT,
	 SUM(t1.f_yearamt) AS THIS_PERIOD_YEARAMT,
	 0 		   AS LAST_PERIOD_AMT,
	 0 		   AS LAST_PERIOD_YEARAMT
	FROM edw.trs_d003_tr_move_income t1
	WHERE  D_REPORTDATE = s_date
	GROUP BY
	t1.d_reportdate,
	t1.s_trecode,
	t1.c_budgetlevel,
	t1.s_budgetsubjectcode,
	t1.s_budgetsubjectname
	
        UNION ALL
        
  -- -- 预算收入
	SELECT 
	 s_date AS D_REPORTDATE,
	 t1.s_trecode AS S_TRECODE,
	 t1.c_budgetlevel AS C_BUDGETLEVEL,
	 t1.s_budgetsubjectcode AS S_BUDGETSUBJECTCODE,
	 t1.s_budgetsubjectname AS S_BUDGETSUBJECTNAME,
	 0                 AS THIS_PERIOD_AMT,
	 0                 AS THIS_PERIOD_YEARAMT,
	 SUM(t1.f_dayamt)  AS LAST_PERIOD_AMT,
	 SUM(t1.f_yearamt) AS LAST_PERIOD_YEARAMT
	FROM edw.trs_d003_tr_budget_income t1
	WHERE  D_REPORTDATE = DATE_SUB(s_date,INTERVAL 1 YEAR)
	AND S_TAXORGCODE NOT IN('000000000000','XXXXXXXXXXXX') 
	AND S_TRECODE <> '2200000000'
	GROUP BY
	t1.d_reportdate,
	t1.s_trecode,
	t1.c_budgetlevel,
	t1.s_budgetsubjectcode,
	t1.s_budgetsubjectname
	UNION ALL
	SELECT 
	 s_date AS D_REPORTDATE,
	 t1.s_trecode AS S_TRECODE,
	 t1.c_budgetlevel AS C_BUDGETLEVEL,
	 t1.s_budgetsubjectcode AS S_BUDGETSUBJECTCODE,
	 t1.s_budgetsubjectname AS S_BUDGETSUBJECTNAME,
	 0                 AS THIS_PERIOD_AMT,
	 0                 AS THIS_PERIOD_YEARAMT,
	 SUM(t1.f_dayamt)  AS LAST_PERIOD_AMT,
	 SUM(t1.f_yearamt) AS LAST_PERIOD_YEARAMT
	FROM edw.trs_d003_tr_budget_income t1
	WHERE  D_REPORTDATE = DATE_SUB(s_date,INTERVAL 1 YEAR)
	AND S_TAXORGCODE  IN('XXXXXXXXXXXX') 
	AND S_TRECODE = '2200000000'
	GROUP BY
	t1.d_reportdate,
	t1.s_trecode,
	t1.c_budgetlevel,
	t1.s_budgetsubjectcode,
	t1.s_budgetsubjectname
	UNION ALL
   -- -- 调拨收入（转移性收入）
	SELECT 
	 s_date AS D_REPORTDATE,
	 t1.s_trecode AS S_TRECODE,
	 t1.c_budgetlevel AS C_BUDGETLEVEL,
	 t1.s_budgetsubjectcode AS S_BUDGETSUBJECTCODE,
	 t1.s_budgetsubjectname AS S_BUDGETSUBJECTNAME,
	 0                 AS THIS_PERIOD_AMT,
	 0                 AS THIS_PERIOD_YEARAMT,
	 SUM(t1.f_dayamt)  AS LAST_PERIOD_AMT,
	 SUM(t1.f_yearamt) AS LAST_PERIOD_YEARAMT
	FROM edw.trs_d003_tr_move_income t1
	WHERE  D_REPORTDATE = DATE_SUB(s_date,INTERVAL 1 YEAR)
	GROUP BY
	t1.d_reportdate,
	t1.s_trecode,
	t1.c_budgetlevel,
	t1.s_budgetsubjectcode,
	t1.s_budgetsubjectname
) aa
JOIN
edw.cm_guoku_dimnsn dt1
ON aa.s_trecode = dt1.guoku_id
GROUP BY
  aa.d_reportdate,
  aa.s_trecode,
  dt1.guoku_dscr,
  aa.c_budgetlevel,
  aa.s_budgetsubjectcode,
  aa.s_budgetsubjectname 
UNION ALL
-- -- 支出部分
SELECT
  aa.d_reportdate AS D_REPORTDATE,
  aa.s_trecode AS S_TRECODE,
  dt1.guoku_dscr AS GUOKU_DSCR,
  dt2.level AS C_BUDGETLEVEL,
  aa.s_budgetsubjectcode AS S_BUDGETSUBJECTCODE,
  aa.s_budgetsubjectname AS S_BUDGETSUBJECTNAME,
  SUM(THIS_PERIOD_AMT)     AS THIS_PERIOD_AMT,
  SUM(LAST_PERIOD_AMT)     AS LAST_PERIOD_AMT,
  SUM(THIS_PERIOD_YEARAMT) AS THIS_PERIOD_YEARAMT,
  SUM(LAST_PERIOD_YEARAMT) AS LAST_PERIOD_YEARAMT,
  CURRENT_TIMESTAMP AS UPDATE_DATE
FROM
(
-- -- 正常期预算支出
	 SELECT 
	  t1.d_reportdate AS D_REPORTDATE,
	  t1.s_trecode AS S_TRECODE,
	  t1.s_budgetsubjectcode AS S_BUDGETSUBJECTCODE,
	  t1.s_budgetsubjectname AS S_BUDGETSUBJECTNAME,
	  SUM(t1.f_dayamt)         AS THIS_PERIOD_AMT,
	  SUM(t1.f_yearamt)        AS THIS_PERIOD_YEARAMT,
	  0 		           AS LAST_PERIOD_AMT,
	  0 		           AS LAST_PERIOD_YEARAMT
	FROM edw.trs_d003_tr_budget_payout t1
	WHERE  t1.d_reportdate = s_date
	GROUP BY
	t1.d_reportdate,
	t1.s_trecode,
	t1.s_budgetsubjectcode,
	t1.s_budgetsubjectname
  UNION ALL
-- -- 正常期预算支出
 SELECT 
  s_date AS D_REPORTDATE,
  t1.s_trecode AS S_TRECODE,
  t1.s_budgetsubjectcode AS S_BUDGETSUBJECTCODE,
  t1.s_budgetsubjectname AS S_BUDGETSUBJECTNAME,
  0                        AS THIS_PERIOD_AMT,
  0                        AS THIS_PERIOD_YEARAMT,
  SUM(t1.f_dayamt)         AS LAST_PERIOD_AMT,
  SUM(t1.f_yearamt)        AS LAST_PERIOD_YEARAMT
FROM edw.trs_d003_tr_budget_payout t1
WHERE  t1.d_reportdate = DATE_SUB(s_date,INTERVAL 1 YEAR)
GROUP BY
t1.d_reportdate,
t1.s_trecode,
t1.s_budgetsubjectcode,
t1.s_budgetsubjectname
) aa
JOIN
edw.cm_guoku_dimnsn dt1
ON aa.s_trecode = dt1.guoku_id
LEFT JOIN
edw.cm_guoku_dimnsn dt2
ON aa.s_trecode = dt2.guoku_id
GROUP BY
  aa.d_reportdate,
  aa.s_trecode,
  dt1.guoku_dscr,
  dt2.level,
  aa.s_budgetsubjectcode,
  aa.s_budgetsubjectname
  ;
 
 CALL etl.edw_proc_trace_log(DATE_FORMAT(s_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  s_date := DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END LOOP;
END;
/

DROP PROCEDURE IF EXISTS adm.py_cx_act_shop;

CREATE PROCEDURE adm.py_cx_act_shop(
     IN V_ACCT_ID    VARCHAR(8),
     IN V_ORG_ID     VARCHAR(14),
     IN V_PARM_TYPE  VARCHAR(1),
     IN V_AREA_ID    VARCHAR(14)
)
AS
    V_PROC_NAME     VARCHAR(80) := 'adm.py_cx_act_shop.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;
    P_RESULT        INT := 0;
    V_DATES         VARCHAR(20) := 0;
    V_STATE CHAR(1);
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 宋楠
     Name      : adm.py_cx_act_shop.PRC
     Functions : 广东省特约商户手机PAY、二维码、双免活跃商户统计表
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
    /* ------------------------------------------------------------------------ */
    /* EXCEPTION HANDLER  */
    P_RESULT := 0;
    V_DATES := CONCAT(V_ACCT_ID,'01');
    /* ------------------------------------------------------------------------ */
   DELETE FROM edw.py_cx_act_shop WHERE DATA_DATE = SUBSTR(V_ACCT_ID,1,6);
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    V_STEP_ID := 2;
  -- 广东省特约商户手机PAY、二维码、双免活跃商户统计表				
INSERT INTO edw.py_cx_act_shop(
DATA_DATE, -- 数据日期，账期
order_num, -- 序号                      
col_org_name, -- 收单机构名称    
shop_type, -- 商户类型     
shop_count_num,  -- 商户总数     
active_shop_num, -- 活跃商户数   
proportion       -- 占比         
)
SELECT     
DATA_DATE, -- 数据日期，账期
order_num, -- 序号                      
col_org_name, -- 收单机构名称    
shop_type, -- 商户类型     
shop_count_num,   -- 商户总数     
active_shop_num,	 -- 活跃商户数   
proportion       -- 占比         
FROM ods.py_cx_act_shop WHERE DATA_DATE=SUBSTR(V_ACCT_ID,1,6);
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
     V_STEP_ID := 3;
    DELETE FROM adm.py_cx_act_shop WHERE DATA_DATE = SUBSTR(V_ACCT_ID,1,6);
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
   V_STEP_ID := 4;
  -- 广东省特约商户手机PAY、二维码、双免活跃商户统计表					
INSERT INTO adm.py_cx_act_shop(
DATA_DATE, -- 数据日期，账期
order_num, -- 序号                      
col_org_name, -- 收单机构名称    
shop_type, -- 商户类型     
shop_count_num,  -- 商户总数     
active_shop_num, -- 活跃商户数   
proportion       -- 占比         
)
SELECT     
DATA_DATE, -- 数据日期，账期
order_num, -- 序号                      
col_org_name, -- 收单机构名称    
shop_type, -- 商户类型     
shop_count_num,   -- 商户总数     
active_shop_num,	 -- 活跃商户数   
proportion       -- 占比         
FROM edw.py_cx_act_shop WHERE DATA_DATE=SUBSTR(V_ACCT_ID,1,6);
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
     V_STEP_ID := 5;
    DELETE FROM adm.ana_cx_mth_act_shop WHERE month = SUBSTR(V_ACCT_ID,1,6);
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
   V_STEP_ID := 6;
  -- 广东省特约商户手机PAY、二维码、双免活跃商户统计表					
INSERT INTO adm.ana_cx_mth_act_shop
SELECT  
DATE_FORMAT(V_ACCT_ID,'%Y-%m-%d'),   
DATA_DATE, -- 数据日期，账期
'',                  
col_org_name, -- 收单机构名称    
case shop_type when '01' then '手机PAY商户'
               when '02' then '二维码商户' 
               when '03' then '双免商户' 
               else '手机PAY或二维码' end , -- 商户类型     
shop_count_num,   -- 商户总数     
active_shop_num	 -- 活跃商户数   
FROM edw.py_cx_act_shop WHERE DATA_DATE=SUBSTR(V_ACCT_ID,1,6);
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
    
    
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
END;
/

DROP PROCEDURE IF EXISTS adm.py_cx_advt_train;

CREATE PROCEDURE adm.py_cx_advt_train(
     IN V_ACCT_ID    VARCHAR(8),
     IN V_ORG_ID     VARCHAR(14),
     IN V_PARM_TYPE  VARCHAR(1),
     IN V_AREA_ID    VARCHAR(14)
)
AS
    V_PROC_NAME     VARCHAR(80) := 'adm.py_cx_advt_train.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;
    P_RESULT        INT := 0;
    V_DATES         VARCHAR(20) := 0;
    V_STATE CHAR(1);
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 杨开泰
     Name      : adm.py_cx_advt_train.PRC
     Functions : 表9 农村地区支付结算宣传培训情况
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
    /* ------------------------------------------------------------------------ */
    /* EXCEPTION HANDLER  */
    P_RESULT := 0;
    V_DATES := CONCAT(V_ACCT_ID,'01');
    /* ------------------------------------------------------------------------ */
    V_STEP_ID := 1;
    DELETE FROM edw.py_cx_advt_train WHERE DATA_DATE = SUBSTR(V_ACCT_ID,1,6);
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    -- ods汇总到edw，添加地区名称，区分地区类型  --插入农村数据
   V_STEP_ID := 2; 
  INSERT INTO edw.py_cx_advt_train
               (
                 DATA_DATE            , -- 数据日期，账期          
                 AREA_ID         , -- 地区代码                
                 AREA_NAME            , -- 地区名称                
                 ORG_ID               , -- 填报单位 
                 AREA_TYPE_CODE       , -- 地区类型编码1农村/2贫困 
                 PUBL_TIME           , -- 宣传次数
                 PUBL_NUM          , -- 发放宣传品数量     
                 OFF_TIME         , -- 非现场宣传    
                 TRAIN_TIME           , -- 培训次数  
                 TRAIN_NUM,       --  培训人次
                 REMARKS               -- 备注  
               )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.area_id,
    b.area_name,
    a.org_id,
    '1',
    a.coun_publ_time,
    a.coun_publ_num,
    a.coun_off_time,
    a.coun_train_time ,
    a.coun_train_num,
    a.remarks
    FROM ods.py_cx_advt_train  a
    INNER JOIN edw.py_cx_area_ncpk_code b
    ON a.area_id=b.area_id 
    WHERE b.area_type_code='1'  AND a.data_date=SUBSTR(V_ACCT_ID,1,6) ;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
   
    -- ods汇总到edw，添加地区名称，区分地区类型  --插入贫困数据
   V_STEP_ID := 3; 
  INSERT INTO edw.py_cx_advt_train
               (
                 DATA_DATE            , -- 数据日期，账期          
                 AREA_ID         , -- 地区代码                
                 AREA_NAME            , -- 地区名称                
                 ORG_ID               , -- 填报单位 
                 AREA_TYPE_CODE       , -- 地区类型编码1农村/2贫困 
                 PUBL_TIME           , -- 宣传次数
                 PUBL_NUM          , -- 发放宣传品数量     
                 OFF_TIME         , -- 非现场宣传    
                 TRAIN_TIME           , -- 培训次数  
                 TRAIN_NUM,       --  培训人次
                 REMARKS               -- 备注  
               )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.area_id,
    b.area_name,
    a.org_id,
    '2',
    a.pove_publ_time,
    a.pove_publ_num,
    a.pove_off_time,
    a.pove_train_time ,
    a.pove_train_num,
    a.remarks
    FROM ods.py_cx_advt_train  a
    INNER JOIN edw.py_cx_area_ncpk_code b
    ON a.area_id=b.area_id 
    WHERE b.area_type_code='2'  AND a.data_date=SUBSTR(V_ACCT_ID,1,6) ;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
 
  V_STEP_ID := 4;
    DELETE FROM adm.py_cx_advt_train WHERE DATA_DATE = SUBSTR(V_ACCT_ID,1,6);
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    -- edw汇总到adm，生成报表展示adm表，同时生成 异动分析结果表
   V_STEP_ID := 5;
  INSERT INTO adm.py_cx_advt_train
               (
                 DATA_DATE            , -- 数据日期，账期          
                 AREA_ID              , -- 地区代码                
                 AREA_NAME            , -- 地区名称                 
                 ORG_ID               , -- 填报单位   
                 ORG_NAME             , -- 填报单位名称           
                 AREA_TYPE_CODE       , -- 地区类型编码1农村/2贫困 
                 COMPARE_TYPE_CODE    , -- 对比类型编码1同比/2环比
                 PUBL_TIME           , -- 宣传次数  
                 COMPARE_PUBL_TIME, -- 对比宣传次数
                 PUBL_NUM   , -- 发放宣传品数量  
                 COMPARE_PUBL_NUM,-- 对比发放宣传品数量
                 OFF_TIME  , -- 非现场宣传   
                 COMPARE_OFF_TIME,-- 对比非现场宣传
                 TRAIN_TIME         , -- 培训次数   
                 COMPARE_TRAIN_TIME, -- 对比培训次数
                 TRAIN_NUM , -- 培训人次   
                 COMPARE_TRAIN_NUM           , -- 对比培训人次  
                 REMARKS               -- 备注  
               )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.area_id,
    a.area_name,
    a.org_id,
    c.org_dscr,
    a.area_type_code,
    '1' AS COMPARE_TYPE_CODE,
    a.publ_time,
    b.publ_time,
    a.publ_num,
    b.publ_num,
    a.off_time,
    b.off_time,
    a.train_time ,
    b.train_time,
    a.train_num,
    b.train_num,
    a.remarks
    FROM edw.py_cx_advt_train  a
    LEFT JOIN 
    (SELECT * FROM edw.py_cx_advt_train 
    WHERE DATA_DATE=DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 12 MONTH),'%Y%m') )b
    ON a.area_id=b.area_id AND a.org_id=b.org_id AND  a.area_type_code=b.area_type_code 
    left join dmcode.t_big_org c
    on a.org_id=c.org_id
    WHERE a.data_date=SUBSTR(V_ACCT_ID,1,6) ;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
 
  V_STEP_ID := 6;
 INSERT INTO adm.py_cx_advt_train
               (
                 DATA_DATE            , -- 数据日期，账期          
                 AREA_ID              , -- 地区代码                
                 AREA_NAME            , -- 地区名称                 
                 ORG_ID               , -- 填报单位   
                 ORG_NAME             , -- 填报单位名称           
                 AREA_TYPE_CODE       , -- 地区类型编码1农村/2贫困 
                 COMPARE_TYPE_CODE    , -- 对比类型编码1同比/2环比
                 PUBL_TIME           , -- 宣传次数  
                 COMPARE_PUBL_TIME, -- 对比宣传次数
                 PUBL_NUM   , -- 发放宣传品数量  
                 COMPARE_PUBL_NUM,-- 对比发放宣传品数量
                 OFF_TIME  , -- 非现场宣传   
                 COMPARE_OFF_TIME,-- 对比非现场宣传
                 TRAIN_TIME         , -- 培训次数   
                 COMPARE_TRAIN_TIME, -- 对比培训次数
                 TRAIN_NUM , -- 培训人次   
                 COMPARE_TRAIN_NUM           , -- 对比培训人次                     
                 REMARKS               -- 备注  
               )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.area_id,
    a.area_name,
    a.org_id,
    c.org_dscr,
    a.area_type_code,
    '2' AS COMPARE_TYPE_CODE,
    a.publ_time,
    b.publ_time,
    a.publ_num,
    b.publ_num,
    a.off_time,
    b.off_time,
    a.train_time ,
    b.train_time,
    a.train_num,
    b.train_num,
    a.remarks
    FROM edw.py_cx_advt_train  a
    LEFT JOIN 
    (SELECT * FROM edw.py_cx_advt_train 
    WHERE DATA_DATE=DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 3 MONTH),'%Y%m') )b
    ON a.area_id=b.area_id AND a.org_id=b.org_id AND  a.area_type_code=b.area_type_code 
    LEFT JOIN dmcode.t_big_org c
    ON a.org_id=c.org_id
    WHERE a.data_date=SUBSTR(V_ACCT_ID,1,6) ;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
END;
/

