DROP PROCEDURE IF EXISTS adm.py_cx_cash_servinfo;

CREATE PROCEDURE adm.py_cx_cash_servinfo(
     IN  V_ACCT_ID VARCHAR(8)
    ,OUT P_RESULT    INT
)
AS
    V_PROC_NAME     VARCHAR(80) := 'adm.py_cx_cash_servinfo.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;
    P_RESULT        INT := 0;
    V_DATES         VARCHAR(20) := 0;
    V_STATE CHAR(1);
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 杨开泰
     Name      : adm.py_cx_cash_servinfo.PRC
     Functions : 服务网点数据入库,服务网点多维生成
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
    /* ------------------------------------------------------------------------ */
    /* EXCEPTION HANDLER  */
    P_RESULT := 0;
    V_DATES := V_ACCT_ID;
    /* ------------------------------------------------------------------------ */
     V_STEP_ID := 1; 
DELETE FROM edw.py_cx_cash_servinfo WHERE insert_type='2';
INSERT INTO edw.py_cx_cash_servinfo
SELECT
 NULL,
 b.put_org_type, -- 布设网点机构类型
 b.org_id, -- 网点代码/商户号
 a.mar_num, -- 机具编号
 b.put_org_name, -- 布设网点机构名称
 b.put_org_id , -- 布设网点机构代码
 b.org_type	,	-- 网点类型
 b.org_name,		-- 网点名称/商户名称
 b.merchant_card_num,	-- 商户卡号
 b.area_no_id AS VILLAGE_CODE,	-- 	所在农村地区代码
 b.address,	-- 	所在农村地区名称
 c.area_no_id ,  -- 所在地区代码
 c.area_dscr,  -- 所在地区名称
 c.area_no_id_2, -- 所在市代码
 c.area_dscr_2,  -- 所在市名称
 b.address	,	-- 详细地址
 b.longitude,	-- 	地址坐标经度
 b.latitude	,	-- 地址坐标纬度
 b.site_learder,		-- 网点负责人
 b.site_learder_id,	-- 负责人身份证号
 b.tel	,	-- 联系电话
 b.is_load_electricity	,	-- 是否加载电商功能
 b.is_open_interbank,	-- 	是否开通跨行功能
 b.accord_door,	-- 	门头照
 b.create_date,	-- 	建成日期
 b.abolish_date,	-- 废止日期
 b.update_date,	-- 	更新日期
 a.mar_state,
 a.mar_type,
 '2'
  FROM (SELECT * FROM ods.py_cx_website_info
GROUP BY ORG_ID
HAVING DATA_DATE=MAX(DATA_DATE)
) b
 LEFT JOIN (SELECT * FROM ods.py_cx_tools_info
GROUP BY ORG_ID
HAVING DATA_DATE=MAX(DATA_DATE))  a ON 
 b.org_id=a.org_id
 LEFT JOIN dmcode.t_org_biz_lvl l
 ON b.put_org_name=l.org_dscr
 LEFT JOIN dmcode.t_area_code c
 ON SUBSTR(b.area_no_id,1,6)=c.area_no_id ;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
   V_STEP_ID := 2; 
     TRUNCATE TABLE adm.py_cx_dw_cash_servinfo_tmp;
INSERT INTO adm.py_cx_dw_cash_servinfo_tmp   
SELECT SUBSTR(INSTALL_DATE,1,6) AS data_date,
VILLAGE_CODE AS AREA_NO,
ORG_NUM AS ORG_NO,
SUBSTR(ORG_NUM,1,6) AS BANK_TYPE,
CASE WHEN STATE='1' THEN '正常' ELSE '撤销' END AS STATE,
COUNT(shop_num) AS WD_NUM
FROM edw.py_cx_cash_servinfo
GROUP BY SUBSTR(INSTALL_DATE,1,6),
VILLAGE_CODE,ORG_NUM,SUBSTR(ORG_NUM,1,6),CASE WHEN STATE='1' THEN '正常' ELSE '撤销' END ;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
       
          V_STEP_ID := 3; 
TRUNCATE TABLE adm.py_cx_dw_cash_servinfo  ;
INSERT INTO adm.py_cx_dw_cash_servinfo
(DATA_DATE, -- 数据日期
AREA_NO,-- 地区编码
ORG_NO,-- 金融机构编码
BANK_TYPE,-- 银行性质编码
STATE,-- 状态
WD_NUM,-- 服务点数量
TQ_WD_NUM,-- 同期服务点数量
SQ_WD_NUM)-- 上期服务点数量)
SELECT a.*,IFNULL(b.wd_num,0),IFNULL(c.wd_num,0)
FROM adm.py_cx_dw_cash_servinfo_tmp a
LEFT JOIN adm.py_cx_dw_cash_servinfo_tmp b
ON a.area_no=b.area_no AND a.org_no=b.org_no 
AND a.bank_type=b.bank_type AND a.state=b.state AND DATE_FORMAT(DATE_SUB(CONCAT(a.data_date,'01'),INTERVAL 1 MONTH),'%Y%m')=b.data_date
LEFT JOIN adm.py_cx_dw_cash_servinfo_tmp c
ON a.area_no=c.area_no AND a.org_no=c.org_no 
AND a.bank_type=c.bank_type AND a.state=c.state AND DATE_FORMAT(DATE_SUB(CONCAT(a.data_date,'01'),INTERVAL 1 MONTH),'%Y%m')=c.data_date ;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
       
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
END;
/

