DROP PROCEDURE IF EXISTS adm.py_cx_envbld_rural_cards_mkt;

CREATE PROCEDURE adm.py_cx_envbld_rural_cards_mkt(
     IN V_ACCT_ID    VARCHAR(8),
     IN V_ORG_ID     VARCHAR(14),
     IN V_PARM_TYPE  VARCHAR(1),
     IN V_AREA_ID    VARCHAR(14)
)
AS
    V_PROC_NAME     VARCHAR(80) := 'edw.py_cx_envbld_rural_cards_mkt.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;
    P_RESULT        INT := 0;
    V_DATES         VARCHAR(20) := 0;
    V_STATE CHAR(1);
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 宋楠
     Name      : edw.py_cx_envbld_rural_cards_mkt.PRC
     Functions : 表5农村地区银行卡受理市场建设情况
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
    /* ------------------------------------------------------------------------ */
    /* EXCEPTION HANDLER  */
    P_RESULT := 0;
    V_DATES := CONCAT(V_ACCT_ID,'01');
    /* ------------------------------------------------------------------------ */
    V_STEP_ID := 1;
    DELETE FROM edw.py_cx_envbld_rural_cards_mkt WHERE DATA_DATE = SUBSTR(V_ACCT_ID,1,6);
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
   V_STEP_ID := 2; 
INSERT INTO edw.py_cx_envbld_rural_cards_mkt (
DATA_DATE      ,-- 数据日期，账期                                                                                         
AREA_ID        ,-- 地区代码                                                                                               
AREA_NAME      ,-- 地区名称                                                                                               
ORG_ID         ,-- 填报单位                                                                                               
AREA_TYPE_CODE ,-- 地区类型编码1农村/2贫困                                                                                
BCARD_TYPE_DSCR,-- 银行卡业务类型描述(04ATM业务量,05POS业务量,06其他银行卡受理终端业务量,10各类银行卡受理终端业务量合计)  
SPECIAL_MERCH  ,-- 特约商户（户）                                                                                         
NUMBER         ,-- 数量(台)                                                                                               
COUNT          ,-- 笔数（万笔）                                                                                           
MONEY          ,-- 金额（万元）                                                                                           
TRANSFER_PHONE , -- 其中转账电话（台）                                                                                     
REMARKS         --  备注                                                                                                   
 )
SELECT 
 m.data_date 
,m.area_id 
,b.area_name     
,m.org_id 
,'1'  
,'10'   
,m.special_merch_country
,m.sum_number_country
,m.sum_count_country 
,m.sum_monry_country
,0 
,m.remarks 
FROM ods.py_cx_envbld_rural_cards_mkt1 m LEFT JOIN edw.py_cx_area_ncpk_code b
 ON m.area_id=b.area_id    
