                 ORG_ID               , -- 填报单位   
                 ORG_NAME             , -- 填报单位名称           
                 AREA_TYPE_CODE       , -- 地区类型编码1农村/2贫困 
                 COMPARE_TYPE_CODE    , -- 对比类型编码1同比/2环比
                 PROVINCE_SUPPERT           , -- 省支持金额（万元）  
                 COMPARE_PROVINCE_SUPPERT, -- 对比省支持金额（万元）
                 CITY_SUPPERT   , -- 市支持金额（万元）
                 COMPARE_CITY_SUPPERT,-- 对比市支持金额（万元）
                 COUNTY_SUPPERT  , -- 县支持金额（万元）
                 COMPARE_COUNTY_SUPPERT,-- 对比县支持金额（万元）            
                 REMARKS               -- 备注  
               )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.area_id,
    a.area_name,
    a.org_id,
    c.org_dscr,
    a.area_type_code,
    '2' AS COMPARE_TYPE_CODE,
    a.province_suppert,
    b.province_suppert,
    a.city_suppert,
    b.city_suppert,
    a.county_suppert,
    b.county_suppert,
    a.remarks
    FROM edw.py_cx_env_support  a
    LEFT JOIN 
    (SELECT * FROM edw.py_cx_env_support 
    WHERE DATA_DATE=DATE_FORMAT(DATE_SUB(V_ACCT_ID,INTERVAL 3 MONTH),'%Y%m') )b
    ON a.area_id=b.area_id AND a.org_id=b.org_id AND  a.area_type_code=b.area_type_code 
    LEFT JOIN dmcode.t_big_org c
    ON a.org_id=c.org_id
    WHERE a.data_date=SUBSTR(V_ACCT_ID,1,6) ;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
END;
/

DROP PROCEDURE IF EXISTS adm.py_cx_map_fwdcity;

CREATE PROCEDURE adm.py_cx_map_fwdcity(
     IN V_ACCT_ID    VARCHAR(8),
     IN V_ORG_ID     VARCHAR(14),
     IN V_PARM_TYPE  VARCHAR(1),
     IN V_AREA_ID    VARCHAR(14)
)
AS
    V_PROC_NAME     VARCHAR(80) := 'adm.py_cx_map_fwdcity.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;
    P_RESULT        INT := 0;
    V_DATES         VARCHAR(20) := 0;
    V_STATE CHAR(1);
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 杨开拓
     Name      : adm.py_cx_map_fwdcity.PRC
     Functions : 城市地图语句
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
    /* ------------------------------------------------------------------------ */
    /* EXCEPTION HANDLER  */
    P_RESULT := 0;
    V_DATES := CONCAT(V_ACCT_ID,'01');
    /* ------------------------------------------------------------------------ */
     V_STEP_ID := 1;
    DELETE FROM adm.py_cx_map_fwdcity WHERE DATA_DATE = SUBSTR(V_ACCT_ID,1,6);
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
   V_STEP_ID := 2;
  -- 城市地图语句					
 INSERT INTO adm.py_cx_map_fwdcity 
 SELECT a.data_date,
 CASE WHEN a.area_id IN ('440117','440118') THEN '440100' ELSE a.area_id END,
 CASE WHEN a.area_id IN ('440117','440118') THEN '广州市' ELSE a.area_name END,
 SUM(a.count), 
  SUM(b.web_count),
 SUM(b.web_money),
 SUM(b.mob_count),
 SUM(b.mob_money),
 SUM(b.tel_count),
 SUM(b.tel_money),
 SUM(b.yhk_count),
 SUM(b.yhk_money),
 SUM(b.pj_count),
 SUM(b.pj_money),
 SUM(b.ds_count),
 SUM(b.ds_money),
 SUM(c.gr_zh),
 SUM(d.debit_card),
 SUM(d.credit_card),
 SUM(d.debit_credit) 
  FROM (SELECT SUM(COUNT) AS COUNT ,data_date,area_id,area_name FROM edw.py_cx_envbld_hf_wd    WHERE area_type_code=1  AND FARM_DRAWAL_CODE='10'
  GROUP BY data_date,area_id,area_name )a
LEFT JOIN (SELECT  data_date,area_id,
SUM(CASE WHEN PAY_CODE='07' THEN COUNT ELSE 0 END) AS web_count,
SUM(CASE WHEN PAY_CODE='07' THEN MONEY ELSE 0 END) AS web_money,
SUM(CASE WHEN PAY_CODE='08' THEN COUNT ELSE 0 END) AS mob_count,
SUM(CASE WHEN PAY_CODE='08' THEN MONEY ELSE 0 END) AS mob_money,
SUM(CASE WHEN PAY_CODE='09' THEN COUNT ELSE 0 END) AS tel_count,
SUM(CASE WHEN PAY_CODE='09' THEN MONEY ELSE 0 END) AS tel_money,
SUM(CASE WHEN BUSINESS_CODE='01' THEN COUNT ELSE 0 END) AS yhk_COUNT,
SUM(CASE WHEN BUSINESS_CODE='01' THEN MONEY ELSE 0 END) AS yhk_money,
SUM(CASE WHEN BUSINESS_CODE='02' THEN COUNT ELSE 0 END) AS pj_count,
SUM(CASE WHEN BUSINESS_CODE='02' THEN MONEY ELSE 0 END) AS pj_money,
SUM(CASE WHEN BUSINESS_CODE='03' THEN COUNT ELSE 0 END) AS ds_count,
SUM(CASE WHEN BUSINESS_CODE='03' THEN MONEY*10000 ELSE 0 END) AS ds_money
FROM edw.py_cx_envbld_rural_ncpi_tltyp  WHERE area_type_code=1 
 GROUP BY   data_date,area_id) b
ON a.data_date=b.data_date AND a.area_id=b.area_id
LEFT JOIN (SELECT data_date,area_id,SUM(PERSONAL_BANK_1+PERSONAL_BANK_2+PERSONAL_BANK_3) AS gr_zh
 FROM edw.py_cx_envbld_rural_bnk_accts  
  WHERE area_type_code=1  
GROUP BY data_date,area_id ) c
ON a.data_date=c.data_date AND a.area_id=c.area_id
LEFT JOIN (SELECT data_date,area_id,SUM(DEBIT_CARD) AS DEBIT_CARD,SUM(CREDIT_CARD) AS CREDIT_CARD,SUM(DEBIT_CREDIT) AS DEBIT_CREDIT
 FROM edw.py_cx_envbld_rural_bnk_cards 
  WHERE area_type_code=1  
 GROUP BY data_date,area_id) d
 ON a.data_date=d.data_date AND a.area_id=d.area_id 
 where a.data_date = SUBSTR(V_ACCT_ID,1,6)
 GROUP BY a.data_date,
 CASE WHEN a.area_id IN ('440117','440118') THEN '440100' ELSE a.area_id END, 
 CASE WHEN a.area_id IN ('440117','440118') THEN '广州市' ELSE a.area_name END ;
 
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
   
 
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
END;
/

