 /* ------------------------------------------------------------------------ */
    
    
    
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
END;
/

DROP PROCEDURE IF EXISTS adm.py_cx_mth_cash_active_area;

CREATE PROCEDURE adm.py_cx_mth_cash_active_area(
     IN  V_ACCT_ID VARCHAR(8)
    ,OUT P_RESULT    INT
)
AS
    V_PROC_NAME     VARCHAR(80) := 'adm.py_cx_mth_cash_active_area.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
    

    
    
    P_RESULT := 0;
    
    V_STEP_ID := 1;
    DELETE FROM adm.py_cx_mth_cash_active_area ;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
   V_STEP_ID := 2;
 INSERT INTO adm.py_cx_mth_cash_active_area 
SELECT 
  a.trade_date,
  b.area_code,
  b.city_code,
  SUM(num) AS num,
  SUM(act_num) AS act_num,
  SUM(no_act_num) AS no_act_num 
FROM
  (SELECT 
    trade_date,
    village_code,
    '0' AS num,
    COUNT(DISTINCT shop_num) AS act_num,
    '0' AS no_act_num 
  FROM
    adm.px_cx_mth_cash_servinfo 
  WHERE trade_num >= 20 
  GROUP BY trade_date,
    village_code,TRADE_TYPE 
  UNION
  ALL 
  SELECT 
    trade_date,
    village_code,
    '0' AS num,
    '0'AS act_num,
    COUNT(DISTINCT shop_num) AS no_act_num 
  FROM
    adm.px_cx_mth_cash_servinfo 
  GROUP BY village_code,
    trade_date 
  HAVING (sum(trade_num) < 5)
 UNION ALL
 SELECT 
    trade_date,
    village_code,
    COUNT(DISTINCT shop_num) AS num,
    '0'AS act_num,
    '0' AS no_act_num 
  FROM
    adm.px_cx_mth_cash_servinfo 
  WHERE  trade_num < 20 
  GROUP BY village_code,
    trade_date 
  HAVING MAX(trade_num) > 5  
  ) a 
  INNER JOIN edw.py_cx_area_code b 
    ON a.village_code = b.nbh_code
    WHERE  a.trade_date=(SELECT MAX(trade_date) FROM adm.px_cx_mth_cash_servinfo )
GROUP BY a.trade_date,
  b.area_code,
  b.city_code ;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
END;
/

DROP PROCEDURE IF EXISTS adm.py_cx_mth_cash_servinfo_active;

CREATE PROCEDURE adm.py_cx_mth_cash_servinfo_active(
     IN  P_DATA_DATE VARCHAR(8)
    ,OUT P_RESULT    INT
)
AS
    V_PROC_NAME     VARCHAR(80) := 'edw.py_cx_mth_cash_servinfo_active.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN

    
    
    P_RESULT := 0;
    
    V_STEP_ID := 1;
    DELETE FROM adm.py_cx_mth_cash_servinfo_active WHERE trade_date = SUBSTR(P_DATA_DATE,1,6);
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    V_STEP_ID := 2;
    
INSERT INTO adm.py_cx_mth_cash_servinfo_active
SELECT  DISTINCT
trade_date,
s.shop_num,
s.area_dscr_2,
s.area_dscr,
'',
s.village_code,
s.org_name,
s.address,
s.service_point_lon,
s.service_point_la,
CASE WHEN a.shop_num IS NULL THEN 0 ELSE a.active_type END AS active_type
FROM edw.py_cx_cash_servinfo s
LEFT JOIN 
(SELECT DISTINCT
SUBSTR(trade_date, 1,6) AS trade_date,
shop_num AS shop_num,    
village_code,
'1' AS active_type
FROM adm.px_cx_mth_cash_servinfo   WHERE trade_num>=30  
UNION ALL
SELECT
trade_date,  
shop_num,    
village_code,
'2' AS active_type
FROM adm.px_cx_mth_cash_servinfo    GROUP BY village_code,SUBSTR(trade_date,1,6),shop_num HAVING MAX(trade_num)<10) a ON a.shop_num=s.shop_num 
WHERE  s.shop_num IS NOT NULL AND s.shop_num!='' AND a.trade_date!='' AND a.trade_date IS NOT NULL; 
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
       CALL etl.edw_proc_error_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
END;
/

