    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    V_STEP_ID := 2;
  INSERT INTO edw.py_cx_pay_change_tj
SELECT DISTINCT
  t.data_date, -- '数据日期，账期'
  c.city_code, -- '地区代码'
t.model_area,	-- '示范地区'
case when t.ind_name like '%其他%' then '其他' else SUBSTR(t.ind_name,2) end,	-- '行业名称'
t.new_add_num,	-- '本月新增项目个数'
t.tot_add_num,	-- '累计项目个数'
t.tot_add_name,	-- '累计项目名称'
