t.new_trade_amount,	-- '该场景本月交易金额'
t.tot_trade_num,	-- '该场景累计交易笔数'
t.tot_trade_amount	-- '该场景累计交易金额'
FROM ods.py_cx_pay_change_tj t
LEFT JOIN edw.py_cx_area_code c
 ON SUBSTR(t.model_area,1,2)=SUBSTR(c.city_name,1,2)
