DROP PROCEDURE IF EXISTS adm.py_cx_trade_check_info;

CREATE PROCEDURE adm.py_cx_trade_check_info(
     IN  P_DATA_DATE VARCHAR(8)
    ,OUT P_RESULT    INT
)
AS
    V_PROC_NAME     VARCHAR(80) := 'edw.py_cx_trade_check_info.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN

    
    
    P_RESULT := 0;
    
    V_STEP_ID := 1;
    DELETE FROM adm.py_cx_trade_check_info WHERE data_date = SUBSTR(P_DATA_DATE,1,6);
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    V_STEP_ID := 2;
INSERT INTO  adm.py_cx_trade_check_info 
SELECT SUBSTR(P_DATA_DATE,1,6),a.*,
IFNULL(b.serv_point,0),
IFNULL(c.trade_count/(b.serv_point*DATEDIFF(CONCAT(data_date,'01'),DATE_FORMAT(DATE_SUB(CONCAT(data_date,'01'),INTERVAL 1 MONTH),'%Y%m%d'))),0),
IFNULL(c.trade_amout/(b.serv_point*DATEDIFF(CONCAT(data_date,'01'),DATE_FORMAT(DATE_SUB(CONCAT(data_date,'01'),INTERVAL 1 MONTH),'%Y%m%d'))),0),
IFNULL(c.trade_count,0),
IFNULL(c.trade_amout,0),
IFNULL(e.termina_num/d.termina_num*100,0),
'1'
FROM 
(SELECT DISTINCT AREA_CODE,AREA_NAME,CITY_CODE,CITY_NAME FROM edw.py_cx_area_code)  a
LEFT JOIN  
(SELECT   
a.area_no_id  ,
a.area_dscr  ,
a.area_no_id_2  ,
a.area_dscr_2  ,
COUNT(1) AS serv_point
FROM  edw.py_cx_cash_servinfo a
GROUP BY a.area_no_id  ,
a.area_dscr  ,
a.area_no_id_2  ,
a.area_dscr_2 ) b
ON a.area_code=b.area_no_id
LEFT JOIN 
(SELECT data_date,area_code,area_name,
trade_amout,
trade_count 
 FROM adm.py_cx_area_tradeinfo
 WHERE data_date=SUBSTR(P_DATA_DATE,1,6) ) c
ON  a.area_code=c.area_code
LEFT JOIN 
(SELECT  COUNT(DISTINCT TERMINA_NUM) AS TERMINA_NUM ,area_no_id 
FROM edw.py_cx_cash_servinfo
GROUP BY area_no_id) d
ON a.area_code=d.area_no_id
LEFT JOIN  (SELECT COUNT(DISTINCT a.termina_num ) AS TERMINA_NUM ,a.area_no_id
FROM edw.py_cx_cash_servinfo a 
INNER JOIN (
SELECT TERMINA_NUM,SHOP_NUM FROM edw.py_cx_cash_tradelog 
WHERE SUBSTR(TRADE_DATE,1,6)=SUBSTR(P_DATA_DATE,1,6)  ) b
ON a.termina_num=b.termina_num AND a.shop_num=b.shop_num  
GROUP BY a.area_no_id) e
ON a.area_code=e.area_no_id;
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
  
    
    V_STEP_ID := 3;
INSERT INTO  adm.py_cx_trade_check_info 
SELECT SUBSTR(P_DATA_DATE,1,6),a.*,
IFNULL(b.serv_point,0),
IFNULL(c.trade_count/(b.serv_point*DATEDIFF(CONCAT(data_date,'01'),DATE_FORMAT(DATE_SUB(CONCAT(data_date,'01'),INTERVAL 1 MONTH),'%Y%m%d'))),0),
IFNULL(c.trade_amout/(b.serv_point*DATEDIFF(CONCAT(data_date,'01'),DATE_FORMAT(DATE_SUB(CONCAT(data_date,'01'),INTERVAL 1 MONTH),'%Y%m%d'))),0),
IFNULL(c.trade_count,0),
IFNULL(c.trade_amout,0),
IFNULL(e.termina_num/d.termina_num*100,0),
'1'  
FROM 
(SELECT DISTINCT AREA_CODE,AREA_NAME,CITY_CODE,CITY_NAME FROM edw.py_cx_area_code)  a
LEFT JOIN  
(SELECT  
a.area_no_id_2  ,
a.area_dscr_2  ,
COUNT(1) AS serv_point
FROM  edw.py_cx_cash_servinfo a
GROUP BY
a.area_no_id_2  ,
a.area_dscr_2 ) b
ON a.city_code=b.area_no_id_2
LEFT JOIN 
(SELECT data_date,city_code,city_name,
trade_amout,
trade_count 
 FROM adm.py_cx_area_tradeinfo
 WHERE data_date=SUBSTR(P_DATA_DATE,1,6) ) c
ON  a.city_code=c.city_code
LEFT JOIN 
(SELECT  COUNT(DISTINCT TERMINA_NUM) AS TERMINA_NUM ,area_no_id_2 
FROM edw.py_cx_cash_servinfo
GROUP BY area_no_id_2) d
ON a.city_code=d.area_no_id_2
LEFT JOIN  (SELECT COUNT(DISTINCT a.termina_num ) AS TERMINA_NUM ,a.area_no_id_2
FROM edw.py_cx_cash_servinfo a 
INNER JOIN (
SELECT TERMINA_NUM,SHOP_NUM FROM edw.py_cx_cash_tradelog 
WHERE SUBSTR(TRADE_DATE,1,6)=SUBSTR(P_DATA_DATE,1,6)  ) b
ON a.termina_num=b.termina_num AND a.shop_num=b.shop_num  
GROUP BY a.area_no_id_2) e
ON a.city_code=e.area_no_id_2;
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
V_STEP_ID := 4;
 
INSERT INTO  adm.py_cx_trade_check_info 
SELECT SUBSTR(P_DATA_DATE,1,6),a.*,
IFNULL(b.serv_point,0),
IFNULL(c.trade_count/(b.serv_point*DATEDIFF(CONCAT(SUBSTR(P_DATA_DATE,1,6),'01'),DATE_FORMAT(DATE_SUB(CONCAT(SUBSTR(P_DATA_DATE,1,6),'01'),INTERVAL 3 MONTH),'%Y%m%d'))),0),
IFNULL(c.trade_amout/(b.serv_point*DATEDIFF(CONCAT(SUBSTR(P_DATA_DATE,1,6),'01'),DATE_FORMAT(DATE_SUB(CONCAT(SUBSTR(P_DATA_DATE,1,6),'01'),INTERVAL 3 MONTH),'%Y%m%d'))),0),
IFNULL(c.trade_count,0),
IFNULL(c.trade_amout,0),
IFNULL(e.termina_num/d.termina_num*100,0),
'2'
FROM 
(SELECT DISTINCT AREA_CODE,AREA_NAME,CITY_CODE,CITY_NAME FROM edw.py_cx_area_code)  a
LEFT JOIN  
(SELECT   
a.area_no_id  ,
a.area_dscr  ,
a.area_no_id_2  ,
a.area_dscr_2  ,
COUNT(1) AS serv_point
FROM  edw.py_cx_cash_servinfo a
GROUP BY a.area_no_id  ,
a.area_dscr  ,
a.area_no_id_2  ,
a.area_dscr_2 ) b
ON a.area_code=b.area_no_id
LEFT JOIN 
(SELECT  area_code,area_name,
SUM(trade_amout) AS trade_amout,
SUM(trade_count) AS  trade_count
 FROM adm.py_cx_area_tradeinfo
 WHERE SUBSTR(data_date,1,6) 
 IN (SELECT b.month FROM (SELECT QUARTER FROM edw.py_cx_dim_date WHERE MONTH=SUBSTR(P_DATA_DATE,1,6)) a 
LEFT JOIN edw.py_cx_dim_date b
ON a.quarter=b.quarter 
WHERE SUBSTR(b.month,1,4)=SUBSTR(P_DATA_DATE,1,4))
 GROUP BY  area_code,area_name) c
ON  a.area_code=c.area_code
LEFT JOIN 
(SELECT  COUNT(DISTINCT TERMINA_NUM) AS TERMINA_NUM ,area_no_id 
FROM edw.py_cx_cash_servinfo
GROUP BY area_no_id) d
ON a.area_code=d.area_no_id
LEFT JOIN  (SELECT COUNT(DISTINCT a.termina_num ) AS TERMINA_NUM ,a.area_no_id
FROM edw.py_cx_cash_servinfo a 
INNER JOIN (
SELECT TERMINA_NUM,SHOP_NUM FROM edw.py_cx_cash_tradelog 
WHERE SUBSTR(trade_date,1,6) IN (SELECT b.month FROM (SELECT QUARTER FROM edw.py_cx_dim_date WHERE MONTH=SUBSTR(P_DATA_DATE,1,6)) a 
LEFT JOIN edw.py_cx_dim_date b
ON a.quarter=b.quarter 
WHERE SUBSTR(b.month,1,4)=SUBSTR(P_DATA_DATE,1,4))  ) b
ON a.termina_num=b.termina_num AND a.shop_num=b.shop_num  
GROUP BY a.area_no_id) e
ON a.area_code=e.area_no_id;
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
V_STEP_ID := 5;
INSERT INTO  adm.py_cx_trade_check_info 
SELECT SUBSTR(P_DATA_DATE,1,6),a.*,
IFNULL(b.serv_point,0),
IFNULL(c.trade_count/(b.serv_point*DATEDIFF(CONCAT(SUBSTR(P_DATA_DATE,1,6),'01'),DATE_FORMAT(DATE_SUB(CONCAT(SUBSTR(P_DATA_DATE,1,6),'01'),INTERVAL 3 MONTH),'%Y%m%d'))),0),
IFNULL(c.trade_amout/(b.serv_point*DATEDIFF(CONCAT(SUBSTR(P_DATA_DATE,1,6),'01'),DATE_FORMAT(DATE_SUB(CONCAT(SUBSTR(P_DATA_DATE,1,6),'01'),INTERVAL 3 MONTH),'%Y%m%d'))),0),
IFNULL(c.trade_count,0),
IFNULL(c.trade_amout,0),
IFNULL(e.termina_num/d.termina_num*100,0),
'2'  
FROM 
(SELECT DISTINCT AREA_CODE,AREA_NAME,CITY_CODE,CITY_NAME FROM edw.py_cx_area_code)  a
LEFT JOIN  
(SELECT  
a.area_no_id_2  ,
a.area_dscr_2  ,
COUNT(1) AS serv_point
FROM  edw.py_cx_cash_servinfo a
GROUP BY
a.area_no_id_2  ,
a.area_dscr_2 ) b
ON a.city_code=b.area_no_id_2
LEFT JOIN 
(SELECT  city_code,city_name,
SUM(trade_amout) AS trade_amout,
SUM(trade_count) AS  trade_count
 FROM adm.py_cx_area_tradeinfo
 WHERE SUBSTR(data_date,1,6) IN (SELECT b.month FROM (SELECT QUARTER FROM edw.py_cx_dim_date WHERE MONTH=SUBSTR(P_DATA_DATE,1,6)) a 
LEFT JOIN edw.py_cx_dim_date b
ON a.quarter=b.quarter 
WHERE SUBSTR(b.month,1,4)=SUBSTR(P_DATA_DATE,1,4)) 
 GROUP BY city_code,city_name) c
ON  a.city_code=c.city_code
LEFT JOIN 
(SELECT  COUNT(DISTINCT TERMINA_NUM) AS TERMINA_NUM ,area_no_id_2 
FROM edw.py_cx_cash_servinfo
GROUP BY area_no_id_2) d
ON a.city_code=d.area_no_id_2
LEFT JOIN  (SELECT COUNT(DISTINCT a.termina_num ) AS TERMINA_NUM ,a.area_no_id_2
FROM edw.py_cx_cash_servinfo a 
INNER JOIN (
SELECT TERMINA_NUM,SHOP_NUM FROM edw.py_cx_cash_tradelog 
WHERE SUBSTR(trade_date,1,6) IN (SELECT b.month FROM (SELECT QUARTER FROM edw.py_cx_dim_date WHERE MONTH=SUBSTR(P_DATA_DATE,1,6)) a 
LEFT JOIN edw.py_cx_dim_date b
ON a.quarter=b.quarter 
WHERE SUBSTR(b.month,1,4)=SUBSTR(P_DATA_DATE,1,4))  ) b
ON a.termina_num=b.termina_num AND a.shop_num=b.shop_num  
GROUP BY a.area_no_id_2) e
ON a.city_code=e.area_no_id_2;
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
V_STEP_ID := 6;
 
INSERT INTO  adm.py_cx_trade_check_info 
SELECT SUBSTR(P_DATA_DATE,1,4),a.*,
IFNULL(b.serv_point,0),
IFNULL(c.trade_count/(b.serv_point*DATEDIFF(CONCAT(SUBSTR(P_DATA_DATE,1,6),'01'),CONCAT((SUBSTR(SUBSTR(P_DATA_DATE,1,6),1,4)-1),'1231'))),0),
IFNULL(c.trade_amout/(b.serv_point*DATEDIFF(CONCAT(SUBSTR(P_DATA_DATE,1,6),'01'),CONCAT((SUBSTR(SUBSTR(P_DATA_DATE,1,6),1,4)-1),'1231'))),0),
IFNULL(c.trade_count,0),
IFNULL(c.trade_amout,0),
IFNULL(e.termina_num/d.termina_num*100,0), 
'3'
FROM 
(SELECT DISTINCT AREA_CODE,AREA_NAME,CITY_CODE,CITY_NAME FROM edw.py_cx_area_code)  a
LEFT JOIN  
(SELECT   
a.area_no_id  ,
a.area_dscr  ,
a.area_no_id_2  ,
a.area_dscr_2  ,
COUNT(1) AS serv_point
FROM  edw.py_cx_cash_servinfo a
GROUP BY a.area_no_id  ,
a.area_dscr  ,
a.area_no_id_2  ,
a.area_dscr_2 ) b
ON a.area_code=b.area_no_id
LEFT JOIN  
(SELECT  area_code,area_name,
SUM(trade_amout) AS trade_amout,
SUM(trade_count) AS  trade_count
 FROM adm.py_cx_area_tradeinfo
 WHERE SUBSTR(data_date,1,4) IN (SUBSTR(P_DATA_DATE,1,4))
 GROUP BY  area_code,area_name) c
ON  a.area_code=c.area_code
LEFT JOIN 
(SELECT  COUNT(DISTINCT TERMINA_NUM) AS TERMINA_NUM ,area_no_id 
FROM edw.py_cx_cash_servinfo
GROUP BY area_no_id) d
ON a.area_code=d.area_no_id
LEFT JOIN  (SELECT COUNT(DISTINCT a.termina_num ) AS TERMINA_NUM ,a.area_no_id
FROM edw.py_cx_cash_servinfo a 
INNER JOIN (
SELECT TERMINA_NUM,SHOP_NUM FROM edw.py_cx_cash_tradelog 
WHERE SUBSTR(trade_date,1,4) IN (SUBSTR(P_DATA_DATE,1,4)) ) b
ON a.termina_num=b.termina_num AND a.shop_num=b.shop_num  
GROUP BY a.area_no_id) e
ON a.area_code=e.area_no_id;
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
V_STEP_ID := 7;
INSERT INTO  adm.py_cx_trade_check_info 
SELECT SUBSTR(P_DATA_DATE,1,4),a.*,
IFNULL(b.serv_point,0),
IFNULL(c.trade_count/(b.serv_point*DATEDIFF(CONCAT(SUBSTR(P_DATA_DATE,1,6),'01'),CONCAT((SUBSTR(SUBSTR(P_DATA_DATE,1,6),1,4)-1),'1231'))),0),
IFNULL(c.trade_amout/(b.serv_point*DATEDIFF(CONCAT(SUBSTR(P_DATA_DATE,1,6),'01'),CONCAT((SUBSTR(SUBSTR(P_DATA_DATE,1,6),1,4)-1),'1231'))),0),
IFNULL(c.trade_count,0),
IFNULL(c.trade_amout,0),
IFNULL(e.termina_num/d.termina_num*100,0),
'3'  
FROM 
(SELECT DISTINCT AREA_CODE,AREA_NAME,CITY_CODE,CITY_NAME FROM edw.py_cx_area_code)  a
LEFT JOIN  
(SELECT  
a.area_no_id_2  ,
a.area_dscr_2  ,
COUNT(1) AS serv_point
FROM  edw.py_cx_cash_servinfo a
GROUP BY
a.area_no_id_2  ,
a.area_dscr_2 ) b
ON a.city_code=b.area_no_id_2
LEFT JOIN 
(SELECT  city_code,city_name,
SUM(trade_amout) AS trade_amout,
SUM(trade_count) AS  trade_count
 FROM adm.py_cx_area_tradeinfo
 WHERE SUBSTR(data_date,1,4) IN (SUBSTR(P_DATA_DATE,1,4))
 GROUP BY city_code,city_name) c
ON  a.city_code=c.city_code
LEFT JOIN 
(SELECT  COUNT(DISTINCT TERMINA_NUM) AS TERMINA_NUM ,area_no_id_2 
FROM edw.py_cx_cash_servinfo
GROUP BY area_no_id_2) d
ON a.city_code=d.area_no_id_2
LEFT JOIN  (SELECT COUNT(DISTINCT a.termina_num ) AS TERMINA_NUM ,a.area_no_id_2
FROM edw.py_cx_cash_servinfo a 
INNER JOIN (
SELECT TERMINA_NUM,SHOP_NUM FROM edw.py_cx_cash_tradelog 
WHERE SUBSTR(trade_date,1,4) IN (SUBSTR(P_DATA_DATE,1,4))  ) b
ON a.termina_num=b.termina_num AND a.shop_num=b.shop_num  
GROUP BY a.area_no_id_2) e
ON a.city_code=e.area_no_id_2;
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
END;
/

DROP PROCEDURE IF EXISTS adm.py_cx_verity_table;

CREATE PROCEDURE adm.py_cx_verity_table(
     IN V_ACCT_ID    VARCHAR(8), 
     IN V_TABLE_NAME   VARCHAR(50), 
     IN V_TABLE_PARAM_NUM     VARCHAR(2), 
     IN V_ORG_ID     VARCHAR(15), 
     OUT RESULT_INT INT 
)
AS
    V_PROC_NAME     VARCHAR(80) := 'adm.py_cx_verity_table.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;
    P_RESULT        INT := 0;
    V_DATES         VARCHAR(20) := 0;
    V_STATE CHAR(1);
    STG_TABLE_NAME_WHERE          	VARCHAR(50)  ;
    ODS_TABLE_NAME_WHERE          	VARCHAR(50)  ;
    STG_TABLE_NAME          	VARCHAR(50)  ;
    ODS_TABLE_NAME          	VARCHAR(50)  ;
    Result INT ;
    i INT := 0;		      
    AREA_NO_                 VARCHAR(50) := NULL;
    ADD_DATE_                TIMESTAMP := NULL;
    verity_file_table_count           INT  ; 
    t_error INTEGER := 0;
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
    v_at_del_result TEXT;
    v_at_falg BIGINT;
    v_at_insert_result TEXT;
    v_at_odsResult BIGINT;
    v_at_query_ods_data TEXT;
    v_at_resultState BIGINT;
    v_at_sqlstr TEXT;
    v_at_sqlstr_py_cx_verify_file_del TEXT;
    v_at_sqlstr_py_cx_verify_file_details_del_data TEXT;
    v_at_sqlstr_py_cx_verify_file_details_insert TEXT;
    v_at_sqlstr_py_cx_verify_file_details_insert_indata TEXT;
    v_at_sqlstr_py_cx_verify_file_details_update_data TEXT;
    v_at_sqlstr_py_cx_verify_file_nodata_insert TEXT;
    v_at_sqlstr_py_cx_verify_file_update TEXT;
    v_at_sqlstr_two TEXT;
    v_at_sumResult BIGINT;
    v_at_up_state BIGINT;
BEGIN
	 
	 
	
	
    
    
    
    
    
    
    
    
    
    V_DATES := CONCAT(V_ACCT_ID,'01');
    V_TABLE_NAME := UPPER(V_TABLE_NAME);
    P_RESULT := 0;
    V_STEP_ID := 1;  
    i := V_TABLE_PARAM_NUM;
    
    STG_TABLE_NAME_WHERE := CONCAT("'","STG",".",V_TABLE_NAME,"'");
    ODS_TABLE_NAME_WHERE := CONCAT("'","ODS",".",V_TABLE_NAME,"'");
    STG_TABLE_NAME := CONCAT("STG",".",V_TABLE_NAME);
    ODS_TABLE_NAME := CONCAT("ODS",".",V_TABLE_NAME);
    
    
    v_at_odsResult := 0;
    v_at_query_ods_data := CONCAT("select count(*) INTO @odsResult from ",ODS_TABLE_NAME," where org_no = '",V_ORG_ID,"' and data_date= '",V_ACCT_ID,"'");
    EXECUTE IMMEDIATE v_at_query_ods_data;
    IF (v_at_odsResult=0) THEN
	 i := 2;
	 RETURN; 
    END IF;	
		
    
    IF (i=1) THEN
	
DECLARE
		TABLE_NAME          	VARCHAR(50)  ;
		START_ROW          	VARCHAR(50)  ;
	        TEMPLATE_ID                 VARCHAR(50)  ;
	        COLUMN_NAME                 VARCHAR(50)  ;
	        COLUMN_TYPE                 VARCHAR(50)  ;
	        CELL         	        VARCHAR(50)  ;
	        up_load_table               VARCHAR(50)  ;
	        target_description          VARCHAR(50)  ;
	        compare_same_previous_begin       DOUBLE  ;
	        compare_same_previous_end       DOUBLE  ;
	        compare_chain_base_begin          DOUBLE  ;
	        compare_chain_base_end          DOUBLE  ;
	        compare_same_previous_fs_begin       DOUBLE  ;
	        compare_same_previous_fs_end       DOUBLE  ;
	        compare_chain_base_fs_begin          DOUBLE  ;
	        compare_chain_base_fs_end          DOUBLE  ;
	       	COLUMN_GROUP               VARCHAR(500);
	       	v_tableid          VARCHAR(50)  ;
	       	v_cell          VARCHAR(50)  ;
	       	v_pos          VARCHAR(50)  ;
	       	v_dscr          VARCHAR(50)  ;
	       	v_where          VARCHAR(50)  ;
	        done INT := FALSE; 
		CURSOR My_Cursor IS SELECT * FROM adm.v_py_cx_verity_table;
BEGIN
	       	
	       	
		
		
		DROP VIEW IF EXISTS adm.v_py_cx_verity_table;  
		v_at_sqlstr := "CREATE VIEW adm.v_py_cx_verity_table as ";  
		v_at_sqlstr := CONCAT(v_at_sqlstr , "SELECT 
					        c.table_name,
					         START_ROW,
					        TEMPLATE_ID,
					        COLUMN_NAME,
					        COLUMN_TYPE,
					        cell_number,
					        up_load_table,
					        target_description,
					        compare_same_previous_begin,
					        compare_same_previous_end,
					        compare_chain_base_begin,
					        compare_chain_base_end,
					        compare_same_previous_fs_begin,
					        compare_same_previous_fs_end,
					        compare_chain_base_fs_begin,
					        compare_chain_base_fs_end,
					        table_id,
						c.cell,
						 LOCATE('*',c.cell),
						 (SELECT COLUMN_NAME FROM dps.t_sys_template_table_column e WHERE e.table_id=c.table_id AND LOCATE('*',e.cell)=0 AND LOCATE(',',e.cell)>0) AS dscr,
						CASE  WHEN  LOCATE('*',c.cell)>0 THEN CONCAT((SELECT COLUMN_NAME FROM dps.t_sys_template_table_column e WHERE e.table_id=c.table_id
											AND LOCATE('*',e.cell)=0 AND LOCATE(',',e.cell)>0 ),'=\"',REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(target_description,'农村地区',''),'贫困地区',''),'数量',''),'金额',''),'用户',''),'笔数',''),'\"')
						ELSE '1=1'
						END AS where_
					    FROM
					      (SELECT 
					        a.start_row,
						a.table_name,
						a.template_id,
						b.column_name,
						b.column_type,
						b.cell ,
						a.table_id
					      FROM
						dps.t_sys_template_table a 
						INNER JOIN dps.t_sys_template_table_column b ON a.table_id = b.table_id AND a.table_name = ",STG_TABLE_NAME_WHERE,"
					      ) c 
					    INNER JOIN 
					    (SELECT * FROM edw.py_cx_verify_labelset WHERE table_name = '",V_TABLE_NAME,"' AND state = 1) d 
					    ON (c.cell = d.cell_number AND d.state=1) OR FIND_IN_SET(CONCAT(d.cell_number,'*'), c.cell) ");
		EXECUTE IMMEDIATE v_at_sqlstr;
		
		v_at_falg := 1;
		OPEN My_Cursor;
		<<myLoop>>
		LOOP
			
			FETCH My_Cursor INTO TABLE_NAME,START_ROW,TEMPLATE_ID,COLUMN_NAME,COLUMN_TYPE,CELL,up_load_table,target_description,
				compare_same_previous_begin,compare_same_previous_end,
				compare_chain_base_begin,compare_chain_base_end,
				compare_same_previous_fs_begin,compare_same_previous_fs_end,
				compare_chain_base_fs_begin,compare_chain_base_fs_end,
				v_tableid,v_cell,v_pos,v_dscr,v_where;
			EXIT WHEN My_Cursor%NOTFOUND;
			IF done THEN 
				EXIT myLoop; 
			END IF;	
			
			
DECLARE
				thb_count                 INT  ; 
BEGIN
				
				
				
				
				
				
				
				
				DROP VIEW IF EXISTS adm.v_py_cx_verity_table_ods_data;  
				v_at_sqlstr_two := "CREATE VIEW adm.v_py_cx_verity_table_ods_data as ";  
				v_at_sqlstr_two := CONCAT(v_at_sqlstr_two , "
							SELECT a.area_no,a.data_date,a.org_no,a.org_id,a.add_date,a.",COLUMN_NAME," AS NOW_DATA,b.",COLUMN_NAME," HB_DATA,
							c.",COLUMN_NAME," TB_DATA,d.",COLUMN_NAME," HB_DATA_FS,e.",COLUMN_NAME," TB_DATA_FS,
							ROUND(IFNULL(((a.",COLUMN_NAME,"-b.",COLUMN_NAME,")/b.",COLUMN_NAME,"),0),2) AS HB_RATE,
							ROUND(IFNULL(((a.",COLUMN_NAME,"-c.",COLUMN_NAME,")/c.",COLUMN_NAME,"),0),2) AS TB_RATE,
							case right('",V_ACCT_ID,"',2)
							when '03' then ROUND(IFNULL(((a.",COLUMN_NAME,"-0)-(b.",COLUMN_NAME,"-d.",COLUMN_NAME,")/(b.",COLUMN_NAME,"-d.",COLUMN_NAME,") ),0),2)
							else ROUND(IFNULL(((a.",COLUMN_NAME,"-b.",COLUMN_NAME,")-(b.",COLUMN_NAME,"-d.",COLUMN_NAME,")/(b.",COLUMN_NAME,"-d.",COLUMN_NAME,") ),0),2)
							end  AS HB_RATE_FS,
							case right('",V_ACCT_ID,"',2)
							when '03' then ROUND(IFNULL(((a.",COLUMN_NAME,"-0)-(c.",COLUMN_NAME,"-e.",COLUMN_NAME,")/(c.",COLUMN_NAME,"-e.",COLUMN_NAME,") ),0),2)
							else ROUND(IFNULL(((a.",COLUMN_NAME,"-b.",COLUMN_NAME,")-(c.",COLUMN_NAME,"-e.",COLUMN_NAME,")/(c.",COLUMN_NAME,"-e.",COLUMN_NAME,") ),0),2)
							end  AS TB_RATE_FS,
							'",CELL,"'  as CELL ,
							a.rows_id as ROWS_ID
							 FROM (
							SELECT * FROM ",ODS_TABLE_NAME," 
							WHERE data_date = '",V_ACCT_ID,"' and ORG_NO = '",V_ORG_ID,"' AND ",v_where,") a
							LEFT JOIN (
							SELECT * FROM ",ODS_TABLE_NAME,"
							WHERE  ORG_NO = '",V_ORG_ID,"' AND ",v_where," and
							data_date = '",DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 3 MONTH),'%Y%m'),"')  b
							ON a.area_no = b.area_no AND  a.org_no = b.org_no
							LEFT JOIN (
							SELECT * FROM ",ODS_TABLE_NAME,"
							WHERE ORG_NO = '",V_ORG_ID,"' AND ",v_where," and
							data_date = '",DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 12 MONTH),'%Y%m'),"')  c
							ON a.area_no = c.area_no AND  a.org_no = c.org_no 
							LEFT JOIN (
							SELECT * FROM ",ODS_TABLE_NAME,"
							WHERE ORG_NO = '",V_ORG_ID,"' AND ",v_where," and
							data_date = '",DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 6 MONTH),'%Y%m'),"')  d
							ON a.area_no = c.area_no AND  a.org_no = c.org_no 
							LEFT JOIN (
							SELECT * FROM ",ODS_TABLE_NAME,"
							WHERE ORG_NO = '",V_ORG_ID,"' AND ",v_where," and
							data_date = '",DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 15 MONTH),'%Y%m'),"')  e
							ON a.area_no = c.area_no AND  a.org_no = c.org_no 
							
							");
				EXECUTE IMMEDIATE v_at_sqlstr_two;
				
				
				SELECT COUNT(1) FROM adm.v_py_cx_verity_table_ods_data  WHERE (HB_RATE NOT BETWEEN compare_chain_base_begin AND compare_chain_base_end) 
											OR (TB_RATE NOT BETWEEN compare_same_previous_begin AND compare_same_previous_end)
											OR ( (compare_chain_base_fs_begin !=0.0 OR compare_chain_base_fs_end !=0.0) AND HB_RATE_FS NOT BETWEEN compare_chain_base_fs_begin AND compare_chain_base_fs_end)  
											OR ( (compare_same_previous_fs_begin!=0.0 OR compare_same_previous_fs_end!=0.0) AND TB_RATE_FS NOT BETWEEN compare_same_previous_fs_begin AND compare_same_previous_fs_end) INTO thb_count;
				
				v_at_sqlstr_py_cx_verify_file_del := CONCAT("delete from edw.py_cx_verify_file where payment_days = '",V_ACCT_ID,"' and report_org= '",V_ORG_ID,"'");						
				
				SELECT COUNT(1) FROM edw.py_cx_verify_file WHERE payment_days=V_ACCT_ID AND report_org=V_ORG_ID INTO verity_file_table_count;
				
				v_at_sqlstr_py_cx_verify_file_details_insert := CONCAT("INSERT INTO  edw.py_cx_verify_filedetails",
											" ( SELECT null,'11111','",up_load_table,"','",target_description,"',CELL,ROWS_ID,NOW_DATA,TB_DATA,HB_DATA,TB_DATA_FS,HB_DATA_FS,'' ",
											" FROM adm.v_py_cx_verity_table_ods_data WHERE (HB_RATE NOT BETWEEN ",compare_chain_base_begin," AND ",compare_chain_base_end,")   OR (TB_RATE NOT BETWEEN ",compare_same_previous_begin," AND ",compare_same_previous_end,") OR ( (",compare_chain_base_fs_begin," !=0.0 or ",compare_chain_base_fs_end," !=0.0) AND HB_RATE_FS NOT BETWEEN ",compare_chain_base_fs_begin," AND ",compare_chain_base_fs_end,")   OR ( (",compare_same_previous_fs_begin,"!=0.0 or ",compare_same_previous_fs_end,"!=0.0) AND TB_RATE_FS NOT BETWEEN ",compare_same_previous_fs_begin," AND ",compare_same_previous_fs_end,") )");
						
				
				
				IF (thb_count!=0) THEN
					v_at_falg := 0;
					
					IF (AREA_NO_ IS NULL) THEN
						SELECT AREA_NO,ADD_DATE INTO AREA_NO_,ADD_DATE_ FROM adm.v_py_cx_verity_table_ods_data LIMIT 1 ;
					END IF;
					
					
					IF (verity_file_table_count=0) THEN
					
						
						EXECUTE IMMEDIATE v_at_sqlstr_py_cx_verify_file_details_insert;
					ELSE
						
						
						v_at_sqlstr_py_cx_verify_file_details_del_data := CONCAT("delete  b from 
										edw.py_cx_verify_filedetails b 
										INNER JOIN edw.py_cx_verify_file a ON a.id = b.file_id AND b.template_name = '",up_load_table,"' AND payment_days='",V_ACCT_ID,"' AND report_org='",V_ORG_ID,"' 
										INNER JOIN adm.v_py_cx_verity_table_ods_data c ON  b.row_num = c.rows_id AND b.column_num = c.cell AND ( (c.hb_rate BETWEEN ",compare_chain_base_begin," AND ",compare_chain_base_end,")  and (c.tb_rate BETWEEN ",compare_same_previous_begin," AND ",compare_same_previous_end,") and (",compare_chain_base_fs_begin,"=0.0 and ",compare_chain_base_fs_end,"=0.0 OR  (c.hb_rate_fs BETWEEN ",compare_chain_base_fs_begin," AND ",compare_chain_base_fs_end,") ) and  (",compare_same_previous_fs_begin,"=0.0 and ",compare_same_previous_fs_end,"=0.0 OR  (c.tb_rate_fs BETWEEN ",compare_same_previous_fs_begin," AND ",compare_same_previous_fs_end,")) )
										");
										
						
						v_at_sqlstr_py_cx_verify_file_details_update_data := CONCAT("UPDATE edw.py_cx_verify_filedetails b 
										INNER JOIN edw.py_cx_verify_file a ON a.id = b.file_id AND b.template_name = '",up_load_table,"' AND payment_days='",V_ACCT_ID,"' AND report_org='",V_ORG_ID,"' 
										INNER JOIN adm.v_py_cx_verity_table_ods_data c ON  b.column_num = c.cell AND b.row_num = c.rows_id AND ( (c.hb_rate NOT BETWEEN ",compare_chain_base_begin," AND ",compare_chain_base_end,")  OR (c.tb_rate NOT BETWEEN ",compare_same_previous_begin," AND ",compare_same_previous_end,") OR ( (",compare_chain_base_fs_begin,"!=0.0 or ",compare_chain_base_fs_end,"!=0.0) AND  (c.hb_rate_fs NOT BETWEEN ",compare_chain_base_fs_begin," AND ",compare_chain_base_fs_end,")) OR ( (",compare_same_previous_fs_begin,"!=0.0 or ",compare_same_previous_fs_end,"!=0.0) and  (c.tb_rate_fs NOT BETWEEN ",compare_same_previous_fs_begin," AND ",compare_same_previous_fs_end,")) ) 
										SET b.current_data = c.now_data,b.last_data = c.tb_data,b.sequential_data = c.hb_data,b.sequential_data_fs = c.hb_data_fs,b.last_data_fs = c.tb_data_fs");
										             
						
						v_at_sqlstr_py_cx_verify_file_details_insert_indata := CONCAT("
								INSERT INTO  edw.py_cx_verify_filedetails
								SELECT null,a.id,'",up_load_table,"','",target_description,"',CELL,ROWS_ID,NOW_DATA,TB_DATA,HB_DATA,TB_DATA_FS,HB_DATA_FS, '' 
								FROM  adm.v_py_cx_verity_table_ods_data 
								INNER JOIN (
									SELECT * FROM  edw.py_cx_verify_file WHERE payment_days='",V_ACCT_ID,"' AND report_org= '",V_ORG_ID,"') a
								WHERE cell NOT IN (
									SELECT column_num FROM (
									SELECT * FROM  edw.py_cx_verify_file WHERE payment_days='",V_ACCT_ID,"' AND report_org= '",V_ORG_ID,"') a
									INNER JOIN edw.py_cx_verify_filedetails b ON a.id = b.file_id  AND b.template_name = '",up_load_table,"'
								) AND ( (HB_RATE NOT BETWEEN ",compare_chain_base_begin," AND ",compare_chain_base_end,")  OR (TB_RATE NOT BETWEEN ",compare_same_previous_begin," AND ",compare_same_previous_end,") OR ( (",compare_chain_base_fs_begin," !=0.0 or ",compare_chain_base_fs_end," !=0.0) AND HB_RATE_FS NOT BETWEEN ",compare_chain_base_fs_begin," AND ",compare_chain_base_fs_end,")   OR  ( (",compare_same_previous_fs_begin,"!=0.0 or ",compare_same_previous_fs_end,"!=0.0) AND TB_RATE_FS NOT BETWEEN ",compare_same_previous_fs_begin," AND ",compare_same_previous_fs_end,") )
								");				
											
						EXECUTE IMMEDIATE v_at_sqlstr_py_cx_verify_file_details_del_data;
						
						EXECUTE IMMEDIATE v_at_sqlstr_py_cx_verify_file_details_update_data;
						
						EXECUTE IMMEDIATE v_at_sqlstr_py_cx_verify_file_details_insert_indata;
					END IF;
					
				ELSE
					IF (AREA_NO_ IS NULL) THEN
						SELECT AREA_NO,ADD_DATE INTO AREA_NO_,ADD_DATE_ FROM adm.v_py_cx_verity_table_ods_data LIMIT 1 ;
					END IF;
					
					
					v_at_sqlstr_py_cx_verify_file_details_del_data := CONCAT("delete  b from 
									edw.py_cx_verify_filedetails b 
									INNER JOIN edw.py_cx_verify_file a ON a.id = b.file_id AND b.template_name = '",up_load_table,"' AND payment_days='",V_ACCT_ID,"' AND report_org='",V_ORG_ID,"' 
									INNER JOIN adm.v_py_cx_verity_table_ods_data c ON  b.row_num = c.rows_id AND b.column_num = c.cell AND (  (c.hb_rate BETWEEN ",compare_chain_base_begin," AND ",compare_chain_base_end,")  and (c.tb_rate BETWEEN ",compare_same_previous_begin," AND ",compare_same_previous_end,") and (",compare_chain_base_fs_begin,"=0.0 and ",compare_chain_base_fs_end,"=0.0 OR  (c.hb_rate_fs BETWEEN ",compare_chain_base_fs_begin," AND ",compare_chain_base_fs_end,") ) and  (",compare_same_previous_fs_begin,"=0.0 and ",compare_same_previous_fs_end,"=0.0 OR  (c.tb_rate_fs BETWEEN ",compare_same_previous_fs_begin," AND ",compare_same_previous_fs_end,"))  )
									");
					EXECUTE IMMEDIATE v_at_sqlstr_py_cx_verify_file_details_del_data;
				END IF;	
			END;
				
			END LOOP myLoop;	
			
			v_at_up_state := 2;
			v_at_sqlstr_py_cx_verify_file_nodata_insert := CONCAT("INSERT INTO  edw.py_cx_verify_file",
									" values( null,'",AREA_NO_,"','",V_ACCT_ID,"','",V_ORG_ID,"','','",v_at_up_state,"','",ADD_DATE_,"','adm.",V_TABLE_NAME,"','",V_ACCT_ID,"','','' )");
												
			
			
			v_at_del_result := CONCAT(" delete from edw.py_cx_verify_result where DATA_DATE='",V_ACCT_ID,"' and ORG_NO='",V_ORG_ID,"' and TABLE_NAME='",V_TABLE_NAME,"' ");
			EXECUTE IMMEDIATE v_at_del_result;
				
			
			IF (v_at_falg = 1) THEN
			
				
				
				v_at_resultState := '1';
				v_at_insert_result := CONCAT(" insert into edw.py_cx_verify_result values('",V_ACCT_ID,"','",V_ORG_ID,"','",v_at_resultState,"','",V_TABLE_NAME,"') ");
				EXECUTE IMMEDIATE v_at_insert_result;
				
				IF (verity_file_table_count=0) THEN
				
					
					v_at_up_state := 1;
					v_at_sqlstr_py_cx_verify_file_nodata_insert := CONCAT("INSERT INTO  edw.py_cx_verify_file",
										" values( null,'",AREA_NO_,"','",V_ACCT_ID,"','",V_ORG_ID,"','','",v_at_up_state,"','",ADD_DATE_,"','adm.",V_TABLE_NAME,"','",V_ACCT_ID,"','','' )");
					EXECUTE IMMEDIATE v_at_sqlstr_py_cx_verify_file_nodata_insert;
				ELSE
					
					SELECT COUNT(1) INTO v_at_sumResult FROM edw.py_cx_verify_result WHERE data_date=V_ACCT_ID AND org_no=V_ORG_ID AND state=0;
					
					IF(v_at_sumResult=0) THEN
						
						v_at_sqlstr_py_cx_verify_file_update := CONCAT("UPDATE edw.py_cx_verify_file SET report_status = 1  ,report_date='",ADD_DATE_,"'  WHERE payment_days = '",V_ACCT_ID,"' AND report_org = '",V_ORG_ID,"' ");					
						EXECUTE IMMEDIATE v_at_sqlstr_py_cx_verify_file_update;
					ELSE
						
						v_at_sqlstr_py_cx_verify_file_update := CONCAT("UPDATE edw.py_cx_verify_file SET report_status = 2  ,report_date='",ADD_DATE_,"' WHERE payment_days = '",V_ACCT_ID,"' AND report_org = '",V_ORG_ID,"' ");					
						EXECUTE IMMEDIATE v_at_sqlstr_py_cx_verify_file_update;
					END IF;
					 
				END IF;
				
			ELSE
				
				v_at_resultState := '0';
				v_at_insert_result := CONCAT(" insert into edw.py_cx_verify_result values('",V_ACCT_ID,"','",V_ORG_ID,"','",v_at_resultState,"','",V_TABLE_NAME,"') ");
				EXECUTE IMMEDIATE v_at_insert_result;
			
				IF (verity_file_table_count=0) THEN
				
					
					
					v_at_up_state := 2;
					EXECUTE IMMEDIATE v_at_sqlstr_py_cx_verify_file_nodata_insert;
					
					
					Result := LAST_INSERT_ID();
					UPDATE edw.py_cx_verify_filedetails SET file_id = Result WHERE file_id='11111';
				ELSE
					
					v_at_sqlstr_py_cx_verify_file_update := CONCAT("UPDATE edw.py_cx_verify_file SET report_status = 2  ,report_date='",ADD_DATE_,"' WHERE payment_days = '",V_ACCT_ID,"' AND report_org = '",V_ORG_ID,"' ");					
					EXECUTE IMMEDIATE v_at_sqlstr_py_cx_verify_file_update;
				END IF;
			END IF;
	END;
	
	RESULT_INT := 1;
    ELSIF (i>1) THEN
	 
	i := 3;
    
    END IF;
    
    CALL etl.edw_proc_trace_log('',V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
EXCEPTION
    WHEN OTHERS THEN
	t_error := 1;
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log('',V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
        RESULT_INT := 0;
    
    END;
/

DROP PROCEDURE IF EXISTS adm.py_cx_verity_table_rh;

CREATE PROCEDURE adm.py_cx_verity_table_rh(
     IN V_ACCT_ID    VARCHAR(8), 
     IN V_TABLE_NAME   VARCHAR(50), 
     IN V_TABLE_PARAM_NUM     VARCHAR(2), 
     IN V_ORG_ID     VARCHAR(15), 
     OUT RESULT_INT INT
)
AS
    V_PROC_NAME     VARCHAR(80) := 'adm.py_cx_verity_table_rh.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;
    P_RESULT        INT := 0;
    V_DATES         VARCHAR(20) := 0;
    V_STATE CHAR(1);
    STG_TABLE_NAME_WHERE          	VARCHAR(50)  ;
    ODS_TABLE_NAME_WHERE          	VARCHAR(50)  ;
    STG_TABLE_NAME          	VARCHAR(50)  ;
    ODS_TABLE_NAME          	VARCHAR(50)  ;
    Result INT ;
    i INT := 0;		      
    AREA_NO_                 VARCHAR(50) := NULL;
    ADD_DATE_                TIMESTAMP := NULL;
    verity_file_table_count           INT  ; 
    t_error INTEGER := 0;
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
    v_at_del_result TEXT;
    v_at_falg BIGINT;
    v_at_insert_result TEXT;
    v_at_odsResult BIGINT;
    v_at_query_ods_data TEXT;
    v_at_resultState BIGINT;
    v_at_sqlstr TEXT;
    v_at_sqlstr_py_cx_verify_file_del TEXT;
    v_at_sqlstr_py_cx_verify_file_details_del_data TEXT;
    v_at_sqlstr_py_cx_verify_file_details_insert TEXT;
    v_at_sqlstr_py_cx_verify_file_details_insert_indata TEXT;
    v_at_sqlstr_py_cx_verify_file_details_update_data TEXT;
    v_at_sqlstr_py_cx_verify_file_nodata_insert TEXT;
    v_at_sqlstr_py_cx_verify_file_update TEXT;
    v_at_sqlstr_two TEXT;
    v_at_sumResult BIGINT;
    v_at_up_state BIGINT;
BEGIN
	 
	
	
    
    
    
    
    
    
    
    V_STEP_ID := 1; 
    V_DATES := CONCAT(V_ACCT_ID,'01');
    V_TABLE_NAME := UPPER(V_TABLE_NAME);
    P_RESULT := 0;
    V_STEP_ID := 2;  
    i := V_TABLE_PARAM_NUM;
    STG_TABLE_NAME_WHERE := CONCAT("'","STG",".",V_TABLE_NAME,"'");
    ODS_TABLE_NAME_WHERE := CONCAT("'","ODS",".",V_TABLE_NAME,"'");
    STG_TABLE_NAME := CONCAT("STG",".",V_TABLE_NAME);
    ODS_TABLE_NAME := CONCAT("ODS",".",V_TABLE_NAME);
    
    
    v_at_odsResult := 0;
    v_at_query_ods_data := CONCAT("select count(*) INTO @odsResult from ",ODS_TABLE_NAME," where  ORG_NO IN ( 
		   SELECT c.* 
		   FROM (
			SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"') c
		   INNER JOIN edw.py_cx_verify_file b
		   ON c.org_id = b.report_org AND b.payment_days='",V_ACCT_ID,"' AND b.report_status IN ('1','5')
		   
		  ) OR '",V_ORG_ID,"' '",V_ORG_ID,"' and data_date= '",V_ACCT_ID,"' ");
    EXECUTE IMMEDIATE v_at_query_ods_data;
    
    IF (v_at_odsResult=0) THEN
	 i := 2;
	 RETURN; 
    END IF;
    
    
    IF (i=1) THEN
DECLARE
		TABLE_NAME          	VARCHAR(50)  ;
		START_ROW          	VARCHAR(50)  ;
	        TEMPLATE_ID                 VARCHAR(50)  ;
	        COLUMN_NAME                 VARCHAR(50)  ;
	        COLUMN_TYPE                 VARCHAR(50)  ;
	        CELL         	        VARCHAR(50)  ;
	        up_load_table               VARCHAR(50)  ;
	        target_description          VARCHAR(50)  ;
	        compare_same_previous_begin       DOUBLE  ;
	        compare_same_previous_end       DOUBLE  ;
	        compare_chain_base_begin          DOUBLE  ;
	        compare_chain_base_end          DOUBLE  ;
	        compare_same_previous_fs_begin       DOUBLE  ;
	        compare_same_previous_fs_end       DOUBLE  ;
	        compare_chain_base_fs_begin          DOUBLE  ;
	        compare_chain_base_fs_end          DOUBLE  ;
	       	COLUMN_GROUP               VARCHAR(500);
	       	v_tableid          VARCHAR(50)  ;
	       	v_cell          VARCHAR(50)  ;
	       	v_pos          VARCHAR(50)  ;
	       	v_dscr          VARCHAR(50)  ;
	       	v_where          VARCHAR(50)  ;
	        done INT := FALSE; 
		CURSOR My_Cursor IS SELECT * FROM adm.v_py_cx_verity_table;
BEGIN
	       	
	       	
		
		
		
		
		DROP VIEW IF EXISTS adm.v_py_cx_verity_table;  
		v_at_sqlstr := "CREATE VIEW adm.v_py_cx_verity_table as ";  
		v_at_sqlstr := CONCAT(v_at_sqlstr , "SELECT 
					        c.table_name,
					         START_ROW,
					        TEMPLATE_ID,
					        COLUMN_NAME,
					        COLUMN_TYPE,
					        cell_number,
					        up_load_table,
					        target_description,
					        compare_same_previous_begin,
					        compare_same_previous_end,
					        compare_chain_base_begin,
					        compare_chain_base_end,
					        compare_same_previous_fs_begin,
					        compare_same_previous_fs_end,
					        compare_chain_base_fs_begin,
					        compare_chain_base_fs_end,
					        table_id,
						c.cell,
						 LOCATE('*',c.cell),
						 (SELECT COLUMN_NAME FROM dps.t_sys_template_table_column e WHERE e.table_id=c.table_id AND LOCATE('*',e.cell)=0 AND LOCATE(',',e.cell)>0) AS dscr,
						CASE  WHEN  LOCATE('*',c.cell)>0 THEN CONCAT((SELECT COLUMN_NAME FROM dps.t_sys_template_table_column e WHERE e.table_id=c.table_id
											AND LOCATE('*',e.cell)=0 AND LOCATE(',',e.cell)>0 ),'=\"',REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(target_description,'农村地区',''),'贫困地区',''),'数量',''),'金额',''),'用户',''),'笔数',''),'\"')
						ELSE '1=1'
						END AS where_
					    FROM
					      (SELECT 
					        a.start_row,
						a.table_name,
						a.template_id,
						b.column_name,
						b.column_type,
						b.cell ,
						a.table_id
					      FROM
						dps.t_sys_template_table a 
						INNER JOIN dps.t_sys_template_table_column b ON a.table_id = b.table_id AND a.table_name = ",STG_TABLE_NAME_WHERE,"
					      ) c 
					    INNER JOIN 
					    (SELECT * FROM edw.py_cx_verify_labelset WHERE table_name = '",V_TABLE_NAME,"' AND state = 1) d 
					    ON (c.cell = d.cell_number AND d.state=1) OR FIND_IN_SET(CONCAT(d.cell_number,'*'), c.cell) ");
		EXECUTE IMMEDIATE v_at_sqlstr;
		
		V_STEP_ID := 3;  
		v_at_falg := 1;
		OPEN My_Cursor;
		<<myLoop>>
		LOOP
			
			FETCH My_Cursor INTO TABLE_NAME,START_ROW,TEMPLATE_ID,COLUMN_NAME,COLUMN_TYPE,CELL,up_load_table,target_description,
				compare_same_previous_begin,compare_same_previous_end,
				compare_chain_base_begin,compare_chain_base_end,
				compare_same_previous_fs_begin,compare_same_previous_fs_end,
				compare_chain_base_fs_begin,compare_chain_base_fs_end,
				v_tableid,v_cell,v_pos,v_dscr,v_where;
			EXIT WHEN My_Cursor%NOTFOUND;
			IF done THEN 
				EXIT myLoop; 
			END IF;	
			
			
DECLARE
				thb_count                 INT  ; 
BEGIN
				
				
				
				
				
				
				
				
				V_STEP_ID := 4;
				DROP VIEW IF EXISTS adm.v_py_cx_verity_table_ods_data;  
				v_at_sqlstr_two := "CREATE VIEW adm.v_py_cx_verity_table_ods_data as ";  
				v_at_sqlstr_two := CONCAT(v_at_sqlstr_two , "
							SELECT a.area_no,a.data_date,a.org_no,a.org_id,a.add_date,a.sum_data AS NOW_DATA,b.sum_hb_data as HB_DATA,
							c.sum_tb_data as  TB_DATA,d.sum_hb_data_fs as  HB_DATA_FS,e.sum_tb_data_fs as TB_DATA_FS,
							ROUND(IFNULL(((a.",COLUMN_NAME,"-b.",COLUMN_NAME,")/b.",COLUMN_NAME,"),0),2) AS HB_RATE,
							ROUND(IFNULL(((a.",COLUMN_NAME,"-c.",COLUMN_NAME,")/c.",COLUMN_NAME,"),0),2) AS TB_RATE,
							case right('",V_ACCT_ID,"',2)
							when '03' then ROUND(IFNULL(((a.",COLUMN_NAME,"-0)-(b.",COLUMN_NAME,"-d.",COLUMN_NAME,")/(b.",COLUMN_NAME,"-d.",COLUMN_NAME,") ),0),2)
							else ROUND(IFNULL(((a.",COLUMN_NAME,"-b.",COLUMN_NAME,")-(b.",COLUMN_NAME,"-d.",COLUMN_NAME,")/(b.",COLUMN_NAME,"-d.",COLUMN_NAME,") ),0),2)
							end  AS HB_RATE_FS,
							case right('",V_ACCT_ID,"',2)
							when '03' then ROUND(IFNULL(((a.",COLUMN_NAME,"-0)-(c.",COLUMN_NAME,"-e.",COLUMN_NAME,")/(c.",COLUMN_NAME,"-e.",COLUMN_NAME,") ),0),2)
							else ROUND(IFNULL(((a.",COLUMN_NAME,"-b.",COLUMN_NAME,")-(c.",COLUMN_NAME,"-e.",COLUMN_NAME,")/(c.",COLUMN_NAME,"-e.",COLUMN_NAME,") ),0),2)
							end  AS TB_RATE_FS,
							'",CELL,"'  as CELL ,
							a.rows_id as ROWS_ID
							 FROM (
							SELECT *,SUM(",COLUMN_NAME,") AS sum_data FROM ",ODS_TABLE_NAME," 
							, (SELECT LEVEL  FROM dmcode.t_org_biz_lvl WHERE org_id = '",V_ORG_ID,"') f
							WHERE  DATA_DATE = '",V_ACCT_ID,"' and 
							CASE
							    WHEN f.level = 2 THEN 
										 ( ORG_NO IN ( 
										SELECT c.* 
										FROM (
											SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"'
											UNION ALL SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id IN(SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"') 
											UNION ALL SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id IN(SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id IN(SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"')) ) c
										INNER JOIN edw.py_cx_verify_file b
										ON c.org_id = b.report_org AND b.payment_days='",V_ACCT_ID,"' AND b.report_status IN ('1','5')
									       ) OR ORG_NO = '",V_ORG_ID,"' )
							    WHEN f.level = 3 THEN 
										( ORG_NO IN ( 
										SELECT c.* 
										FROM (
											SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"'
											UNION ALL SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id IN(SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"') ) c
										INNER JOIN edw.py_cx_verify_file b
										ON c.org_id = b.report_org AND b.payment_days='",V_ACCT_ID,"' AND b.report_status IN ('1','5')
									       ) OR ORG_NO = '",V_ORG_ID,"' )
							    WHEN f.level = 4 THEN 
									     ( ORG_NO IN ( 
										SELECT c.* 
										FROM (
											SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"') c
										INNER JOIN edw.py_cx_verify_file b
										ON c.org_id = b.report_org AND b.payment_days='",V_ACCT_ID,"' AND b.report_status IN ('1','5')
									       ) OR ORG_NO = '",V_ORG_ID,"' )
							   else 1=1
							END  AND ",v_where,"  ) a
							LEFT JOIN (
							SELECT *,SUM(",COLUMN_NAME,") AS sum_hb_data FROM ",ODS_TABLE_NAME,"
							, (SELECT LEVEL  FROM dmcode.t_org_biz_lvl WHERE org_id = '",V_ORG_ID,"') f
							WHERE  DATA_DATE = '",DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 3 MONTH),'%Y%m'),"' and 
							CASE
							    WHEN f.level = 2 THEN 
										 ( ORG_NO IN ( 
										SELECT c.* 
										FROM (
											SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"'
											UNION ALL SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id IN(SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"') 
											UNION ALL SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id IN(SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id IN(SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"')) ) c
										INNER JOIN edw.py_cx_verify_file b
										ON c.org_id = b.report_org AND b.payment_days='",DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 3 MONTH),'%Y%m'),"' AND b.report_status IN ('1','5')
									       ) OR ORG_NO = '",V_ORG_ID,"' )
							    WHEN f.level = 3 THEN 
										( ORG_NO IN ( 
										SELECT c.* 
										FROM (
											SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"'
											UNION ALL SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id IN(SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"') ) c
										INNER JOIN edw.py_cx_verify_file b
										ON c.org_id = b.report_org AND b.payment_days='",DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 3 MONTH),'%Y%m'),"' AND b.report_status IN ('1','5')
									       ) OR ORG_NO = '",V_ORG_ID,"' )
							    WHEN f.level = 4 THEN 
									     ( ORG_NO IN ( 
										SELECT c.* 
										FROM (
											SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"') c
										INNER JOIN edw.py_cx_verify_file b
										ON c.org_id = b.report_org AND b.payment_days='",DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 3 MONTH),'%Y%m'),"' AND b.report_status IN ('1','5')
									       ) OR ORG_NO = '",V_ORG_ID,"' )
							   else 1=1
							END  AND ",v_where,"  )  b
							ON 1=1
							LEFT JOIN (
							SELECT *,SUM(",COLUMN_NAME,") AS sum_tb_data FROM ",ODS_TABLE_NAME,"
							, (SELECT LEVEL  FROM dmcode.t_org_biz_lvl WHERE org_id = '",V_ORG_ID,"') f
							WHERE  DATA_DATE = '",DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 12 MONTH),'%Y%m'),"' and 
							CASE
							    WHEN f.level = 2 THEN 
										 ( ORG_NO IN ( 
										SELECT c.* 
										FROM (
											SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"'
											UNION ALL SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id IN(SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"') 
											UNION ALL SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id IN(SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id IN(SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"')) ) c
										INNER JOIN edw.py_cx_verify_file b
										ON c.org_id = b.report_org AND b.payment_days='",DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 12 MONTH),'%Y%m'),"' AND b.report_status IN ('1','5')
									       ) OR ORG_NO = '",V_ORG_ID,"' )
							    WHEN f.level = 3 THEN 
										( ORG_NO IN ( 
										SELECT c.* 
										FROM (
											SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"'
											UNION ALL SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id IN(SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"') ) c
										INNER JOIN edw.py_cx_verify_file b
										ON c.org_id = b.report_org AND b.payment_days='",DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 12 MONTH),'%Y%m'),"' AND b.report_status IN ('1','5')
									       ) OR ORG_NO = '",V_ORG_ID,"' )
							    WHEN f.level = 4 THEN 
									     ( ORG_NO IN ( 
										SELECT c.* 
										FROM (
											SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"') c
										INNER JOIN edw.py_cx_verify_file b
										ON c.org_id = b.report_org AND b.payment_days='",DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 12 MONTH),'%Y%m'),"' AND b.report_status IN ('1','5')
									      ) OR ORG_NO = '",V_ORG_ID,"' )
							   else 1=1
							END  AND ",v_where,"   )  c
							ON 1=1
							LEFT JOIN (
							SELECT *,SUM(",COLUMN_NAME,") AS sum_hb_data_fs FROM ",ODS_TABLE_NAME,"
							, (SELECT LEVEL  FROM dmcode.t_org_biz_lvl WHERE org_id = '",V_ORG_ID,"') f
							WHERE  DATA_DATE = '",DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 6 MONTH),'%Y%m'),"' and 
							CASE
							    WHEN f.level = 2 THEN 
										 ( ORG_NO IN ( 
										SELECT c.* 
										FROM (
											SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"'
											UNION ALL SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id IN(SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"') 
											UNION ALL SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id IN(SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id IN(SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"')) ) c
										INNER JOIN edw.py_cx_verify_file b
										ON c.org_id = b.report_org AND b.payment_days='",DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 6 MONTH),'%Y%m'),"' AND b.report_status IN ('1','5')
									       ) OR ORG_NO = '",V_ORG_ID,"' )
							    WHEN f.level = 3 THEN 
										( ORG_NO IN ( 
										SELECT c.* 
										FROM (
											SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"'
											UNION ALL SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id IN(SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"') ) c
										INNER JOIN edw.py_cx_verify_file b
										ON c.org_id = b.report_org AND b.payment_days='",DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 6 MONTH),'%Y%m'),"' AND b.report_status IN ('1','5')
									       ) OR ORG_NO = '",V_ORG_ID,"' )
							    WHEN f.level = 4 THEN 
									     ( ORG_NO IN ( 
										SELECT c.* 
										FROM (
											SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"') c
										INNER JOIN edw.py_cx_verify_file b
										ON c.org_id = b.report_org AND b.payment_days='",DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 6 MONTH),'%Y%m'),"' AND b.report_status IN ('1','5')
									       ) OR ORG_NO = '",V_ORG_ID,"' )
							   else 1=1
							END  AND ",v_where,"  )  d
							ON 1=1
							LEFT JOIN (
							SELECT *,SUM(",COLUMN_NAME,") AS sum_tb_data_fs FROM ",ODS_TABLE_NAME,"
							, (SELECT LEVEL  FROM dmcode.t_org_biz_lvl WHERE org_id = '",V_ORG_ID,"') f
							WHERE  DATA_DATE = '",DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 15 MONTH),'%Y%m'),"' and 
							CASE
							    WHEN f.level = 2 THEN 
										 ( ORG_NO IN ( 
										SELECT c.* 
										FROM (
											SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"'
											UNION ALL SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id IN(SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"') 
											UNION ALL SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id IN(SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id IN(SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"')) ) c
										INNER JOIN edw.py_cx_verify_file b
										ON c.org_id = b.report_org AND b.payment_days='",DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 15 MONTH),'%Y%m'),"' AND b.report_status IN ('1','5')
									       ) OR ORG_NO = '",V_ORG_ID,"' )
							    WHEN f.level = 3 THEN 
										( ORG_NO IN ( 
										SELECT c.* 
										FROM (
											SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"'
											UNION ALL SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id IN(SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"') ) c
										INNER JOIN edw.py_cx_verify_file b
										ON c.org_id = b.report_org AND b.payment_days='",DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 15 MONTH),'%Y%m'),"' AND b.report_status IN ('1','5')
									       ) OR ORG_NO = '",V_ORG_ID,"' )
							    WHEN f.level = 4 THEN 
									     ( ORG_NO IN ( 
										SELECT c.* 
										FROM (
											SELECT ORG_ID FROM dmcode.t_org_biz_lvl  WHERE pbc_id = '",V_ORG_ID,"') c
										INNER JOIN edw.py_cx_verify_file b
										ON c.org_id = b.report_org AND b.payment_days='",DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 15 MONTH),'%Y%m'),"' AND b.report_status IN ('1','5')
									       ) OR ORG_NO = '",V_ORG_ID,"' )
							   else 1=1
							END  AND ",v_where,"  )  e
							ON 1=1
							");
				EXECUTE IMMEDIATE v_at_sqlstr_two;
				V_STEP_ID := 5;
				
				SELECT COUNT(1) FROM adm.v_py_cx_verity_table_ods_data  WHERE (HB_RATE not BETWEEN compare_chain_base_begin and compare_chain_base_end) 
											OR (TB_RATE NOT between compare_same_previous_begin and compare_same_previous_end)
											OR ( (compare_chain_base_fs_begin !=0.0 or compare_chain_base_fs_end !=0.0) AND HB_RATE_FS NOT between compare_chain_base_fs_begin and compare_chain_base_fs_end)  
											OR ( (compare_same_previous_fs_begin!=0.0 or compare_same_previous_fs_end!=0.0) AND TB_RATE_FS NOT BETWEEN compare_same_previous_fs_begin and compare_same_previous_fs_end) INTO thb_count;
				
				v_at_sqlstr_py_cx_verify_file_del := CONCAT("delete from edw.py_cx_verify_file where payment_days = '",V_ACCT_ID,"' and report_org= '",V_ORG_ID,"'");						
				
				SELECT COUNT(1) FROM edw.py_cx_verify_file WHERE payment_days=V_ACCT_ID AND report_org=V_ORG_ID INTO verity_file_table_count;
				
				v_at_sqlstr_py_cx_verify_file_details_insert := CONCAT("INSERT INTO  edw.py_cx_verify_filedetails",
											" ( SELECT null,'11111','",up_load_table,"','",target_description,"',CELL,ROWS_ID,NOW_DATA,TB_DATA,HB_DATA,TB_DATA_FS,HB_DATA_FS,'' ",
											" FROM adm.v_py_cx_verity_table_ods_data WHERE (HB_RATE NOT BETWEEN ",compare_chain_base_begin," AND ",compare_chain_base_end,")   OR (TB_RATE NOT BETWEEN ",compare_same_previous_begin," AND ",compare_same_previous_end,") OR ( (",compare_chain_base_fs_begin," !=0.0 or ",compare_chain_base_fs_end," !=0.0) AND HB_RATE_FS NOT BETWEEN ",compare_chain_base_fs_begin," AND ",compare_chain_base_fs_end,")   OR ( (",compare_same_previous_fs_begin,"!=0.0 or ",compare_same_previous_fs_end,"!=0.0) AND TB_RATE_FS NOT BETWEEN ",compare_same_previous_fs_begin," AND ",compare_same_previous_fs_end,") )");
						
				V_STEP_ID := 6;
				
				IF (thb_count!=0) THEN
					v_at_falg := 0;
					
					IF (AREA_NO_ IS NULL) THEN
						SELECT AREA_NO,NOW() INTO AREA_NO_,ADD_DATE_ FROM adm.v_py_cx_verity_table_ods_data LIMIT 1 ;
					END IF;
					
					
					IF (verity_file_table_count=0) THEN
					
						
						EXECUTE IMMEDIATE v_at_sqlstr_py_cx_verify_file_details_insert;
					ELSE
						
						
						v_at_sqlstr_py_cx_verify_file_details_del_data := CONCAT("delete  b from 
										edw.py_cx_verify_filedetails b 
										INNER JOIN edw.py_cx_verify_file a ON a.id = b.file_id AND b.template_name = '",up_load_table,"' AND payment_days='",V_ACCT_ID,"' AND report_org='",V_ORG_ID,"' 
										INNER JOIN adm.v_py_cx_verity_table_ods_data c ON  b.row_num = c.rows_id AND b.column_num = c.cell AND ( (c.hb_rate BETWEEN ",compare_chain_base_begin," AND ",compare_chain_base_end,")  and (c.tb_rate BETWEEN ",compare_same_previous_begin," AND ",compare_same_previous_end,") and (",compare_chain_base_fs_begin,"=0.0 and ",compare_chain_base_fs_end,"=0.0 OR  (c.hb_rate_fs BETWEEN ",compare_chain_base_fs_begin," AND ",compare_chain_base_fs_end,") ) and  (",compare_same_previous_fs_begin,"=0.0 and ",compare_same_previous_fs_end,"=0.0 OR  (c.tb_rate_fs BETWEEN ",compare_same_previous_fs_begin," AND ",compare_same_previous_fs_end,")) )
										");
										
						
						v_at_sqlstr_py_cx_verify_file_details_update_data := CONCAT("UPDATE edw.py_cx_verify_filedetails b 
										INNER JOIN edw.py_cx_verify_file a ON a.id = b.file_id AND b.template_name = '",up_load_table,"' AND payment_days='",V_ACCT_ID,"' AND report_org='",V_ORG_ID,"' 
										INNER JOIN adm.v_py_cx_verity_table_ods_data c ON  b.column_num = c.cell AND b.row_num = c.rows_id AND ( (c.hb_rate NOT BETWEEN ",compare_chain_base_begin," AND ",compare_chain_base_end,")  OR (c.tb_rate NOT BETWEEN ",compare_same_previous_begin," AND ",compare_same_previous_end,") OR ( (",compare_chain_base_fs_begin,"!=0.0 or ",compare_chain_base_fs_end,"!=0.0) AND  (c.hb_rate_fs NOT BETWEEN ",compare_chain_base_fs_begin," AND ",compare_chain_base_fs_end,")) OR ( (",compare_same_previous_fs_begin,"!=0.0 or ",compare_same_previous_fs_end,"!=0.0) and  (c.tb_rate_fs NOT BETWEEN ",compare_same_previous_fs_begin," AND ",compare_same_previous_fs_end,")) ) 
										SET b.current_data = c.now_data,b.last_data = c.tb_data,b.sequential_data = c.hb_data,b.sequential_data_fs = c.hb_data_fs,b.last_data_fs = c.tb_data_fs");
										             
						
						v_at_sqlstr_py_cx_verify_file_details_insert_indata := CONCAT("
								INSERT INTO  edw.py_cx_verify_filedetails
								SELECT null,a.id,'",up_load_table,"','",target_description,"',CELL,ROWS_ID,NOW_DATA,TB_DATA,HB_DATA,TB_DATA_FS,HB_DATA_FS, '' 
								FROM  adm.v_py_cx_verity_table_ods_data 
								INNER JOIN (
									SELECT * FROM  edw.py_cx_verify_file WHERE payment_days='",V_ACCT_ID,"' AND report_org= '",V_ORG_ID,"') a
								WHERE cell NOT IN (
									SELECT column_num FROM (
									SELECT * FROM  edw.py_cx_verify_file WHERE payment_days='",V_ACCT_ID,"' AND report_org= '",V_ORG_ID,"') a
									INNER JOIN edw.py_cx_verify_filedetails b ON a.id = b.file_id  AND b.template_name = '",up_load_table,"'
								) AND ( (HB_RATE NOT BETWEEN ",compare_chain_base_begin," AND ",compare_chain_base_end,")  OR (TB_RATE NOT BETWEEN ",compare_same_previous_begin," AND ",compare_same_previous_end,") OR ( (",compare_chain_base_fs_begin," !=0.0 or ",compare_chain_base_fs_end," !=0.0) AND HB_RATE_FS NOT BETWEEN ",compare_chain_base_fs_begin," AND ",compare_chain_base_fs_end,")   OR  ( (",compare_same_previous_fs_begin,"!=0.0 or ",compare_same_previous_fs_end,"!=0.0) AND TB_RATE_FS NOT BETWEEN ",compare_same_previous_fs_begin," AND ",compare_same_previous_fs_end,") )
								");				
											
						EXECUTE IMMEDIATE v_at_sqlstr_py_cx_verify_file_details_del_data;
						
						EXECUTE IMMEDIATE v_at_sqlstr_py_cx_verify_file_details_update_data;
						
						EXECUTE IMMEDIATE v_at_sqlstr_py_cx_verify_file_details_insert_indata;
					END IF;
					
				ELSE
				
					IF (AREA_NO_ IS NULL) THEN
						SELECT AREA_NO,NOW() INTO AREA_NO_,ADD_DATE_ FROM adm.v_py_cx_verity_table_ods_data LIMIT 1 ;
					END IF;
					
					V_STEP_ID := 7;
					
					v_at_sqlstr_py_cx_verify_file_details_del_data := CONCAT("delete  b from 
									edw.py_cx_verify_filedetails b 
									INNER JOIN edw.py_cx_verify_file a ON a.id = b.file_id AND b.template_name = '",up_load_table,"' AND payment_days='",V_ACCT_ID,"' AND report_org='",V_ORG_ID,"' 
									INNER JOIN adm.v_py_cx_verity_table_ods_data c ON  b.row_num = c.rows_id AND b.column_num = c.cell AND (  (c.hb_rate BETWEEN ",compare_chain_base_begin," AND ",compare_chain_base_end,")  and (c.tb_rate BETWEEN ",compare_same_previous_begin," AND ",compare_same_previous_end,") and (",compare_chain_base_fs_begin,"=0.0 and ",compare_chain_base_fs_end,"=0.0 OR  (c.hb_rate_fs BETWEEN ",compare_chain_base_fs_begin," AND ",compare_chain_base_fs_end,") ) and  (",compare_same_previous_fs_begin,"=0.0 and ",compare_same_previous_fs_end,"=0.0 OR  (c.tb_rate_fs BETWEEN ",compare_same_previous_fs_begin," AND ",compare_same_previous_fs_end,"))  )
									");
					EXECUTE IMMEDIATE v_at_sqlstr_py_cx_verify_file_details_del_data;
					V_STEP_ID := 8;
				END IF;	
				
			END;
				
			END LOOP myLoop;	
			V_STEP_ID := 9;  
			v_at_up_state := 2;
			v_at_sqlstr_py_cx_verify_file_nodata_insert := CONCAT("INSERT INTO  edw.py_cx_verify_file",
									" values( null,'",AREA_NO_,"','",V_ACCT_ID,"','",V_ORG_ID,"','','",v_at_up_state,"','",ADD_DATE_,"','adm.",V_TABLE_NAME,"','",V_ACCT_ID,"','','' )");
												
			
			
			v_at_del_result := CONCAT(" delete from edw.py_cx_verify_result where DATA_DATE='",V_ACCT_ID,"' and ORG_NO='",V_ORG_ID,"' and TABLE_NAME='",V_TABLE_NAME,"' ");
			EXECUTE IMMEDIATE v_at_del_result;
				
			
			IF (v_at_falg = 1) THEN
			
				
				
				v_at_resultState := '1';
				v_at_insert_result := CONCAT(" insert into edw.py_cx_verify_result values('",V_ACCT_ID,"','",V_ORG_ID,"','",v_at_resultState,"','",V_TABLE_NAME,"') ");
				EXECUTE IMMEDIATE v_at_insert_result;
				
				IF (verity_file_table_count=0) THEN
				
					
					v_at_up_state := 1;
					v_at_sqlstr_py_cx_verify_file_nodata_insert := CONCAT("INSERT INTO  edw.py_cx_verify_file",
										" values( null,'",AREA_NO_,"','",V_ACCT_ID,"','",V_ORG_ID,"','','",v_at_up_state,"','",ADD_DATE_,"','adm.",V_TABLE_NAME,"','",V_ACCT_ID,"','','' )");
					EXECUTE IMMEDIATE v_at_sqlstr_py_cx_verify_file_nodata_insert;
				ELSE
					
					SELECT COUNT(1) INTO v_at_sumResult FROM edw.py_cx_verify_result WHERE data_date=V_ACCT_ID AND org_no=V_ORG_ID AND state=0;
					
					IF(v_at_sumResult=0) THEN
						
						v_at_sqlstr_py_cx_verify_file_update := CONCAT("UPDATE edw.py_cx_verify_file SET report_status = 1  ,report_date='",ADD_DATE_,"'  WHERE payment_days = '",V_ACCT_ID,"' AND report_org = '",V_ORG_ID,"' ");					
						EXECUTE IMMEDIATE v_at_sqlstr_py_cx_verify_file_update;
					ELSE
						
						v_at_sqlstr_py_cx_verify_file_update := CONCAT("UPDATE edw.py_cx_verify_file SET report_status = 2  ,report_date='",ADD_DATE_,"' WHERE payment_days = '",V_ACCT_ID,"' AND report_org = '",V_ORG_ID,"' ");					
						EXECUTE IMMEDIATE v_at_sqlstr_py_cx_verify_file_update;
					END IF;
					 
				END IF;
				
			ELSE
				
				v_at_resultState := '0';
				v_at_insert_result := CONCAT(" insert into edw.py_cx_verify_result values('",V_ACCT_ID,"','",V_ORG_ID,"','",v_at_resultState,"','",V_TABLE_NAME,"') ");
				EXECUTE IMMEDIATE v_at_insert_result;
			
				IF (verity_file_table_count=0) THEN
				
					
					
					v_at_up_state := 2;
					EXECUTE IMMEDIATE v_at_sqlstr_py_cx_verify_file_nodata_insert;
					
					
					Result := LAST_INSERT_ID();
					UPDATE edw.py_cx_verify_filedetails SET file_id = Result WHERE file_id='11111';
				ELSE
					
					v_at_sqlstr_py_cx_verify_file_update := CONCAT("UPDATE edw.py_cx_verify_file SET report_status = 2  ,report_date='",ADD_DATE_,"' WHERE payment_days = '",V_ACCT_ID,"' AND report_org = '",V_ORG_ID,"' ");					
					EXECUTE IMMEDIATE v_at_sqlstr_py_cx_verify_file_update;
				END IF;
			END IF;
	END;
	
	RESULT_INT := 1;
    ELSIF (i>1) THEN
	 
	i := 3;
    
    END IF;
    
    CALL etl.edw_proc_trace_log('',V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
  
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log('',V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
        RESULT_INT := 0;
        RESULT_INT := 0;
        
    END;
/

DROP PROCEDURE IF EXISTS adm.py_cx_verity_testquerycol;

CREATE PROCEDURE adm.py_cx_verity_testquerycol()
AS
    V_PROC_NAME     VARCHAR(80) := 'adm.py_cx_verity_testquerycol.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;
    P_RESULT        INT := 0;
    V_DATES         VARCHAR(20) := 0;
    V_STATE CHAR(1);
    COLUMN_NAME         VARCHAR(50) := 0;
    done INT := FALSE; 
    CURSOR My_Cursor IS SELECT COLUMN_NAME  FROM information_schema.columns WHERE  TABLE_SCHEMA ="ods" AND table_name='py_cx_envbld_rural_bnk_accts';
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN 
    
    -- NOT FOUND handler replaced by explicit cursor %NOTFOUND checks below.
        
    
    
    
    
    V_DATES := CONCAT(V_ACCT_ID,'01');
    P_RESULT := 0;
    V_STEP_ID := 1;  
 
    OPEN My_Cursor;
		<<myLoop>>
		LOOP
			FETCH My_Cursor INTO COLUMN_NAME;
			EXIT WHEN My_Cursor%NOTFOUND;
			IF done THEN 
				EXIT myLoop; 
			END IF;
		END LOOP myLoop;
   
    
    
    
    
    
    
    
    
    
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log('',V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
    END;
/

