DROP PROCEDURE IF EXISTS adm.py_cx_yc_check_tjb;

CREATE PROCEDURE adm.py_cx_yc_check_tjb(
     IN V_ACCT_ID    VARCHAR(8),
     OUT P_RESULT    INT
)
AS
    V_PROC_NAME     VARCHAR(80) := 'adm.py_cx_yc_check_tjb.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;
    P_RESULT        INT := 0;
    V_DATES         VARCHAR(20) := 0;
    V_STATE CHAR(1);
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
    

    
    
    P_RESULT := 0;
    V_DATES := V_ACCT_ID;
    
    V_STEP_ID := 1;
    DELETE FROM adm.py_cx_yc_check_tjb WHERE DATA_DATE = SUBSTR(V_ACCT_ID,1,6);
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
  
   V_STEP_ID := 2; 
  INSERT INTO adm.py_cx_yc_check_tjb 
SELECT 
  SUBSTR(trade_date, 1, 6) AS data_date,
  b.org_type_dscr_2,
  a.area_code,
  a.area_name,
  a.city_code,
  a.city_name,
  COUNT(1) AS yc_bs,
  SUM(trade_amount) AS yc_je,
  YC_BIG,
  YC_DETAIL,
  Remarks 
FROM adm.py_cx_yc_check_detail a 
  INNER JOIN dmcode.t_org_biz_lvl b 
    ON a.org_num = b.org_id 
GROUP BY SUBSTR(trade_date, 1, 6),
  b.org_type_dscr_2,
  a.area_code,
  a.area_name,
  a.city_code,
  a.city_name,
  YC_BIG,
  YC_DETAIL,
  Remarks ;
    CALL etl.edw_proc_trace_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
END;
/

