CREATE PROCEDURE adm.p_guoku_saiku_processing(
    IN P_DATA_DATE CHAR(10)
)
AS
    V_PROC_NAME     VARCHAR(50) := 'adm.p_guoku_saiku_processing.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;  -- 步骤编号
