DROP PROCEDURE IF EXISTS adm.p_execute_date_processing;

CREATE PROCEDURE adm.p_execute_date_processing(
IN P_DATA_DATE CHAR(10)
)
AS
    v_at_P_LASTDAY_DAYE VARCHAR(2000);
BEGIN
  -- DECLARE  P_DAY_DATE  CHAR(10) DEFAULT '';
    -- 定义跑数日期（当前时间的7天前）
   -- SET P_DAY_DATE = CONCAT(DATE_SUB(DATE_FORMAT(NOW(),'%Y-%m-%d'),INTERVAL 7 DAY));
   P_DATA_DATE := DATE_FORMAT(P_DATA_DATE,'%Y-%m-%d');
  -- SET P_DAY_DATE = P_DATA_DATE;
    -- 定义跑数日期的本月最后一天日期
    v_at_P_LASTDAY_DAYE := CONCAT(LAST_DAY(P_DATA_DATE));
    -- 执行报表数据加工过程
  --  CALL adm.p_guoku_report_processing(P_DAY_DATE);
    -- 执行多维数据加工过程
    CALL adm.p_guoku_saiku_processing(P_DATA_DATE);
    IF P_DATA_DATE=v_at_P_LASTDAY_DAYE 
    THEN
         -- 执行专题按日跑的数据加工过程
         CALL adm.p_guoku_day_ana_processing(P_DATA_DATE);
         -- 执行专题按每月最后一天跑的数据加工过程
         CALL adm.p_guoku_lastday_ana_processing(P_DATA_DATE);
    ELSE
         -- 执行专题按日跑的数据加工过程
         CALL adm.p_guoku_day_ana_processing(P_DATA_DATE);
    END IF;
END;
/

DROP PROCEDURE IF EXISTS adm.p_execute_date_processing1;

CREATE PROCEDURE adm.p_execute_date_processing1(
IN P_DATA_DATE CHAR(10)
)
AS
    v_at_P_LASTDAY_DAYE VARCHAR(2000);
BEGIN
  -- DECLARE  P_DAY_DATE  CHAR(10) DEFAULT '';
    -- 定义跑数日期（当前时间的7天前）
   -- SET P_DAY_DATE = CONCAT(DATE_SUB(DATE_FORMAT(NOW(),'%Y-%m-%d'),INTERVAL 7 DAY));
   P_DATA_DATE := DATE_FORMAT(P_DATA_DATE,'%Y-%m-%d');
  -- SET P_DAY_DATE = P_DATA_DATE;
    -- 定义跑数日期的本月最后一天日期
    v_at_P_LASTDAY_DAYE := CONCAT(LAST_DAY(P_DATA_DATE));
    -- 执行报表数据加工过程
  --  CALL adm.p_guoku_report_processing(P_DAY_DATE);
    -- 执行多维数据加工过程
    
    IF P_DATA_DATE=v_at_P_LASTDAY_DAYE 
    THEN
         -- 执行专题按日跑的数据加工过程
         CALL adm.p_guoku_day_ana_processing(P_DATA_DATE);
         -- 执行专题按每月最后一天跑的数据加工过程
         CALL adm.p_guoku_lastday_ana_processing(P_DATA_DATE);
    ELSE
         -- 执行专题按日跑的数据加工过程
         CALL adm.p_guoku_day_ana_processing(P_DATA_DATE);
    END IF;
    END;
/

DROP PROCEDURE IF EXISTS adm.p_guoku_saiku_processing1;

CREATE PROCEDURE adm.p_guoku_saiku_processing1(
    IN P_DATA_DATE CHAR(10)
)
AS
    V_PROC_NAME     VARCHAR(50) := 'adm.p_guoku_saiku_processing1.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;  -- 步骤编号
    V_STEP_NAME     VARCHAR(100) := ''; -- 步骤信息
    V_SQL_ID        INT := 0;  -- 查询SQL的ID
    V_TABLE_NAME    VARCHAR(50) := ''; -- 操作表名
    V_SQL_DELETE    VARCHAR(100) := ''; -- 删除语句SQL
    V_SQL_INSERT    LONGTEXT := ''; -- 插数语句SQL
    V_SQLTXT        LONGTEXT := ''; -- 执行SQL
    DONE            INT := FALSE; -- 自定义控制游标循环变量,默认false
    CURSOR PROC_CURSOR IS 
                                       SELECT ID FROM adm.trs_guoku_saiku_processing
                                       WHERE IS_ACTIVE='1' and ID in ('2','4') AND REPLACE(P_DATA_DATE,'-','') BETWEEN START_DATE AND END_DATE
                                       ; -- 定义游标并输入结果集
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
    v_at_DAY_DATE VARCHAR(2000);
    v_at_MONTH_DATE VARCHAR(2000);
    v_at_V_SQLTXT TEXT;
    v_at_YEAR_DATE VARCHAR(2000);
BEGIN
/******************
过程跑数频率：按日
过程跑数内容：执行多维加工所有过程
*******************/
    -- NOT FOUND handler replaced by explicit cursor %NOTFOUND checks below.
    /* EXCEPTION HANDLER */
    
    OPEN PROC_CURSOR; -- 打开游标
    <<PROC_CURSOR>>
    LOOP -- 开始循环体,PROC_CURSOR为自定义循环名,结束循环时用到
    FETCH PROC_CURSOR INTO V_SQL_ID; -- 将游标当前读取行的数据顺序赋予自定义变量-查询SQL的ID
    EXIT WHEN PROC_CURSOR%NOTFOUND;
    IF DONE THEN -- 判断是否继续循环
      EXIT PROC_CURSOR; -- 结束循环
    END IF;
    -- 自己要做的事情,在 sql 中直接使用自定义变量即可
    
    -- 日账期
    v_at_DAY_DATE := CONCAT(P_DATA_DATE);
    -- 月账期
    v_at_MONTH_DATE := CONCAT(SUBSTR(P_DATA_DATE,1,7));
    -- 年账期
    v_at_YEAR_DATE := CONCAT(SUBSTR(P_DATA_DATE,1,4));
    -- 获取表名
    SELECT TABLE_NAME INTO V_TABLE_NAME FROM adm.trs_guoku_saiku_processing WHERE  ID=V_SQL_ID;
    -- 获取删除语句SQL
    SELECT SQL_DELETE INTO V_SQL_DELETE FROM adm.trs_guoku_saiku_processing WHERE  ID=V_SQL_ID;
    -- 获取插数语句SQL
    SELECT SQL_INSERT INTO V_SQL_INSERT FROM adm.trs_guoku_saiku_processing WHERE  ID=V_SQL_ID;
    
    -- 删除步骤开始
    V_STEP_ID := V_STEP_ID + 1;
    -- 更新步骤信息
    V_STEP_NAME := CONCAT('删除',V_TABLE_NAME,'该日期下的数据');
    -- 封装删除语句
    v_at_V_SQLTXT := CONCAT(V_SQL_DELETE,'WHERE REPORTDATE = ',CONCAT("'",SUBSTR(P_DATA_DATE,1,7),"-01'"));
  select v_at_V_SQLTXT;
    -- 准备删除
    EXECUTE IMMEDIATE v_at_V_SQLTXT;
 
    -- 执行删除
    -- ETL记录删除结果
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    -- 删除步骤结束
    
    -- 插数步骤开始
    V_STEP_ID := V_STEP_ID + 1;
    -- 更新步骤信息
    V_STEP_NAME := CONCAT('增加',V_TABLE_NAME,'该日期下的数据');
    -- 封装插数语句
                                                
    v_at_V_SQLTXT := concat(V_SQL_INSERT ,'WHERE b.d_expfile = ',CONCAT("'",P_DATA_DATE,"'"));
    -- 准备插数
    
    --  SELECT v_at_V_SQLTXT;
    EXECUTE IMMEDIATE v_at_V_SQLTXT;
    -- 执行插数
     
    -- ETL记录插数结果
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    -- 插数步骤结束
    
    COMMIT; -- 提交事务  
    END LOOP PROC_CURSOR; -- 结束自定义循环体  
    CLOSE PROC_CURSOR; -- 关闭游标
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
END;
/

DROP PROCEDURE IF EXISTS adm.p_nan_real_estate;

CREATE PROCEDURE adm.p_nan_real_estate(IN P_DATA_DATE VARCHAR(8),OUT P_RESULT   INT)
AS
    V_PROC_NAME VARCHAR(200) := 'adm.p_nan_real_estate.prc';
    V_STEP INT := 0;
    V_START_TIME VARCHAR(20) := NOW();
    V_DATA_DATE VARCHAR(6) := SUBSTR(P_DATA_DATE,1,6);    
    V_DATA_DATE_P VARCHAR(6) := SUBSTR(DATE_FORMAT(DATE_SUB(DATE_FORMAT(P_DATA_DATE,'%Y%m%d'),INTERVAL 1 MONTH),'%Y%m%d'),1,6);
    V_DATA_DATE_L VARCHAR(6) := SUBSTR(DATE_FORMAT(DATE_SUB(DATE_FORMAT(P_DATA_DATE,'%Y%m%d'),INTERVAL 12 MONTH),'%Y%m%d'),1,6);
    V_DATA_DATE_L_P VARCHAR(6) := SUBSTR(DATE_FORMAT(DATE_SUB(DATE_FORMAT(P_DATA_DATE,'%Y%m%d'),INTERVAL 13 MONTH),'%Y%m%d'),1,6);
    V_DATA_END_Y VARCHAR(6) := CONCAT(SUBSTR(P_DATA_DATE,1,4)-1,'12');          -- 上年末
    V_DATA_END_Y_L VARCHAR(6) := CONCAT(SUBSTR(P_DATA_DATE,1,4)-2,'12');        -- 上上年末
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
/*
| Author :严锦涛
| Name :adm.ana_glr_mth_small_micro_map
| FUNCTION:
| Purpose:货币信贷-专题分析-房地产分析
|         edw.glr_rel_estate_loan_direct_dist|房地产贷款投向统计分地区表|adm.ana_glr_mth_real_estate_loans
|         edw.glr_rel_estate_loan_direct_org |房地产贷款投向统计分机构表|adm.ana_glr_mth_real_estate_loans_org
|
|
| VER         DATE        AUTHOR           DESCRIPTION
| ---------  ----------  ---------------  ------------------------------------
| 1.0        2018-12-27     严锦涛        1.CREATES THE PROCEDURE
*/     
    
    
    
    P_RESULT := 0;
    SET V_STEP:='1';
    DELETE  FROM adm.ana_glr_mth_real_estate_loans WHERE FISCAL_MTH = V_DATA_DATE;
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
    SET V_STEP:='2';
    INSERT INTO adm.ana_glr_mth_real_estate_loans (
	        FISCAL_DATE                   -- 日期
	       ,FISCAL_MTH                    -- 月份
	       ,AREA_NO_ID                    -- 区县编码
	       ,AREA_DSCR                     -- 区县名称
	       ,REAL_ESTATE_LOANS_TYPE1_ID    -- 房地产贷款类型ID
	       ,LOANS_TYPE1_DSCR              -- 房地产贷款类型1描述  ()
	       ,SERVICE_TYPE                  -- 业务统计类型
	       ,LOAN_AMOUNT                   -- 贷款金额
	       ,LOAN_AMOUNT_LY                -- 去年同期贷款金额
	)
    -- 1.1(合计)  余额当月新增  
    SELECT 
     CONCAT(V_DATA_DATE,'01')
	,V_DATA_DATE
	,r.area_no_id
	,t.org_name
	,'1'
	,'合计'
	,'贷款余额当月新增'
	,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(LOAN_BALANCE_SUM,0) ELSE 0 END )/10000 - SUM(CASE WHEN data_date = v_data_date_p THEN IFNULL(LOAN_BALANCE_SUM,0) ELSE 0 END )/10000  AS LOAN_AMOUNT
	,SUM(CASE WHEN data_date = v_data_date_l THEN IFNULL(LOAN_BALANCE_SUM,0) ELSE 0 END )/10000 - SUM(CASE WHEN data_date = v_data_date_l_p THEN IFNULL(LOAN_BALANCE_SUM,0) ELSE 0 END )/10000  AS LOAN_AMOUNT_LY
     FROM edw.glr_rel_estate_loan_direct_dist T 
     LEFT JOIN edw.cm_glr_area_code R
     ON t.org_name = r.area_dscr
     GROUP BY 
     r.area_no_id
    ,t.org_name
     	
     UNION ALL	
     -- 1.2.(合计)   贷款余额当年新增  (本期-上年末)
     SELECT 
         CONCAT(V_DATA_DATE,'01')
	,V_DATA_DATE
	,r.area_no_id
	,t.org_name
	,'2'
	,'合计'
	,'贷款余额当年新增'
	,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(LOAN_BALANCE_SUM,0) ELSE 0 END )/10000 - SUM(CASE WHEN data_date = V_DATA_END_Y THEN IFNULL(LOAN_BALANCE_SUM,0) ELSE 0 END )/10000   AS LOAN_AMOUNT
	,SUM(CASE WHEN data_date = v_data_date_l THEN IFNULL(LOAN_BALANCE_SUM,0) ELSE 0 END )/10000 - SUM(CASE WHEN data_date = V_DATA_END_Y_L THEN IFNULL(LOAN_BALANCE_SUM,0) ELSE 0 END )/10000   AS LOAN_AMOUNT_LY
     FROM edw.glr_rel_estate_loan_direct_dist T 
     LEFT JOIN edw.cm_glr_area_code R
     ON t.org_name = r.area_dscr
     GROUP BY 
         r.area_no_id
	,t.org_name
     
     UNION ALL
     -- 1.3.(合计)  贷款余额
     SELECT 
         CONCAT(V_DATA_DATE,'01')
	,V_DATA_DATE
	,r.area_no_id
	,t.org_name
	,'3'
	,'合计'
	,'贷款余额'
	,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(LOAN_BALANCE_SUM,0) ELSE 0 END )/10000  AS LOAN_AMOUNT
	,SUM(CASE WHEN data_date = v_data_date_l THEN IFNULL(LOAN_BALANCE_SUM,0) ELSE 0 END )/10000   AS LOAN_AMOUNT_LY
     FROM edw.glr_rel_estate_loan_direct_dist T 
     LEFT JOIN edw.cm_glr_area_code R
     ON t.org_name = r.area_dscr
     GROUP BY 
         r.area_no_id
	,t.org_name
	
	UNION ALL
	
	-- 2.1房地产开发贷款 贷款余额当月新增
   	SELECT 
         CONCAT(V_DATA_DATE,'01')
	,V_DATA_DATE
	,r.area_no_id
	,t.org_name
	,'4'
	,'房地产开发贷款'
	,'贷款余额当月新增'
	,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(LOAN_BAL_REAL_ESTATE,0) ELSE 0 END )/10000 - SUM(CASE WHEN data_date = v_data_date_p THEN IFNULL(LOAN_BAL_REAL_ESTATE,0) ELSE 0 END )/10000  AS LOAN_AMOUNT
	,SUM(CASE WHEN data_date = v_data_date_l THEN IFNULL(LOAN_BAL_REAL_ESTATE,0) ELSE 0 END )/10000 - SUM(CASE WHEN data_date = v_data_date_l_p THEN IFNULL(LOAN_BAL_REAL_ESTATE,0) ELSE 0 END )/10000  AS LOAN_AMOUNT_LY
     FROM edw.glr_rel_estate_loan_direct_dist T 
     LEFT JOIN edw.cm_glr_area_code R
     ON t.org_name = r.area_dscr
     GROUP BY 
        r.area_no_id
       ,t.org_name
        
        UNION ALL     
     
        -- 2.2房地产开发贷款 贷款余额当年新增
   	SELECT 
         CONCAT(V_DATA_DATE,'01')
	,V_DATA_DATE
	,r.area_no_id
	,t.org_name
	,'5'
	,'房地产开发贷款'
	,'贷款余额当年新增'
	,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(LOAN_BAL_REAL_ESTATE,0) ELSE 0 END )/10000 - SUM(CASE WHEN data_date = V_DATA_END_Y THEN IFNULL(LOAN_BAL_REAL_ESTATE,0) ELSE 0 END )/10000   AS LOAN_AMOUNT
	,SUM(CASE WHEN data_date = v_data_date_l THEN IFNULL(LOAN_BAL_REAL_ESTATE,0) ELSE 0 END )/10000 - SUM(CASE WHEN data_date = V_DATA_END_Y_L THEN IFNULL(LOAN_BAL_REAL_ESTATE,0) ELSE 0 END )/10000   AS LOAN_AMOUNT_LY
     FROM edw.glr_rel_estate_loan_direct_dist T 
     LEFT JOIN edw.cm_glr_area_code R
     ON t.org_name = r.area_dscr
     GROUP BY 
         r.area_no_id
	,t.org_name
	
	
	UNION ALL
	-- 2.3房地产开发贷款 贷款余额
	SELECT 
         CONCAT(V_DATA_DATE,'01')
	,V_DATA_DATE
	,r.area_no_id
	,t.org_name
	,'6'
	,'房地产开发贷款'
	,'贷款余额'
	,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(LOAN_BAL_REAL_ESTATE,0) ELSE 0 END )/10000  AS LOAN_AMOUNT
	,SUM(CASE WHEN data_date = v_data_date_l THEN IFNULL(LOAN_BAL_REAL_ESTATE,0) ELSE 0 END )/10000   AS LOAN_AMOUNT_LY
     FROM edw.glr_rel_estate_loan_direct_dist T 
     LEFT JOIN edw.cm_glr_area_code R
     ON t.org_name = r.area_dscr
     GROUP BY 
         r.area_no_id
	,t.org_name
        
        UNION ALL 
        -- 3.1 个人购房贷款   贷款余额当月新增	
	SELECT 
         CONCAT(V_DATA_DATE,'01')
	,V_DATA_DATE
	,r.area_no_id
	,t.org_name
	,'7'
	,'购房贷款'
	,'贷款余额当月新增'
	,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(LOAN_BAL_PERSON,0) ELSE 0 END )/10000 - SUM(CASE WHEN data_date = v_data_date_p THEN IFNULL(LOAN_BAL_PERSON,0) ELSE 0 END )/10000  AS LOAN_AMOUNT
	,SUM(CASE WHEN data_date = v_data_date_l THEN IFNULL(LOAN_BAL_PERSON,0) ELSE 0 END )/10000 - SUM(CASE WHEN data_date = v_data_date_l_p THEN IFNULL(LOAN_BAL_PERSON,0) ELSE 0 END )/10000  AS LOAN_AMOUNT_LY
     FROM edw.glr_rel_estate_loan_direct_dist T
     LEFT JOIN edw.cm_glr_area_code R
     ON t.org_name = r.area_dscr 
     GROUP BY 
         r.area_no_id
	,t.org_name
	
	UNION ALL
	-- 3.2 个人购房贷款   贷款余额当年新增
        SELECT 
         CONCAT(V_DATA_DATE,'01')
	,V_DATA_DATE
	,r.area_no_id
	,t.org_name
	,'8'
	,'购房贷款'
	,'贷款余额当年新增'
	,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(LOAN_BAL_PERSON,0) ELSE 0 END )/10000 - SUM(CASE WHEN data_date = V_DATA_END_Y THEN IFNULL(LOAN_BAL_PERSON,0) ELSE 0 END )/10000   AS LOAN_AMOUNT
	,SUM(CASE WHEN data_date = v_data_date_l THEN IFNULL(LOAN_BAL_PERSON,0) ELSE 0 END )/10000 - SUM(CASE WHEN data_date = V_DATA_END_Y_L THEN IFNULL(LOAN_BAL_PERSON,0) ELSE 0 END )/10000   AS LOAN_AMOUNT_LY
     FROM edw.glr_rel_estate_loan_direct_dist T 
     LEFT JOIN edw.cm_glr_area_code R
     ON t.org_name = r.area_dscr 
     GROUP BY 
         r.area_no_id
	,t.org_name
	
        
        UNION  ALL
        -- 3.3 个人购房贷款   贷款余额
        SELECT 
         CONCAT(V_DATA_DATE,'01')
	,V_DATA_DATE
	,r.area_no_id
	,t.org_name
	,'9'
	,'购房贷款'
	,'贷款余额'
	,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(LOAN_BAL_PERSON,0) ELSE 0 END )/10000  AS LOAN_AMOUNT
	,SUM(CASE WHEN data_date = v_data_date_l THEN IFNULL(LOAN_BAL_PERSON,0) ELSE 0 END )/10000   AS LOAN_AMOUNT_LY
     FROM edw.glr_rel_estate_loan_direct_dist T
     LEFT JOIN edw.cm_glr_area_code R
     ON t.org_name = r.area_dscr  
     GROUP BY 
         r.area_no_id
	,t.org_name
     ;
     CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
     
     
     
    
    SET V_STEP:='3';
    DELETE  FROM adm.ana_glr_mth_real_estate_loans_org WHERE FISCAL_MTH = V_DATA_DATE;
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
     
    SET V_STEP:='4';
    INSERT INTO adm.ana_glr_mth_real_estate_loans_org (
	        FISCAL_DATE           -- 日期
	       ,FISCAL_MTH            -- 月份
	       ,ORG_ID                -- 金融机构编码
	       ,ORG_NAME              -- 金融机构名称
	       ,SERVICE_TYPE          -- 业务统计类型
	       ,LOAN_AMOUNT           -- 贷款金额
	) 
     -- 1.贷款余额当月新增
     SELECT 
         CONCAT(V_DATA_DATE,'01')
	,V_DATA_DATE
	,CASE ORG_NAME 
		WHEN  '中国工商银行'                   THEN     'C1010211000012'
		WHEN  '中国农业银行'                   THEN     'C1010311000014'
		WHEN  '中国银行'                       THEN     'C1010411000013'
		WHEN  '中国建设银行'                   THEN     'C1010511003703'
		WHEN  '重庆农村商业银行'               THEN     'C1126750000032'
		WHEN  '交通银行'                       THEN     'C1030131001288'
		WHEN  '中信银行'                       THEN     'C1030211000389'
		WHEN  '中国光大银行'                   THEN     'C1030311000455'
		WHEN  '华夏银行'                       THEN     'C1030411000431'
		WHEN  '广发银行'                       THEN     'C1030644021075'
		WHEN  '平安银行'                       THEN     'C1030744001296'
		WHEN  '招商银行'                       THEN     'C1030844001362'
		WHEN  '浦东发展银行'                   THEN     'C1031031001312'
		WHEN  '兴业银行'                       THEN     'C1030935001347'
		WHEN  '中国民生银行'                   THEN     'C1030511000483'
		WHEN  '恒丰银行'                       THEN     'C1031537000883'
		WHEN  '浙商银行'                       THEN     'C1031633000292'
		WHEN  '渤海银行'                       THEN     'C1031812000205'
		WHEN  '重庆银行'                       THEN     'C1093150000010'
		WHEN  '成都市商业银行'                 THEN     'C1078851000017'
		WHEN  '哈尔滨市商业银行'               THEN     'C1085523000014'
		WHEN  '广东南粤银行股份有限公司'       THEN     'C1083044000019'
		WHEN  '大连银行'                       THEN     'C1081021000044'
		WHEN  '富滇银行'                       THEN     'C1091753000015'
		WHEN  '厦门银行'                       THEN     'C1082435000010'
		WHEN  '三峡银行'                       THEN     'C1093250000011'
		WHEN  '汉口银行'                       THEN     'C1085642000133'
		WHEN  '中国邮政储蓄银行'               THEN     'C1040311005293'
		WHEN  '国家开发银行'                   THEN     'C1020111000021'
		WHEN  '进出口银行'                     THEN     'C1020211000034'
		WHEN  '农业发展银行'                   THEN     'C1020311000163'
		WHEN  '重庆富民银行股份有限公司'       THEN     'C1352150000016'
		WHEN  '村镇银行'                       THEN     'C0000000000000'
		WHEN  '新华信托投资股份有限公司'       THEN     'D1006450000011'
		WHEN  '重庆国际信托投资有限公司'       THEN     'D1006550000012'
		WHEN  '重庆化医控股集团财务有限公司'   THEN     'C5012650000014'
		WHEN  '重庆机电控股集团财务有限公司'   THEN     'C5015250000029'
		WHEN  '重庆力帆财务有限公司'           THEN     'C5018850000014'
		WHEN  '重庆市能源投资集团财务有限公司' THEN     'C5020350000017'
		WHEN  '昆仑金融租赁有限责任公司'       THEN     'D3002550000015'
		WHEN  '渝农商金融租赁有限公司'         THEN     'D3003150000017'
		WHEN  '重庆汽车金融有限公司'           THEN     'D4001550000016'
		WHEN  '重庆鈊渝金融租赁有限公司'       THEN     'D3008550000011'
		WHEN  '贷款公司'                       THEN     'Z1142850000012'
		ELSE '9999'
	END AS ORG_ID 
