		WHEN  '昆仑金融租赁有限责任公司'       THEN     'D3002550000015'
		WHEN  '渝农商金融租赁有限公司'         THEN     'D3003150000017'
		WHEN  '重庆汽车金融有限公司'           THEN     'D4001550000016'
		WHEN  '重庆鈊渝金融租赁有限公司'       THEN     'D3008550000011'
		WHEN  '贷款公司'                       THEN     'Z1142850000012'
		ELSE '9999'
	END
	,t.org_name
	
	union all
	
	-- 3.贷款余额
	SELECT 
         CONCAT(V_DATA_DATE,'01')
	,V_DATA_DATE
	,CASE ORG_NAME 
		WHEN  '中国工商银行'                   THEN     'C1010211000012'
		WHEN  '中国农业银行'                   THEN     'C1010311000014'
		WHEN  '中国银行'                       THEN     'C1010411000013'
		WHEN  '中国建设银行'                   THEN     'C1010511003703'
		WHEN  '重庆农村商业银行'               THEN     'C1126750000032'
		WHEN  '交通银行'                       THEN     'C1030131001288'
		WHEN  '中信银行'                       THEN     'C1030211000389'
		WHEN  '中国光大银行'                   THEN     'C1030311000455'
		WHEN  '华夏银行'                       THEN     'C1030411000431'
		WHEN  '广发银行'                       THEN     'C1030644021075'
		WHEN  '平安银行'                       THEN     'C1030744001296'
		WHEN  '招商银行'                       THEN     'C1030844001362'
		WHEN  '浦东发展银行'                   THEN     'C1031031001312'
		WHEN  '兴业银行'                       THEN     'C1030935001347'
		WHEN  '中国民生银行'                   THEN     'C1030511000483'
		WHEN  '恒丰银行'                       THEN     'C1031537000883'
		WHEN  '浙商银行'                       THEN     'C1031633000292'
		WHEN  '渤海银行'                       THEN     'C1031812000205'
		WHEN  '重庆银行'                       THEN     'C1093150000010'
		WHEN  '成都市商业银行'                 THEN     'C1078851000017'
		WHEN  '哈尔滨市商业银行'               THEN     'C1085523000014'
		WHEN  '广东南粤银行股份有限公司'       THEN     'C1083044000019'
		WHEN  '大连银行'                       THEN     'C1081021000044'
		WHEN  '富滇银行'                       THEN     'C1091753000015'
		WHEN  '厦门银行'                       THEN     'C1082435000010'
		WHEN  '三峡银行'                       THEN     'C1093250000011'
		WHEN  '汉口银行'                       THEN     'C1085642000133'
		WHEN  '中国邮政储蓄银行'               THEN     'C1040311005293'
		WHEN  '国家开发银行'                   THEN     'C1020111000021'
		WHEN  '进出口银行'                     THEN     'C1020211000034'
		WHEN  '农业发展银行'                   THEN     'C1020311000163'
		WHEN  '重庆富民银行股份有限公司'       THEN     'C1352150000016'
		WHEN  '村镇银行'                       THEN     'C0000000000000'
		WHEN  '新华信托投资股份有限公司'       THEN     'D1006450000011'
		WHEN  '重庆国际信托投资有限公司'       THEN     'D1006550000012'
		WHEN  '重庆化医控股集团财务有限公司'   THEN     'C5012650000014'
		WHEN  '重庆机电控股集团财务有限公司'   THEN     'C5015250000029'
		WHEN  '重庆力帆财务有限公司'           THEN     'C5018850000014'
		WHEN  '重庆市能源投资集团财务有限公司' THEN     'C5020350000017'
		WHEN  '昆仑金融租赁有限责任公司'       THEN     'D3002550000015'
		WHEN  '渝农商金融租赁有限公司'         THEN     'D3003150000017'
		WHEN  '重庆汽车金融有限公司'           THEN     'D4001550000016'
		WHEN  '重庆鈊渝金融租赁有限公司'       THEN     'D3008550000011'
		WHEN  '贷款公司'                       THEN     'Z1142850000012'
		ELSE '9999'
	END AS ORG_ID 
	,t.org_name
	,'贷款余额'
	,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN  IFNULL(LOAN_BAL_TOTAL,0) ELSE 0 END)/10000  AS LOAN_AMOUNT
     FROM edw.glr_rel_estate_loan_direct_org  T
     GROUP BY 
        CASE ORG_NAME 
		WHEN  '中国工商银行'                   THEN     'C1010211000012'
		WHEN  '中国农业银行'                   THEN     'C1010311000014'
		WHEN  '中国银行'                       THEN     'C1010411000013'
		WHEN  '中国建设银行'                   THEN     'C1010511003703'
		WHEN  '重庆农村商业银行'               THEN     'C1126750000032'
		WHEN  '交通银行'                       THEN     'C1030131001288'
		WHEN  '中信银行'                       THEN     'C1030211000389'
		WHEN  '中国光大银行'                   THEN     'C1030311000455'
		WHEN  '华夏银行'                       THEN     'C1030411000431'
		WHEN  '广发银行'                       THEN     'C1030644021075'
		WHEN  '平安银行'                       THEN     'C1030744001296'
		WHEN  '招商银行'                       THEN     'C1030844001362'
		WHEN  '浦东发展银行'                   THEN     'C1031031001312'
		WHEN  '兴业银行'                       THEN     'C1030935001347'
		WHEN  '中国民生银行'                   THEN     'C1030511000483'
		WHEN  '恒丰银行'                       THEN     'C1031537000883'
		WHEN  '浙商银行'                       THEN     'C1031633000292'
		WHEN  '渤海银行'                       THEN     'C1031812000205'
		WHEN  '重庆银行'                       THEN     'C1093150000010'
		WHEN  '成都市商业银行'                 THEN     'C1078851000017'
		WHEN  '哈尔滨市商业银行'               THEN     'C1085523000014'
		WHEN  '广东南粤银行股份有限公司'       THEN     'C1083044000019'
		WHEN  '大连银行'                       THEN     'C1081021000044'
		WHEN  '富滇银行'                       THEN     'C1091753000015'
		WHEN  '厦门银行'                       THEN     'C1082435000010'
		WHEN  '三峡银行'                       THEN     'C1093250000011'
		WHEN  '汉口银行'                       THEN     'C1085642000133'
		WHEN  '中国邮政储蓄银行'               THEN     'C1040311005293'
		WHEN  '国家开发银行'                   THEN     'C1020111000021'
		WHEN  '进出口银行'                     THEN     'C1020211000034'
		WHEN  '农业发展银行'                   THEN     'C1020311000163'
		WHEN  '重庆富民银行股份有限公司'       THEN     'C1352150000016'
		WHEN  '村镇银行'                       THEN     'C0000000000000'
		WHEN  '新华信托投资股份有限公司'       THEN     'D1006450000011'
		WHEN  '重庆国际信托投资有限公司'       THEN     'D1006550000012'
		WHEN  '重庆化医控股集团财务有限公司'   THEN     'C5012650000014'
		WHEN  '重庆机电控股集团财务有限公司'   THEN     'C5015250000029'
		WHEN  '重庆力帆财务有限公司'           THEN     'C5018850000014'
		WHEN  '重庆市能源投资集团财务有限公司' THEN     'C5020350000017'
		WHEN  '昆仑金融租赁有限责任公司'       THEN     'D3002550000015'
		WHEN  '渝农商金融租赁有限公司'         THEN     'D3003150000017'
		WHEN  '重庆汽车金融有限公司'           THEN     'D4001550000016'
		WHEN  '重庆鈊渝金融租赁有限公司'       THEN     'D3008550000011'
		WHEN  '贷款公司'                       THEN     'Z1142850000012'
		ELSE '9999'
	END
	,t.org_name
     ;
     CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
     
     
    -- ======================================房地产贷款各项目占比分析表===================================================
    SET V_STEP:='5';
    DELETE  FROM adm.ana_glr_mth_real_estate_loans_rate WHERE FISCAL_MTH = V_DATA_DATE;
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
    SET V_STEP:='6';
    insert into adm.ana_glr_mth_real_estate_loans_rate (
	 FISCAL_DATE               -- 日期
	,FISCAL_MTH                -- 月份
	,SERVICE_TYPE              -- 业务统计类型
	,REAL_ESTATE_LOANS         -- 房地产贷款金额
	,REAL_ESTATE_LOANS_DEV     -- 房地产开发贷款金额
	,REAL_ESTATE_LOANS_PER     -- 个人住房贷款金额
	,LOANS_TOTAL               -- 各项贷款金额
	)
     select 
        ds1.fiscal_date
       ,ds1.fiscal_mth   
       ,ds1.service_type
       ,ds1.real_estate_loans
       ,ds1.real_estate_loans_dev
       ,ds1.real_estate_loans_per
       ,ds2.loan_all
     from (	
	
     -- 1.贷款余额    
      SELECT 
         concat(v_data_date ,'01') as FISCAL_DATE
	,v_data_date as FISCAL_MTH
	,'贷款余额' as  SERVICE_TYPE
	,SUM(case when data_date = v_data_date then IFNULL(LOAN_BAL_TOTAL,0) else 0 end )/10000   as REAL_ESTATE_LOANS
	,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(LOAN_BAL_DEV_HOUS,0) ELSE 0 END )/10000   AS REAL_ESTATE_LOANS_DEV
	,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(LOAN_BAL_PERS_LIVE,0) ELSE 0 END )/10000   AS REAL_ESTATE_LOANS_PER
      FROM edw.glr_rel_estate_loan_direct_org  T    -- 房地产-房地产贷款投向统计分机构表
     )ds1 
     join 
     (
       select 
         sum(ifnull(loan_balance,0)) as loan_all
       from edw.glr_mpa_all_cny_credit T    -- 重庆市全金融机构人民币信贷收支合并表 各项贷款
       where t.rows_id = 3
        and data_date = v_data_date 
     )ds2
     on  1=1 
     
    union  all
     select 
        ds3.fiscal_date
       ,ds3.fiscal_mth
       ,ds3.service_type
       ,ds3.real_estate_loans
       ,ds3.real_estate_loans_dev
       ,ds3.real_estate_loans_per
       ,ds4.loan_all
     from (
     
     -- 贷款余额当月新增 
     SELECT 
         CONCAT(v_data_date ,'01') as FISCAL_DATE
	,v_data_date  as FISCAL_MTH
	,'贷款余额当月新增' as SERVICE_TYPE
	,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(LOAN_BAL_TOTAL,0) ELSE 0 END )/10000 -SUM(CASE WHEN data_date = v_data_date_p THEN IFNULL(LOAN_BAL_TOTAL,0) ELSE 0 END )/10000  AS REAL_ESTATE_LOANS
	,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(LOAN_BAL_DEV_HOUS,0) ELSE 0 END )/10000 -SUM(CASE WHEN data_date = v_data_date_p THEN IFNULL(LOAN_BAL_DEV_HOUS,0) ELSE 0 END )/10000  AS REAL_ESTATE_LOANS_DEV
	,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(LOAN_BAL_PERS_LIVE,0) ELSE 0 END )/10000 -SUM(CASE WHEN data_date = v_data_date_p THEN IFNULL(LOAN_BAL_PERS_LIVE,0) ELSE 0 END )/10000  AS REAL_ESTATE_LOANS_PER
     FROM edw.glr_rel_estate_loan_direct_org  T    -- 房地产-房地产贷款投向统计分机构表
    ) ds3
    join 
    (
       SELECT 
         SUM(case when data_date = v_data_date then IFNULL(loan_balance,0) else 0 end ) - SUM(CASE WHEN data_date = v_data_date_p THEN IFNULL(loan_balance,0) ELSE 0 END ) AS loan_all
       FROM edw.glr_mpa_all_cny_credit T    -- 重庆市全金融机构人民币信贷收支合并表 各项贷款
       WHERE t.rows_id = 3
     
    ) ds4     
    on 1 =1 
     
   union all
   
   select  
        ds5.fiscal_date
       ,ds5.fiscal_mth
       ,ds5.service_type
       ,ds5.real_estate_loans
       ,ds5.real_estate_loans_dev
       ,ds5.real_estate_loans_per
       ,ds6.loan_all
   from (
     -- 贷款余额当年新增
     SELECT 
         CONCAT(v_data_date ,'01') as FISCAL_DATE
	,v_data_date as FISCAL_MTH
	,'贷款余额当年新增' as SERVICE_TYPE
	,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(LOAN_BAL_TOTAL,0) ELSE 0 END )/10000 -SUM(CASE WHEN data_date = V_DATA_END_Y THEN IFNULL(LOAN_BAL_TOTAL,0) ELSE 0 END )/10000  AS REAL_ESTATE_LOANS
	,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(LOAN_BAL_DEV_HOUS,0) ELSE 0 END )/10000 -SUM(CASE WHEN data_date = V_DATA_END_Y THEN IFNULL(LOAN_BAL_DEV_HOUS,0) ELSE 0 END )/10000 AS REAL_ESTATE_LOANS_DEV
	,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(LOAN_BAL_PERS_LIVE,0) ELSE 0 END )/10000 -SUM(CASE WHEN data_date = V_DATA_END_Y THEN IFNULL(LOAN_BAL_PERS_LIVE,0) ELSE 0 END )/10000 AS REAL_ESTATE_LOANS_PER
     FROM edw.glr_rel_estate_loan_direct_org  T    -- 房地产-房地产贷款投向统计分机构表
   )ds5 
   join 
   (
       SELECT 
         SUM(CASE WHEN data_date = v_data_date THEN IFNULL(loan_balance,0) ELSE 0 END ) - SUM(CASE WHEN data_date = V_DATA_END_Y THEN IFNULL(loan_balance,0) ELSE 0 END ) AS loan_all
       FROM edw.glr_mpa_all_cny_credit T    -- 重庆市全金融机构人民币信贷收支合并表 各项贷款
       WHERE t.rows_id = 3
   ) ds6 
   on 1=1
    ;
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
    
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
END;
/

DROP PROCEDURE IF EXISTS adm.p_nan_real_estate_bak20190122;

CREATE PROCEDURE adm.p_nan_real_estate_bak20190122(IN P_DATA_DATE VARCHAR(8),OUT P_RESULT   INT)
AS
    V_PROC_NAME VARCHAR(200) := 'p_ana_small_micro_enterprise.prc';
    V_STEP INT := 0;
    V_START_TIME VARCHAR(20) := NOW();
    V_DATA_DATE VARCHAR(6) := SUBSTR(P_DATA_DATE,1,6);
    V_DATA_DATE_L VARCHAR(6) := SUBSTR(DATE_FORMAT(DATE_SUB(DATE_FORMAT(P_DATA_DATE,'%Y%m%d'),INTERVAL 12 MONTH),'%Y%m%d'),1,6);
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
/*
| Author :严锦涛
| Name :adm.ana_glr_mth_small_micro_map
| FUNCTION:
| Purpose:货币信贷-专题分析-房地产分析
|         edw.glr_rel_estate_loan_direct_dist|房地产贷款投向统计分地区表|adm.ana_glr_mth_real_estate_loans
|         edw.glr_rel_estate_loan_direct_org |房地产贷款投向统计分机构表|adm.ana_glr_mth_real_estate_loans_org
|
|
| VER         DATE        AUTHOR           DESCRIPTION
| ---------  ----------  ---------------  ------------------------------------
| 1.0        2018-12-27     严锦涛        1.CREATES THE PROCEDURE
*/     
    


    P_RESULT := 0;

    SET V_STEP:='1';
    DELETE  FROM adm.ana_glr_mth_real_estate_loans WHERE DATA_DATE = V_DATA_DATE;
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
    SET V_STEP:='2';
    -- 货币信贷-专题分析-房地产分析(分地区)
    insert into ana_glr_mth_real_estate_loans 
	(
	  FISCAL_DATE
	, FISCAL_MTH
	, AREA_NO_ID
	, AREA_DSCR
	, REAL_ESTATE_LOANS_TYPE1_ID
	, LOANS_TYPE1_DSCR
	, LOANS_TYPE2_DSCR
	, LOAN_REMAIN
	, LOAN_REMAIN_LY
	)
     -- 1.房地产开发贷款:地产开发贷款|房产开发贷款 
     SELECT 
	concat(V_DATA_DATE,'01')
	,V_DATA_DATE
	,CASE  ORG_NAME
	WHEN   '重庆市'                 THEN    '500000'
	WHEN   '万州区'                 THEN    '500101'
	WHEN   '涪陵区'                 THEN    '500102'
	WHEN   '渝中区'                 THEN    '500103'
	WHEN   '大渡口区'               THEN    '500104'
	WHEN   '江北区'                 THEN    '500105'
	WHEN   '沙坪坝区'               THEN    '500106'
	WHEN   '九龙坡区'               THEN    '500107'
	WHEN   '南岸区'                 THEN    '500108'
	WHEN   '北碚区'                 THEN    '500109'
	WHEN   '綦江区'                 THEN    '500110'
	WHEN   '大足区'                 THEN    '500111'
	WHEN   '渝北区'                 THEN    '500112'
	WHEN   '巴南区'                 THEN    '500113'
	WHEN   '黔江区'                 THEN    '500114'
	WHEN   '长寿区'                 THEN    '500115'
	WHEN   '江津区'                 THEN    '500116'
	WHEN   '合川区'                 THEN    '500117'
	WHEN   '永川区'                 THEN    '500118'
	WHEN   '南川区'                 THEN    '500119'
	WHEN   '璧山区'                 THEN    '500120'
	WHEN   '铜梁区'                 THEN    '500151'
	WHEN   '潼南区'                 THEN    '500152'
	WHEN   '荣昌区'                 THEN    '500153'
	WHEN   '巫山县'                 THEN    '500237'
	WHEN   '开州区'                 THEN    '500154'
	WHEN   '梁平县'                 THEN    '500228'
	WHEN   '城口县'                 THEN    '500229'
	WHEN   '丰都县'                 THEN    '500230'
	WHEN   '垫江县'                 THEN    '500231'
	WHEN   '武隆县'                 THEN    '500232'
	WHEN   '忠县'                   THEN    '500233'
	WHEN   '云阳县'                 THEN    '500235'
	WHEN   '奉节县'                 THEN    '500236'
	WHEN   '巫溪县'                 THEN    '500238'
	WHEN   '石柱土家族自治县'       THEN    '500240'
	WHEN   '秀山土家族苗族自治县'   THEN    '500241'
	WHEN   '酉阳土家族苗族自治县'   THEN    '500242'
	WHEN   '彭水苗族土家族自治县'   THEN    '500243'
	ELSE '9999'
	END AS AREA_NO
	,ORG_NAME AS AREA_DSCR
	,'1' AS REAL_ESTATE_LOANS_TYPE1_ID
	,'房地产开发贷款' AS LOANS_TYPE1_DSCR
	,'地产开发贷款' AS LOANS_TYPE2_DSCR
	,SUM(CASE WHEN DATA_DATE=V_DATA_DATE   THEN  IFNULL(LOAN_BAL_LAND,0) ELSE 0 END ) AS LOAN_REMAIN
	,SUM(CASE WHEN DATA_DATE=V_DATA_DATE_L THEN  IFNULL(LOAN_BAL_LAND,0) ELSE 0 END ) AS LOAN_REMAIN_LY
	FROM edw.glr_rel_estate_loan_direct_dist

	GROUP BY
	CASE  ORG_NAME
	WHEN    '重庆市'                  THEN    '500000'
	WHEN    '万州区'                  THEN    '500101'
	WHEN    '涪陵区'                  THEN    '500102'
	WHEN    '渝中区'                  THEN    '500103'
	WHEN    '大渡口区'                THEN    '500104'
	WHEN    '江北区'                  THEN    '500105'
	WHEN    '沙坪坝区'                THEN    '500106'
	WHEN    '九龙坡区'                THEN    '500107'
	WHEN    '南岸区'                  THEN    '500108'
	WHEN    '北碚区'                  THEN    '500109'
	WHEN    '綦江区'                  THEN    '500110'
	WHEN    '大足区'                  THEN    '500111'
	WHEN    '渝北区'                  THEN    '500112'
	WHEN    '巴南区'                  THEN    '500113'
	WHEN    '黔江区'                  THEN    '500114'
	WHEN    '长寿区'                  THEN    '500115'
	WHEN    '江津区'                  THEN    '500116'
	WHEN    '合川区'                  THEN    '500117'
	WHEN    '永川区'                  THEN    '500118'
	WHEN    '南川区'                  THEN    '500119'
