DROP PROCEDURE IF EXISTS adm.p_rpt_m_loan_indust_dist;

CREATE PROCEDURE adm.p_rpt_m_loan_indust_dist(
    IN P_DATA_DATE VARCHAR(8)
    ,OUT P_RESULT   INT)
AS
    V_PROC_NAME VARCHAR(200) := 'adm.p_rpt_m_loan_indust_dist.prc';
    V_STEP INT := 0;
    V_START_TIME VARCHAR(20) := NOW();
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
    /*
    Author :zhangjiao
    Name :adm.p_rpt_m_loan_indust_dist.PRC
    FUNCTION:
    Purpose:表3-2 重庆市金融机构(含外资)房地产贷款投向统计分地区表(人民币)
    VER         DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2019-01-29     ZHANGJIAO        1.CREATES THE PROCEDURE
*/     
    /* EXCEPTION HANDLER  异常处理*/
    
    
    P_RESULT := 0;
    -- 支持数据重跑
    SET V_STEP:='1';
    DELETE  FROM adm.rpt_m_loan_indust_dist WHERE DATA_DATE = SUBSTR(P_DATA_DATE,1,6) ;
    -- 业务逻辑处理
    SET V_STEP:='2' ;   
    INSERT INTO adm.rpt_m_loan_indust_dist(
             BATCH_DATE               
            ,AREA_NO                  
            ,DATA_DATE                
            ,ORG_NO
            ,ROWS_ID                   
            ,ORG_NAME                 
            ,LOAN_BALANCE_SUM         
            ,LOAN_BAL_REAL_ESTATE     
            ,LOAN_BAL_LAND            
            ,LOAN_BAL_GOV_RESVER      
            ,LOAN_BAL_DEV_HOUS        
            ,LOAN_BAL_LIVE_DEV_HOUS   
            ,LOAN_BAL_SECU_HOUS       
            ,LOAN_BAL_COMC_DEV_HOUS   
            ,LOAN_BAL_OTHER_DEV_HOUS  
            ,LOAN_BAL_PURCH_HOUS      
            ,LOAN_BAL_ENTER_PURCH_HOUS
            ,LOAN_BAL_COMMC_USE_HOUS  
            ,LOAN_BAL_LIVE_HOUS       
            ,LOAN_BAL_TEAM_PURCH_HOUS 
            ,LOAN_BAL_TEAM_COMMC_HOUS 
            ,LOAN_BAL_TEAM_LIVE_HOUS  
            ,LOAN_BAL_PERSON          
            ,LOAN_BAL_COMMC_PERSON    
            ,LOAN_BAL_LIVE_PERSON     
            ,LOAN_BAL_DEV_NEW         
            ,LOAN_BAL_MORTGAGE        
            ,LOAN_BAL_RETRANS         
            ,LOAN_BAL_STOCK           
            ,LOAN_BAL_STOCK_PERSON    
            ,LOAN_BAL_STOCK_OTHER     
            ,LOAN_BAL_LOWER_INCOME    
            ,LOAN_BAL_MERGE_PLAN      
            ,LOAN_BAL_TERM_MERGE_PLAN 
            ,LOAN_BAL_MAIN_PERSON     
            ,LOAN_BAL_DEV_ESTA_HB     
            )
     SELECT
            NOW()               
           ,AREA_NO                  
           ,DATA_DATE                
           ,ORG_NO                   
           ,ROWS_ID                  
           ,ORG_NAME                 
           ,SUM(IFNULL(LOAN_BALANCE_SUM,0))
           ,SUM(IFNULL(LOAN_BAL_REAL_ESTATE,0))
           ,SUM(IFNULL(LOAN_BAL_LAND,0))
           ,SUM(IFNULL(LOAN_BAL_GOV_RESVER,0))
           ,SUM(IFNULL(LOAN_BAL_DEV_HOUS,0))
           ,SUM(IFNULL(LOAN_BAL_LIVE_DEV_HOUS,0))
           ,SUM(IFNULL(LOAN_BAL_SECU_HOUS,0))
           ,SUM(IFNULL(LOAN_BAL_COMC_DEV_HOUS,0))
           ,SUM(IFNULL(LOAN_BAL_OTHER_DEV_HOUS,0))
           ,SUM(IFNULL(LOAN_BAL_PURCH_HOUS,0))
           ,SUM(IFNULL(LOAN_BAL_ENTER_PURCH_HOUS,0))
           ,SUM(IFNULL(LOAN_BAL_COMMC_USE_HOUS,0))
           ,SUM(IFNULL(LOAN_BAL_LIVE_HOUS,0))
           ,SUM(IFNULL(LOAN_BAL_TEAM_PURCH_HOUS,0))
           ,SUM(IFNULL(LOAN_BAL_TEAM_COMMC_HOUS,0))
           ,SUM(IFNULL(LOAN_BAL_TEAM_LIVE_HOUS,0))
           ,SUM(IFNULL(LOAN_BAL_PERSON,0))
           ,SUM(IFNULL(LOAN_BAL_COMMC_PERSON,0))
           ,SUM(IFNULL(LOAN_BAL_LIVE_PERSON,0))
           ,SUM(IFNULL(LOAN_BAL_DEV_NEW,0))
           ,SUM(IFNULL(LOAN_BAL_MORTGAGE,0))
           ,SUM(IFNULL(LOAN_BAL_RETRANS,0))
           ,SUM(IFNULL(LOAN_BAL_STOCK,0))
           ,SUM(IFNULL(LOAN_BAL_STOCK_PERSON,0))
           ,SUM(IFNULL(LOAN_BAL_STOCK_OTHER,0))
           ,SUM(IFNULL(LOAN_BAL_LOWER_INCOME,0))
           ,SUM(IFNULL(LOAN_BAL_MERGE_PLAN,0))
           ,SUM(IFNULL(LOAN_BAL_TERM_MERGE_PLAN,0))
           ,SUM(IFNULL(LOAN_BAL_MAIN_PERSON,0))
           ,SUM(IFNULL(LOAN_BAL_DEV_ESTA_HB,0))
    FROM edw.glr_rel_estate_loan_direct_dist
    WHERE DATA_DATE =SUBSTR(P_DATA_DATE,1,6)
    GROUP BY  DATA_DATE 
             ,AREA_NO               
             ,ORG_NO                   
             ,ROWS_ID                  
             ,ORG_NAME
             ;             
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
    END;
/

