WHERE data_date = v_at_V_TEMP_QUA_MONTH
GROUP BY org_no ,x.org_dscr
;
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
END;
/

DROP PROCEDURE IF EXISTS adm.p_rpt_q_farm_loan_all;

CREATE PROCEDURE adm.p_rpt_q_farm_loan_all(
    IN P_DATA_DATE VARCHAR(8)
    ,OUT P_RESULT   INT)
AS
    V_PROC_NAME VARCHAR(200) := 'adm.p_rpt_q_farm_loan_all.prc';
    V_STEP INT := 0;
    V_START_TIME VARCHAR(20) := NOW();
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
    v_at_instr TEXT;
    v_at_v_temp_qua VARCHAR(2000);
    v_at_V_TEMP_QUA_MONTH VARCHAR(2000);
BEGIN
    /*
    Author :zhangjiao
    Name :P_RPT_Q_FARM_LOAN_ALL
    FUNCTION:
    Purpose:附表3-12 X年X季度全市涉农不良贷款统计表
    VER         DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-12-19     ZHANGJIAO        1.CREATES THE PROCEDURE
*/     
    /* EXCEPTION HANDLER  异常处理*/
    
    -- 季度日期处理
    SELECT CONCAT('\'',CONCAT(QUARTER(DATE_FORMAT(P_DATA_DATE,'%Y%m%d')),'Q'),'\'') INTO v_at_v_temp_qua;
        v_at_instr := CONCAT('SELECT MAX(t.month) AS MONTH  INTO @V_TEMP_QUA_MONTH  FROM edw.dim_date t WHERE t.quarter=',v_at_v_temp_qua,'
        AND t.year = ',SUBSTR(P_DATA_DATE,1,4));
 
        EXECUTE IMMEDIATE v_at_instr;
    
    
    P_RESULT := 0;
    -- 支持数据重跑
    SET V_STEP:='1';
    DELETE  FROM adm.rpt_q_farm_loan_all WHERE DATA_DATE = v_at_V_TEMP_QUA_MONTH ;
    -- 业务逻辑处理
    SET V_STEP:='2' ;   
    INSERT INTO adm.rpt_q_farm_loan_all(
             BATCH_DATE
            ,AREA_NO
            ,DATA_DATE
            ,ORG_NO
            ,KPI_CODE
            ,KPI_NAME
            ,LOAN_BALANCE
            )
     SELECT
           NOW()
          ,AREA_NO
          ,v_at_V_TEMP_QUA_MONTH
          ,ORG_NO
          ,KPI_CODE
          ,KPI_NAME
          ,SUM(IFNULL(LOAN_BALANCE,0))
     FROM edw.glr_agl_farm_bad_loan_cny
     WHERE DATA_DATE = v_at_V_TEMP_QUA_MONTH
     group by v_at_V_TEMP_QUA_MONTH
              ,AREA_NO
              ,ORG_NO
              ,KPI_CODE
              ,KPI_NAME
              ;
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
    END;
/

DROP PROCEDURE IF EXISTS adm.p_rpt_q_farm_loan_org;

CREATE PROCEDURE adm.p_rpt_q_farm_loan_org(
    IN P_DATA_DATE VARCHAR(8)
    ,OUT P_RESULT   INT)
AS
    V_PROC_NAME VARCHAR(200) := 'adm.p_rpt_q_farm_loan_org.prc';
    V_STEP INT := 0;
    V_START_TIME VARCHAR(20) := NOW();
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
    v_at_instr TEXT;
    v_at_v_temp_qua VARCHAR(2000);
    v_at_V_TEMP_QUA_MONTH VARCHAR(2000);
BEGIN
    /*
    Author :zhangjiao
    Name :P_RPT_Q_FARM_LOAN_ORG
    FUNCTION:
    Purpose:附表3-11 X年X季度分银行机构涉农贷款统计表
    VER         DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-12-19     ZHANGJIAO        1.CREATES THE PROCEDURE
*/     
    /* EXCEPTION HANDLER  异常处理*/
    
    -- 季度日期处理
    SELECT CONCAT('\'',CONCAT(QUARTER(DATE_FORMAT(P_DATA_DATE,'%Y%m%d')),'Q'),'\'') INTO v_at_v_temp_qua;
    v_at_instr := CONCAT('SELECT MAX(t.month) AS MONTH  INTO @V_TEMP_QUA_MONTH  FROM edw.dim_date t WHERE t.quarter=',v_at_v_temp_qua,'
    AND t.year = ',SUBSTR(P_DATA_DATE,1,4));
        
    EXECUTE IMMEDIATE v_at_instr;
    
    P_RESULT := 0;
    -- 支持数据重跑
    SET V_STEP:='1';
    DELETE  FROM adm.rpt_q_farm_loan_org WHERE DATA_DATE = v_at_V_TEMP_QUA_MONTH;
    -- 业务逻辑处理
    SET V_STEP:='2' ;   
    INSERT INTO adm.rpt_q_farm_loan_org(
            BATCH_DATE
            ,AREA_NO
            ,DATA_DATE
            ,ORG_NO
            ,ORG_DESC
            ,PROJECT
            ,PROJECT_ORDER
            ,LOAN_BAL
            ,LOAN_BAL_B                                                 -- 余额占各项贷款比重
            ,LOAN_BAL_ADD_BGY                                           -- 当年新增余额
            ,LOAN_BAL_PB                                                -- 当年新增余额占各项贷款比重
            ,LOAN_BAL_TB                                                -- 同比增长
            )
     SELECT
           NOW()
          ,x.area_no
          ,v_at_V_TEMP_QUA_MONTH
          ,x.org_no
          ,org.org_dscr
          ,x.project
          ,x.rows_id
          ,SUM(IFNULL(x.loan_bal,0))
          ,CASE WHEN SUM(IFNULL(t.loan_bal,0)) =0 THEN 0 ELSE SUM(IFNULL(x.loan_bal,0))/SUM(IFNULL(t.loan_bal,0))*100 END AS   LOAN_BAL_B  
          ,SUM(IFNULL(x.loan_bal_add_bgy,0))
	  ,CASE WHEN SUM(IFNULL(t.loan_bal_sub_l,0)) =0 THEN 0 ELSE SUM(IFNULL(x.loan_bal_sub_l,0))/SUM(IFNULL(t.loan_bal_sub_l,0))*100 END  AS    LOAN_BAL_PB                        
          ,IFNULL(x.loan_bal_tb,0)
     FROM edw.glr_agl_farm_org_loan X
     LEFT JOIN dmcode.t_org_biz_lvl ORG 
           ON org.org_id = x.org_no
     LEFT JOIN (SELECT * FROM edw.glr_agl_farm_org_loan  WHERE ROWS_ID = '31' ) T
           ON  x.data_date = t.data_date
	   AND x.org_no = t.org_no
	   AND x.area_no = t.area_no
     WHERE x.data_date =v_at_V_TEMP_QUA_MONTH
         AND x.rows_id NOT IN ('5','6')
       GROUP BY v_at_V_TEMP_QUA_MONTH
                 ,x.area_no
                 ,x.org_no
                 ,x.project
                 ,x.rows_id;
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
    END;
/

DROP PROCEDURE IF EXISTS adm.p_rpt_technolo_finance_mth;

CREATE PROCEDURE adm.p_rpt_technolo_finance_mth(IN P_DATA_DATE VARCHAR(8),OUT P_RESULT   INT)
AS
    V_PROC_NAME VARCHAR(200) := 'adm.p_rpt_technolo_finance_mth.PRC';
    V_STEP INT := 0;
    V_START_TIME VARCHAR(20) := NOW();
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
 /*
    Author :yanjintao
    Name :adm.p_rpt_finance_key_kpi_mth.PRC
    FUNCTION:
    Purpose:调统-科技金融专项统计表月表(adm.rpt_technolo_finance_mth)
    VER         DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2019-02-26     yanjintao        1.CREATES THE PROCEDURE
*/     
    /* EXCEPTION HANDLER  异常处理*/
    P_RESULT := 0;
    SET V_STEP:='1';
    DELETE  FROM adm.rpt_technolo_finance_mth WHERE DATA_DATE = P_DATA_DATE;
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
    SET V_STEP:='2';
    INSERT INTO adm.rpt_technolo_finance_mth (
	 BATCH_DATE      -- 跑批日期               
	,AREA_NO         -- 上报地区               
	,DATA_DATE       -- 数据日期，账期         
	,ORG_NO          -- 上报机构/上报用户      
	,ROWS_ID         -- 行号                   
	,KPI_NAME        -- 指标名称               
	,LOAN_BAL        -- 贷款余额               
	,LOAN_BAL_P      -- 上期贷款余额           
	,LOAN_BAL_BGY    -- 结转贷款余额
	,VERITY_VAL      -- 校验项                 
	)
	SELECT 
	 NOW()
	,AREA_NO   
	,DATA_DATE 
	,ORG_NO    
	,ROWS_ID   
	,KPI_NAME  
	,case when data_date  <> CONCAT(SUBSTR(P_DATA_DATE,1,4),'0101') and data_date =P_DATA_DATE THEN LOAN_BAL  ELSE 0 END as LOAN_BAL
	,CASE WHEN data_date  <> CONCAT(SUBSTR(P_DATA_DATE,1,4),'0101')  THEN LOAN_BAL_P ELSE 0 END as LOAN_BAL_P
	,CASE WHEN data_date = concat(substr(P_DATA_DATE,1,4),'0101') then LOAN_BAL else 0 end as LOAN_BAL_BGY
	,CASE WHEN data_date  <> CONCAT(SUBSTR(P_DATA_DATE,1,4),'0101')  AND data_date =P_DATA_DATE THEN VERITY_VAL ELSE 0 END  as VERITY_VAL
	FROM edw.glr_eds_technolo_finance_mth 
	WHERE DATA_DATE = P_DATA_DATE 
	;
    CALL etl.edw_proc_trace_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,V_RETURN_CODE,V_ERROR_MSG);
        P_RESULT := 1;
END;
/

