  DELETE FROM adm.sust_sk_funds_application
  WHERE DATA_DATE IN
    (SELECT
      a.data_date
    FROM
      edw.sust_source_of_funds_detailed_a02 a
    WHERE a.batch_date = v_data_date
    );
    COMMIT;
    
   INSERT INTO adm.sust_sk_funds_application 
   SELECT
	b.data_date,
	b.batch_date,
	b.y1101,
	b.y1201,
	b.y2803,
	b.y2804,
	b.y2807,
	b.y2101, -- 股权类
	b.y2401,
	b.y2601,
	b.y2605,
	b.y2701,
	b.y3101,
	b.y2502,
	b.y2501,
	b.y3103,
	CASE WHEN b.y2603 IS NULL OR b.y2603='' THEN 7
		 WHEN DATEDIFF(b.y2603, b.y2602) >= 0         AND DATEDIFF(b.y2603, b.y2602) <= 30 THEN 0
		 WHEN DATEDIFF(b.y2603, b.y2602) >= (30+1)    AND DATEDIFF(b.y2603, b.y2602) <= (30*3) THEN 1
		 WHEN DATEDIFF(b.y2603, b.y2602) >= (30*3+1)  AND DATEDIFF(b.y2603, b.y2602) <= (30*6) THEN 2
		 WHEN DATEDIFF(b.y2603, b.y2602) >= (30*6+1)  AND DATEDIFF(b.y2603, b.y2602) <= (30*12) THEN 3
		 WHEN DATEDIFF(b.y2603, b.y2602) >= (30*12+1) AND DATEDIFF(b.y2603, b.y2602) <= (30*12*2) THEN 4
		 WHEN DATEDIFF(b.y2603, b.y2602) >= (30*12*2+1) AND DATEDIFF(b.y2603, b.y2602) <= (30*12*3) THEN 5
		 WHEN DATEDIFF(b.y2603, b.y2602) >= (30*12*3+1) THEN 6
		 END AS Y2603_Y2602,
	CASE WHEN b.y2603 IS NULL OR b.y2603='' OR DATEDIFF(b.y2603, CONCAT(b.y1101,DAY(LAST_DAY(CONCAT(b.y1101, '01'))))) < 0  THEN 7
		 WHEN DATEDIFF(b.y2603, CONCAT(b.y1101,DAY(LAST_DAY(CONCAT(b.y1101, '01'))))) >= 0         AND DATEDIFF(b.y2603, CONCAT(b.y1101,DAY(LAST_DAY(CONCAT(b.y1101, '01'))))) <= 30 THEN 0
		 WHEN DATEDIFF(b.y2603, CONCAT(b.y1101,DAY(LAST_DAY(CONCAT(b.y1101, '01'))))) >= (30+1)    AND DATEDIFF(b.y2603, CONCAT(b.y1101,DAY(LAST_DAY(CONCAT(b.y1101, '01'))))) <= (30*3) THEN 1
		 WHEN DATEDIFF(b.y2603, CONCAT(b.y1101,DAY(LAST_DAY(CONCAT(b.y1101, '01'))))) >= (30*3+1)  AND DATEDIFF(b.y2603, CONCAT(b.y1101,DAY(LAST_DAY(CONCAT(b.y1101, '01'))))) <= (30*6) THEN 2
		 WHEN DATEDIFF(b.y2603, CONCAT(b.y1101,DAY(LAST_DAY(CONCAT(b.y1101, '01'))))) >= (30*6+1)  AND DATEDIFF(b.y2603, CONCAT(b.y1101,DAY(LAST_DAY(CONCAT(b.y1101, '01'))))) <= (30*12) THEN 3
