		 WHEN DATEDIFF(b.y2603, CONCAT(b.y1101,DAY(LAST_DAY(CONCAT(b.y1101, '01'))))) >= (30*12*2+1) AND DATEDIFF(b.y2603, CONCAT(b.y1101,DAY(LAST_DAY(CONCAT(b.y1101, '01'))))) <= (30*12*3) THEN 5
		 WHEN DATEDIFF(b.y2603, CONCAT(b.y1101,DAY(LAST_DAY(CONCAT(b.y1101, '01'))))) >= (30*12*3+1) THEN 6
