	a.y2605 = j.fb_code,
	a.y2701 = k.income_code,
	a.y3101 = l.gs_code,
	a.y2502 = m.type_code,
	a.y2501 = n.data_c_code,
	a.y3103 = o.cs_code
	    ;
	COMMIT;
END;
