		 WHEN datediff(b.l2302, b.l2301) >= (30+1)    AND datediff(b.l2302, b.l2301) <= (30*3) THEN 1
		 WHEN datediff(b.l2302, b.l2301) >= (30*3+1)  AND datediff(b.l2302, b.l2301) <= (30*6) THEN 2
		 WHEN datediff(b.l2302, b.l2301) >= (30*6+1)  AND datediff(b.l2302, b.l2301) <= (30*12) THEN 3
		 WHEN datediff(b.l2302, b.l2301) >= (30*12+1) AND datediff(b.l2302, b.l2301) <= (30*12*2) THEN 4
		 WHEN datediff(b.l2302, b.l2301) >= (30*12*2+1) AND datediff(b.l2302, b.l2301) <= (30*12*3) THEN 5
		 WHEN datediff(b.l2302, b.l2301) >= (30*12*3+1) THEN 6
		 END AS L2302_L2301,
	CASE WHEN b.l2302 IS null OR b.l2302='' OR DATEDIFF(b.l2302, CONCAT(b.l1101,DAY(LAST_DAY(CONCAT(b.l1101, '01'))))) < 0  THEN 7
		 WHEN DATEDIFF(b.l2302, CONCAT(b.l1101,DAY(LAST_DAY(CONCAT(b.l1101, '01'))))) >= 0         AND DATEDIFF(b.l2302, CONCAT(b.l1101,DAY(LAST_DAY(CONCAT(b.l1101, '01'))))) <= 30 THEN 0
		 WHEN DATEDIFF(b.l2302, CONCAT(b.l1101,DAY(LAST_DAY(CONCAT(b.l1101, '01'))))) >= (30+1)    AND DATEDIFF(b.l2302, CONCAT(b.l1101,DAY(LAST_DAY(CONCAT(b.l1101, '01'))))) <= (30*3) THEN 1
		 WHEN DATEDIFF(b.l2302, CONCAT(b.l1101,DAY(LAST_DAY(CONCAT(b.l1101, '01'))))) >= (30*3+1)  AND DATEDIFF(b.l2302, CONCAT(b.l1101,DAY(LAST_DAY(CONCAT(b.l1101, '01'))))) <= (30*6) THEN 2
		 WHEN DATEDIFF(b.l2302, CONCAT(b.l1101,DAY(LAST_DAY(CONCAT(b.l1101, '01'))))) >= (30*6+1)  AND DATEDIFF(b.l2302, CONCAT(b.l1101,DAY(LAST_DAY(CONCAT(b.l1101, '01'))))) <= (30*12) THEN 3
		 WHEN DATEDIFF(b.l2302, CONCAT(b.l1101,DAY(LAST_DAY(CONCAT(b.l1101, '01'))))) >= (30*12+1) AND DATEDIFF(b.l2302, CONCAT(b.l1101,DAY(LAST_DAY(CONCAT(b.l1101, '01'))))) <= (30*12*2) THEN 4
		 WHEN DATEDIFF(b.l2302, CONCAT(b.l1101,DAY(LAST_DAY(CONCAT(b.l1101, '01'))))) >= (30*12*2+1) AND DATEDIFF(b.l2302, CONCAT(b.l1101,DAY(LAST_DAY(CONCAT(b.l1101, '01'))))) <= (30*12*3) THEN 5
		 WHEN DATEDIFF(b.l2302, CONCAT(b.l1101,DAY(LAST_DAY(CONCAT(b.l1101, '01'))))) >= (30*12*3+1) THEN 6
		 END AS L2302_L1101,
	b.l2402,
	b.l2403,
	b.l2203,
	b.l3101,
	b.l3103
	from edw.sust_source_of_funds_detailed_a01 b
   where b.data_date IN
    (SELECT
      t.data_date
    FROM
      edw.sust_source_of_funds_detailed_a01 t
    WHERE t.batch_date = v_data_date
    );
    commit;
	UPDATE adm.sust_sk_funds_source a
	LEFT JOIN
	adm.v_sust_investment_style b
	ON a.l21_3 = b.name_3
	LEFT JOIN
	adm.v_sust_biz_category c
	ON a.l1201 = c.biz_dscr
	LEFT JOIN
	adm.v_sust_industry d
	ON a.l2503 = d.lev_1_dscr
	LEFT JOIN
	adm.v_sust_enterprise_size e
	ON a.l2504 = e.e_size_dscr
	LEFT JOIN
	adm.v_sust_ownership f
	ON a.l2507 = f.os_dscr
	LEFT JOIN
	adm.v_sust_investment_style g
	ON a.l21_3 = g.name_3
	LEFT JOIN
	adm.v_sust_forward_buyback h
	ON a.l2304 = h.fb_dscr
	LEFT JOIN
	adm.v_sust_fixed_income i
	ON a.l2401 = i.income_dscr
	LEFT JOIN
	adm.v_sust_currency_type j
	ON a.l2202 = j.type_dscr
	LEFT JOIN
	adm.v_sust_data_category k
	ON a.l2201 = k.data_c_dscr
	LEFT JOIN
	adm.v_sust_payment_status l
	ON a.l3102 = l.status_dscr
	SET a.l21_3 = b.code_3,
	    a.l1201 = c.biz_code,
	    a.l2503 = d.lev_1_id,
	    a.l2504 = e.e_size_code,
	    a.l2507 = f.os_code,
	    a.l21_3 = g.code_3,
	    a.l2304 = h.fb_code,
	    a.l2401 = i.income_code,
	    a.l2202 = j.type_code,
	    a.l2201 = k.data_c_code,
	    a.l3102 = l.status_code
	    ;
	commit;
    
END;
/

DROP PROCEDURE IF EXISTS adm.p_trs_budget_payout_cq;

CREATE PROCEDURE adm.p_trs_budget_payout_cq(IN s_date DATE,IN edate DATE)
AS
  V_START_TIME    CHAR(19) := NOW();
  V_PROC_NAME     VARCHAR(80) := 'adm.p_trs_budget_payout_cq.PRC';
  V_STEP_ID       INT := 0;
BEGIN
  -- DECLARE  s_date DATE ;  -- 数据日期
  -- SET s_date =  '2018-01-01';
  
  
  
  WHILE s_date <= edate
  LOOP
	  V_STEP_ID := 1;
INSERT INTO adm.trs_budget_function_payout_daily
(
D_REPORTDATE,
S_TRECODE,
C_BUDGETLEVEL,
SUBJECT_CODE_4,
SUBJECT_DSCR_4,
FUN_CLASS_CODE_1,
FUN_CLASS_DSCR_1,
FUN_CLASS_CODE_2,
FUN_CLASS_DSCR_2,
FUN_CLASS_CODE_3,
FUN_CLASS_DSCR_3,
THIS_PERIOD_AMT,
LAST_PERIOD_AMT,
THIS_PERIOD_YEARAMT,
LAST_PERIOD_YEARAMT,
UPDATE_DATE
)
SELECT
  DATE_FORMAT(aa.d_reportdate,'%Y-%m-%d') AS D_REPORTDATE,
  aa.s_trecode AS S_TRECODE,
  dt2.level AS C_BUDGETLEVEL,
  dt1.subject_code_4 AS SUBJECT_CODE_4,
  dt1.subject_dscr_4 AS SUBJECT_DSCR_4,
  dt1.fun_class_code_1 AS FUN_CLASS_CODE_1,
  dt1.fun_class_dscr_1 AS FUN_CLASS_DSCR_1,
  dt1.fun_class_code_2 AS FUN_CLASS_CODE_2,
  dt1.fun_class_dscr_2 AS FUN_CLASS_DSCR_2,
  dt1.fun_class_code_3 AS FUN_CLASS_CODE_3,
  dt1.fun_class_dscr_3 AS FUN_CLASS_DSCR_3,
  aa.f_dayamt AS THIS_PERIOD_AMT,
  bb.f_dayamt AS LAST_PERIOD_AMT,
  aa.f_yearamt AS THIS_PERIOD_YEARAMT,
  bb.f_yearamt AS LAST_PERIOD_YEARAMT,
  CURRENT_TIMESTAMP AS UPDATE_DATE
FROM
(
-- -- 正常期预算支出
 SELECT 
  t1.d_reportdate AS D_REPORTDATE,
  t1.s_trecode AS S_TRECODE,
  t1.s_budgetsubjectcode AS S_BUDGETSUBJECTCODE,
  t1.s_budgetsubjectname AS S_BUDGETSUBJECTNAME,
  SUM(t1.f_dayamt) AS F_DAYAMT,
  SUM(t1.f_yearamt) AS F_YEARAMT
FROM edw.trs_d003_tr_budget_payout t1
WHERE  t1.d_reportdate = s_date
GROUP BY
t1.d_reportdate,
t1.s_trecode,
t1.s_budgetsubjectcode,
t1.s_budgetsubjectname
) aa
LEFT JOIN
(
-- -- 正常期预算支出
 SELECT 
  t1.d_reportdate AS D_REPORTDATE,
  t1.s_trecode AS S_TRECODE,
  t1.s_budgetsubjectcode AS S_BUDGETSUBJECTCODE,
  t1.s_budgetsubjectname AS S_BUDGETSUBJECTNAME,
  SUM(t1.f_dayamt) AS F_DAYAMT,
  SUM(t1.f_yearamt) AS F_YEARAMT
FROM edw.trs_d003_tr_budget_payout t1
WHERE  t1.d_reportdate = DATE_SUB(s_date,INTERVAL 1 YEAR)
GROUP BY
t1.d_reportdate,
t1.s_trecode,
t1.s_budgetsubjectcode,
t1.s_budgetsubjectname
) bb
 ON aa.d_reportdate = DATE_ADD(bb.d_reportdate,INTERVAL 1 YEAR)
AND aa.s_trecode = bb.s_trecode
AND aa.s_budgetsubjectcode = bb.s_budgetsubjectcode
JOIN
edw.cm_guoku_dimnsn dt2
ON aa.s_trecode = dt2.guoku_id
JOIN
(
SELECT
a.fun_class_code_1 AS FUN_CLASS_CODE_1,
a.fun_class_dscr_1 AS FUN_CLASS_DSCR_1,
a.fun_class_code_2 AS FUN_CLASS_CODE_2,
a.fun_class_dscr_2 AS FUN_CLASS_DSCR_2,
a.fun_class_code_3 AS FUN_CLASS_CODE_3,
a.fun_class_dscr_3 AS FUN_CLASS_DSCR_3,
b.subject_code_4 AS SUBJECT_CODE_4,
b.subject_dscr_4 AS SUBJECT_DSCR_4
FROM
edw.cm_guoku_functional_type a
LEFT JOIN
edw.cm_guoku_rcpt_dsb b
ON  a.fun_class_code_3 = b.t_class_code_3
WHERE
1=1
AND a.fun_class_code_1 = 'T02'
) dt1
ON aa.s_budgetsubjectcode = dt1.subject_code_4
  ;
  CALL etl.edw_proc_trace_log(DATE_FORMAT(s_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  s_date := DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END LOOP;
END;
/

DROP PROCEDURE IF EXISTS adm.p_trs_comprehensive_income_month;

CREATE PROCEDURE adm.p_trs_comprehensive_income_month(IN V_DATA_DATE VARCHAR(10))
AS
v_proc_name VARCHAR(50) := 'adm.p_trs_comprehensive_income_month';
V_STEP_ID   INT := '0';
P_DATA_DATE VARCHAR(50) := DATE_FORMAT(V_DATA_DATE,'%Y-%m');
V_START_TIME VARCHAR(50) := NOW();
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
/*综合查询收入月表*/
V_STEP_ID := 1;
DELETE FROM adm.trs_comprehensive_income_month WHERE D_ACCT = DATE_FORMAT(V_DATA_DATE,'%Y-%m');
V_STEP_ID := 2;
INSERT INTO adm.trs_comprehensive_income_month
SELECT
  aa.d_acct,
  aa.trecode,
  aa.tredscr,
  aa.subject_code,
  aa.subject_dscr,
  aa.this_amt,
  aa.this_amt_year,
  CASE WHEN bb.this_amt IS NULL OR bb.this_amt=0 OR aa.this_amt IS NULL
  THEN NULL
  ELSE ROUND(aa.this_amt/bb.this_amt,4) 
  END AS THIS_AMT_PPT,
  aa.year_amt,
  aa.year_amt_year,
  CASE WHEN bb.year_amt IS NULL OR bb.year_amt=0 OR aa.year_amt IS NULL
  THEN NULL
  ELSE ROUND(aa.year_amt/bb.year_amt,4) 
  END AS YEAR_AMT_PPT
  FROM
  (
	SELECT
	 DATE_FORMAT(a.d_acct,'%Y-%m') 		AS D_ACCT,
	 a.trecode AS TRECODE,
	 a.tredscr AS TREDSCR,
	 a.subject_code AS SUBJECT_CODE,
	 a.subject_dscr AS SUBJECT_DSCR,
	 SUM(a.this_amt) AS THIS_AMT,
	 CASE WHEN SUM(b.this_amt) IS NULL OR SUM(b.this_amt)=0
	 THEN NULL
	 ELSE ROUND(((IFNULL(SUM(a.this_amt),0)-SUM(b.this_amt))/SUM(b.this_amt)),4) 
	 END AS THIS_AMT_YEAR,
	 SUM(a.year_amt) AS YEAR_AMT,
	 CASE WHEN SUM(b.year_amt) IS NULL OR SUM(b.year_amt)=0
	 THEN NULL
	 ELSE ROUND(((IFNULL(SUM(a.year_amt),0)-SUM(b.year_amt))/SUM(b.year_amt)),4) 
	 END AS YEAR_AMT_YEAR
	FROM stg.trs_tmis_budget_income AS A
	LEFT JOIN stg.trs_tmis_budget_income AS B
	ON b.d_acct = DATE_FORMAT(DATE_SUB(V_DATA_DATE,INTERVAL 1 YEAR),'%Y-%m-01')
	AND a.trecode=b.trecode
	AND a.subject_code=b.subject_code
	AND a.level=b.level
	WHERE a.d_acct=DATE_FORMAT(V_DATA_DATE,'%Y-%m-01')
	GROUP BY
	a.trecode,
	a.subject_code
  )AA
  LEFT JOIN
  (
	SELECT
	 DATE_FORMAT(D_ACCT,'%Y-%m') 		AS D_ACCT,
         TRECODE,
         SUM(THIS_AMT) 				AS THIS_AMT,
         SUM(YEAR_AMT) 				AS YEAR_AMT
       FROM stg.trs_tmis_budget_income
       WHERE D_ACCT = DATE_FORMAT(V_DATA_DATE,'%Y-%m-01')
       AND  SUBJECT_CODE IN ('T010101','T010201','T010601')
       GROUP BY
         D_ACCT,
         TRECODE
  )BB
  ON aa.d_acct=bb.d_acct
  AND aa.trecode=bb.trecode;
  
  
  
  
  
  
  
  
  
  
  
EXCEPTION
    WHEN OTHERS THEN
       GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
       CALL etl.edw_proc_error_log(P_DATA_DATE,V_START_TIME,NOW(),v_proc_name,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
	END;
/

DROP PROCEDURE IF EXISTS adm.p_trs_comprehensive_income_month_incomemm;

CREATE PROCEDURE adm.p_trs_comprehensive_income_month_incomemm(IN V_DATA_DATE VARCHAR(10))
AS
v_proc_name VARCHAR(50) := 'adm.p_trs_comprehensive_income_month_incomemm';
V_STEP_ID   INT := '0';
P_DATA_DATE VARCHAR(50) := DATE_FORMAT(V_DATA_DATE,'%Y-%m');
V_START_TIME VARCHAR(50) := NOW();
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
/*综合查询收入月表*/
V_STEP_ID := 1;
DELETE FROM adm.trs_comprehensive_income_month_incomemm WHERE D_ACCT = DATE_FORMAT(V_DATA_DATE,'%Y-%m');
V_STEP_ID := 2;
INSERT INTO adm.trs_comprehensive_income_month_incomemm
SELECT
  aa.d_acct,
  aa.trecode,
  aa.tredscr,
  aa.subject_code,
  aa.subject_dscr,
  aa.this_amt,
  aa.this_amt_year,
  CASE WHEN bb.this_amt IS NULL OR bb.this_amt=0 OR aa.this_amt IS NULL
  THEN NULL
  ELSE ROUND(aa.this_amt/bb.this_amt,4) 
  END AS THIS_AMT_PPT,
  aa.year_amt,
  aa.year_amt_year,
  CASE WHEN bb.year_amt IS NULL OR bb.year_amt=0 OR aa.year_amt IS NULL
  THEN NULL
  ELSE ROUND(aa.year_amt/bb.year_amt,4) 
  END AS YEAR_AMT_PPT
  FROM
  (
SELECT
 DATE_FORMAT(a.d_acct,'%Y-%m')        AS D_ACCT,
 d.pid                 AS TRECODE,
 d.guoku_dscr           AS TREDSCR,
 a.subject_code         AS SUBJECT_CODE,
 a.subject_dscr         AS SUBJECT_DSCR,
 SUM(a.this_amt)         AS THIS_AMT,
 CASE WHEN b.this_amt IS NULL OR b.this_amt=0
      THEN NULL
      ELSE ROUND(((IFNULL(SUM(a.this_amt),0)-SUM(b.this_amt))/SUM(b.this_amt)),4) 
       END AS THIS_AMT_YEAR,
 a.year_amt AS YEAR_AMT,
 CASE WHEN b.year_amt IS NULL OR b.year_amt=0
      THEN NULL
      ELSE ROUND(((IFNULL(a.year_amt,0)-b.year_amt)/b.year_amt),4) 
       END AS YEAR_AMT_YEAR
FROM stg.trs_tmis_budget_income AS A
LEFT JOIN stg.trs_tmis_budget_income AS B
       ON DATE_FORMAT(b.d_acct,'%Y-%m') = DATE_FORMAT(DATE_SUB(V_DATA_DATE,INTERVAL 1 YEAR),'%Y-%m')
      AND a.trecode=b.trecode
      AND a.subject_code=b.subject_code
      AND a.level=b.level
 JOIN (
	SELECT
	DISTINCT 
	p.guoku_id AS PID,
	p.level,
	p.guoku_dscr,
	c.guoku_id AS CID
	FROM
	edw.cm_guoku_dimnsn p
	LEFT JOIN
	edw.cm_guoku_dimnsn c
	ON(
	p.guoku_lvl_id_2 = c.guoku_lvl_id_1
	OR  p.guoku_lvl_id_3 = c.guoku_lvl_id_2
	OR  p.guoku_id = c.guoku_lvl_id_3
		) 
	) d 
	ON a.trecode = d.cid
WHERE DATE_FORMAT(a.d_acct,'%Y-%m')=DATE_FORMAT(V_DATA_DATE,'%Y-%m')
GROUP BY
  d.pid,
  a.subject_code
  )AA
  LEFT JOIN
  (
	SELECT
	 DATE_FORMAT(D_ACCT,'%Y-%m') 		AS D_ACCT,
         dinm.pid AS TRECODE,
         SUM(THIS_AMT) 				AS THIS_AMT,
         SUM(YEAR_AMT) 				AS YEAR_AMT
       FROM stg.trs_tmis_budget_income AA
       LEFT JOIN (
	SELECT
	DISTINCT p.guoku_id AS PID,
	p.level,
    p.guoku_dscr,
    c.guoku_id AS CID
    FROM
     edw.cm_guoku_dimnsn p
    JOIN
     edw.cm_guoku_dimnsn c
    ON(
        p.guoku_lvl_id_2 = c.guoku_lvl_id_1
    OR  p.guoku_lvl_id_3 = c.guoku_lvl_id_2
    OR  p.guoku_id = c.guoku_lvl_id_3
      ) 
       )dinm 
         ON aa.trecode=dinm.cid  
       WHERE DATE_FORMAT(D_ACCT,'%Y-%m') = DATE_FORMAT(V_DATA_DATE,'%Y-%m')
       AND  SUBJECT_CODE IN ('T010101','T010201','T010601')
       GROUP BY
         DATE_FORMAT(D_ACCT,'%Y-%m'),
         dinm.pid
  )BB
  ON aa.d_acct=bb.d_acct
  AND aa.trecode=bb.trecode;
  
EXCEPTION
    WHEN OTHERS THEN
       GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
       CALL etl.edw_proc_error_log(P_DATA_DATE,V_START_TIME,NOW(),v_proc_name,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
	END;
/

DROP PROCEDURE IF EXISTS adm.p_trs_comprehensive_income_quarter;

CREATE PROCEDURE adm.p_trs_comprehensive_income_quarter(IN V_DATA_DATE VARCHAR(10))
AS
v_proc_name VARCHAR(50) := 'adm.p_trs_comprehensive_income_quarter';
V_STEP_ID   INT := '0';
P_DATA_DATE VARCHAR(50) := DATE_FORMAT(V_DATA_DATE,'%Y-%m');
V_START_TIME VARCHAR(50) := NOW();
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
/*综合查询收入月表*/
V_STEP_ID := 1;
DELETE FROM adm.trs_comprehensive_income_quarter WHERE D_ACCT = CONCAT(YEAR(V_DATA_DATE),'Q',QUARTER(V_DATA_DATE));
V_STEP_ID := 2;
INSERT INTO adm.trs_comprehensive_income_quarter
SELECT 
 D_ACCT,
 S_TRECODE,
 S_TREDSCR,
 SUBJECT_CODE,
 SUBJECT_DSCR,
 SUM(THIS_AMT),
 SUM(THIS_AMT_YEAR),
 SUM(THIS_AMT_PPT),
 SUM(YEAR_AMT),
 SUM(YEAR_AMT_YEAR),
 SUM(YEAR_AMT_PPT)
FROM 
(
-- 本期
SELECT
	aa.d_acct, 		
	aa.s_trecode, 	
	aa.s_tredscr,	
	aa.subject_code,    
	aa.subject_dscr,   	
	aa.this_amt,        
	aa.this_amt_year, 	
	CASE WHEN bb.this_amt = 0
	     THEN 0
	     ELSE aa.this_amt/bb.this_amt END   AS  THIS_AMT_PPT,    
	aa.year_amt,	
	aa.year_amt_year,	
	0					AS YEAR_AMT_PPT
FROM
(
SELECT
	CONCAT(YEAR(a.d_acct),'Q',QUARTER(a.d_acct))		AS D_ACCT, 		
	a.trecode						AS S_TRECODE, 	
	a.tredscr						AS S_TREDSCR,	
	a.subject_code						AS SUBJECT_CODE,    
	a.subject_dscr						AS SUBJECT_DSCR,   	
	SUM(a.this_amt)						AS THIS_AMT,        
	CASE WHEN SUM(b.this_amt) = 0
	     THEN 0
	     ELSE (SUM(a.this_amt)-SUM(b.this_amt))/SUM(b.this_amt) END 	AS THIS_AMT_YEAR, 	 
	0						AS YEAR_AMT,	
	0 						AS YEAR_AMT_YEAR
FROM stg.trs_tmis_budget_income A
LEFT JOIN stg.trs_tmis_budget_income B    -- 去年
       ON b.d_acct = DATE_SUB(a.d_acct,INTERVAL 1 YEAR)
       AND a.trecode = b.trecode
       AND a.subject_code = b.subject_code
       AND a.level = b.level
WHERE CONCAT(YEAR(a.d_acct),'Q',QUARTER(a.d_acct)) = CONCAT(YEAR(V_DATA_DATE),'Q',QUARTER(V_DATA_DATE))
GROUP BY
       CONCAT(YEAR(a.d_acct),'Q',QUARTER(a.d_acct)),
       a.trecode,
       a.subject_code
) AA
LEFT JOIN (
       SELECT 
         CONCAT(YEAR(D_ACCT),'Q',QUARTER(D_ACCT)) 		AS D_ACCT,
         TRECODE,
         SUM(THIS_AMT) 						AS THIS_AMT,
         0 						        AS YEAR_AMT
       FROM stg.trs_tmis_budget_income 
       WHERE CONCAT(YEAR(D_ACCT),'Q',QUARTER(D_ACCT)) = CONCAT(YEAR(V_DATA_DATE),'Q',QUARTER(V_DATA_DATE))
         AND SUBJECT_CODE IN ('T010101','T010201','T010601')
       GROUP BY
         CONCAT(YEAR(D_ACCT),'Q',QUARTER(D_ACCT)),
         TRECODE
)  BB -- 国库收入
	ON aa.d_acct = bb.d_acct
	AND aa.s_trecode = bb.trecode
UNION ALL 
-- 累计值
SELECT
	aa.d_acct, 		
	aa.s_trecode, 	
	aa.s_tredscr,	
	aa.subject_code,    
	aa.subject_dscr,   	
	aa.this_amt,        
	aa.this_amt_year, 	
	0   AS  THIS_AMT_PPT,    
	aa.year_amt,	
	aa.year_amt_year,	
	CASE WHEN bb.year_amt = 0
	     THEN 0
	     ELSE aa.year_amt/bb.year_amt END	AS YEAR_AMT_PPT
FROM
(
SELECT
	CONCAT(YEAR(a.d_acct),'Q',QUARTER(a.d_acct))		AS D_ACCT, 		
	a.trecode						AS S_TRECODE, 	
	a.tredscr						AS S_TREDSCR,	
	a.subject_code						AS SUBJECT_CODE,    
	a.subject_dscr						AS SUBJECT_DSCR,   	
	0							AS THIS_AMT,        
	0						 	AS THIS_AMT_YEAR, 	 
	SUM(a.year_amt)						AS YEAR_AMT,	
	CASE WHEN SUM(b.year_amt) = 0
	     THEN 0
	     ELSE (SUM(a.year_amt)-SUM(b.year_amt))/SUM(b.year_amt) END 	AS YEAR_AMT_YEAR
FROM stg.trs_tmis_budget_income A
LEFT JOIN stg.trs_tmis_budget_income B    -- 去年
       ON b.d_acct = DATE_SUB(a.d_acct,INTERVAL 1 YEAR)
       AND a.trecode = b.trecode
       AND a.subject_code = b.subject_code
       AND a.level = b.level
WHERE a.d_acct =   CASE WHEN MONTH(V_DATA_DATE) IN ('1','2','3') THEN CONCAT(YEAR(V_DATA_DATE),'-03-01')
		       WHEN MONTH(V_DATA_DATE) IN ('4','5','6') THEN CONCAT(YEAR(V_DATA_DATE),'-06-01')
		       WHEN MONTH(V_DATA_DATE) IN ('7','8','9') THEN CONCAT(YEAR(V_DATA_DATE),'-09-01')
		       ELSE CONCAT(YEAR(V_DATA_DATE),'-12-01')  END
GROUP BY
       a.d_acct,
       a.trecode,
       a.subject_code
) AA
LEFT JOIN (
       SELECT 
         CONCAT(YEAR(D_ACCT),'Q',QUARTER(D_ACCT)) 		AS D_ACCT,
         TRECODE,
         0 						AS THIS_AMT,
         SUM(YEAR_AMT) 						AS YEAR_AMT
       FROM stg.trs_tmis_budget_income 
       WHERE D_ACCT =   CASE WHEN MONTH(V_DATA_DATE) IN ('1','2','3') THEN CONCAT(YEAR(V_DATA_DATE),'-03-01')
		       WHEN MONTH(V_DATA_DATE) IN ('4','5','6') THEN CONCAT(YEAR(V_DATA_DATE),'-06-01')
		       WHEN MONTH(V_DATA_DATE) IN ('7','8','9') THEN CONCAT(YEAR(V_DATA_DATE),'-09-01')
		       ELSE CONCAT(YEAR(V_DATA_DATE),'-12-01')  END
         AND SUBJECT_CODE IN ('T010101','T010201','T010601')
       GROUP BY
         D_ACCT,
         TRECODE
)  BB -- 国库收入
	ON aa.d_acct = bb.d_acct
	AND aa.s_trecode = bb.trecode
) AA 	
GROUP BY 
	aa.d_acct,
	aa.s_trecode,
	aa.subject_code	;
	
EXCEPTION
    WHEN OTHERS THEN
       GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
       CALL etl.edw_proc_error_log(P_DATA_DATE,V_START_TIME,NOW(),v_proc_name,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
	END;
/

DROP PROCEDURE IF EXISTS adm.p_trs_comprehensive_income_quarter_incomeqq;

CREATE PROCEDURE adm.p_trs_comprehensive_income_quarter_incomeqq(IN V_DATA_DATE VARCHAR(10))
AS
v_proc_name VARCHAR(50) := 'adm.p_trs_comprehensive_income_quarter_incomeqq';
V_STEP_ID   INT := '0';
P_DATA_DATE VARCHAR(50) := DATE_FORMAT(V_DATA_DATE,'%Y-%m');
V_START_TIME VARCHAR(50) := NOW();
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
/*综合查询收入季表*/
V_STEP_ID := 1;
DELETE FROM adm.trs_comprehensive_income_quarter_incomeqq WHERE D_ACCT = CONCAT(YEAR(V_DATA_DATE),'Q',QUARTER(V_DATA_DATE));
V_STEP_ID := 2;
INSERT INTO adm.trs_comprehensive_income_quarter_incomeqq
SELECT
	aa.d_acct, 		
	aa.s_trecode, 	
	aa.s_tredscr,	
	aa.subject_code,    
	aa.subject_dscr,   	
	aa.this_amt,        
	aa.this_amt_year, 	
	CASE WHEN bb.this_amt = 0
	     THEN 0
	     ELSE aa.this_amt/bb.this_amt END   AS  THIS_AMT_PPT,    
	aa.year_amt,	
	aa.year_amt_year,	
	CASE WHEN bb.year_amt = 0
	     THEN 0
	     ELSE aa.year_amt/bb.year_amt END	AS YEAR_AMT_PPT
FROM
(
SELECT
	CONCAT(YEAR(a.d_acct),'Q',QUARTER(a.d_acct))		AS D_ACCT, 		
	d.pid							AS S_TRECODE, 	
	d.guoku_dscr						AS S_TREDSCR,	
	a.subject_code						AS SUBJECT_CODE,    
	a.subject_dscr						AS SUBJECT_DSCR,   	
	SUM(a.this_amt)						AS THIS_AMT,        
	CASE WHEN SUM(b.this_amt) = 0
	     THEN 0
	     ELSE (SUM(a.this_amt)-SUM(b.this_amt))/SUM(b.this_amt) END 	AS THIS_AMT_YEAR, 	 
	SUM(a.year_amt)						AS YEAR_AMT,	
	CASE WHEN SUM(b.year_amt) = 0
	     THEN 0
	     ELSE (SUM(a.year_amt)-SUM(b.year_amt))/SUM(b.year_amt) END 	AS YEAR_AMT_YEAR
FROM stg.trs_tmis_budget_income A
LEFT JOIN stg.trs_tmis_budget_income B    -- 去年
       ON b.d_acct = DATE_SUB(a.d_acct,INTERVAL 1 YEAR)
       AND a.trecode = b.trecode
       AND a.subject_code = b.subject_code
       AND a.level = b.level
       JOIN (
       SELECT
	DISTINCT p.guoku_id AS PID,
	p.level,
    p.guoku_dscr,
    c.guoku_id AS CID
    FROM
     edw.cm_guoku_dimnsn p
    JOIN
     edw.cm_guoku_dimnsn c
    ON(
        p.guoku_lvl_id_2 = c.guoku_lvl_id_1
    OR  p.guoku_lvl_id_3 = c.guoku_lvl_id_2
    OR  p.guoku_id = c.guoku_lvl_id_3
      ) 
       ) d 
       ON a.trecode = d.cid
WHERE CONCAT(YEAR(a.d_acct),'Q',QUARTER(a.d_acct)) = CONCAT(YEAR('2020-10-01'),'Q',QUARTER('2020-10-01'))
GROUP BY
       CONCAT(YEAR(a.d_acct),'Q',QUARTER(a.d_acct)),
       d.pid,
       a.subject_code
) AA
LEFT JOIN (
       SELECT 
         CONCAT(YEAR(income.d_acct),'Q',QUARTER(income.d_acct)) 		AS D_ACCT,
         d.pid 							AS TRECODE,
         SUM(THIS_AMT) 						AS THIS_AMT,
         SUM(YEAR_AMT) 						AS YEAR_AMT
       FROM stg.trs_tmis_budget_income income
       LEFT JOIN (
	SELECT
	DISTINCT p.guoku_id AS PID,
	p.level,
	p.guoku_dscr,
	c.guoku_id AS CID
    FROM
     edw.cm_guoku_dimnsn p
    JOIN
     edw.cm_guoku_dimnsn c
    ON(
        p.guoku_lvl_id_2 = c.guoku_lvl_id_1
    OR  p.guoku_lvl_id_3 = c.guoku_lvl_id_2
    OR  p.guoku_id = c.guoku_lvl_id_3
       
       )
       ) d
       ON income.trecode = d.cid
       WHERE CONCAT(YEAR(income.d_acct),'Q',QUARTER(income.d_acct)) = CONCAT(YEAR('2020-10-01'),'Q',QUARTER('2020-10-01'))
         AND SUBJECT_CODE IN ('T010101','T010201','T010601')
       GROUP BY
         CONCAT(YEAR(income.d_acct),'Q',QUARTER(income.d_acct)),
         d.pid
)  BB -- 国库收入
	ON aa.d_acct = bb.d_acct
	AND aa.s_trecode = bb.trecode;
EXCEPTION
    WHEN OTHERS THEN
       GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
       CALL etl.edw_proc_error_log(P_DATA_DATE,V_START_TIME,NOW(),v_proc_name,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
	END;
/

DROP PROCEDURE IF EXISTS adm.p_trs_comprehensive_payout_month;

CREATE PROCEDURE adm.p_trs_comprehensive_payout_month(IN V_DATA_DATE VARCHAR(10))
AS
v_proc_name VARCHAR(50) := 'adm.p_trs_comprehensive_payout_month';
V_STEP_ID   INT := '0';
P_DATA_DATE VARCHAR(50) := DATE_FORMAT(V_DATA_DATE,'%Y-%m');
V_START_TIME VARCHAR(50) := NOW();
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
/*综合查询支出月表*/
V_STEP_ID := 1;
DELETE FROM adm.trs_comprehensive_payout_month WHERE D_ACCT = DATE_FORMAT(V_DATA_DATE,'%Y-%m');
V_STEP_ID := 2;
INSERT INTO adm.trs_comprehensive_payout_month
SELECT
	a1.d_acct,
	a1.trecode,
	a1.tredscr,
	a1.subject_code,
	a1.subject_dscr,
	a1.this_amt,
	a1.this_amt_year,
	CASE WHEN a2.this_amt IS NULL OR a2.this_amt=0 OR a1.this_amt IS NULL
	THEN NULL
	ELSE ROUND(a1.this_amt/a2.this_amt,4) 
	END AS THIS_AMT_PPT,
	a1.year_amt,
	a1.year_amt_year,
	CASE WHEN a2.year_amt IS NULL OR a2.year_amt=0 OR a1.year_amt IS NULL
	THEN NULL
	ELSE ROUND(a1.year_amt/a2.year_amt,4) 
	END AS YEAR_AMT_PPT
FROM
  (
  SELECT
	 DATE_FORMAT(a.d_acct,'%Y-%m') 		AS D_ACCT,
	 a.trecode AS TRECODE,
	 a.tredscr AS TREDSCR,
	 a.subject_code AS SUBJECT_CODE,
	 a.subject_dscr AS SUBJECT_DSCR,
	 SUM(a.this_amt) AS THIS_AMT,
	 CASE WHEN SUM(b.this_amt) IS NULL OR SUM(b.this_amt)=0
	 THEN NULL
	 ELSE ROUND(((IFNULL(SUM(a.this_amt),0)-SUM(b.this_amt))/SUM(b.this_amt)),4) 
	 END AS THIS_AMT_YEAR,
	 SUM(a.year_amt) AS YEAR_AMT,
	 CASE WHEN SUM(b.year_amt) IS NULL OR SUM(b.year_amt)=0
	 THEN NULL
	 ELSE ROUND(((IFNULL(SUM(a.year_amt),0)-SUM(b.year_amt))/SUM(b.year_amt)),4) 
	 END AS YEAR_AMT_YEAR
  FROM stg.trs_tmis_budget_payout AS A
  LEFT JOIN stg.trs_tmis_budget_payout AS B
	 ON b.d_acct = DATE_FORMAT(DATE_SUB(V_DATA_DATE,INTERVAL 1 YEAR),'%Y-%m-01')
	AND a.trecode=b.trecode
	AND a.subject_code=b.subject_code
	AND a.level=b.level
  WHERE a.d_acct=DATE_FORMAT(V_DATA_DATE,'%Y-%m-01')
  GROUP BY
	a.trecode,
	a.subject_code
  )a1
  LEFT JOIN
  (
	SELECT
	 DATE_FORMAT(D_ACCT,'%Y-%m') 		AS D_ACCT,
         TRECODE,
         SUM(THIS_AMT) 				AS THIS_AMT,
         SUM(YEAR_AMT) 				AS YEAR_AMT
       FROM stg.trs_tmis_budget_payout
       WHERE D_ACCT = DATE_FORMAT(V_DATA_DATE,'%Y-%m-01')
       AND  SUBJECT_CODE IN ('T020101','T020201','T020601')
       GROUP BY
         D_ACCT,
         TRECODE
  )a2
  ON a1.d_acct=a2.d_acct
  AND a1.trecode=a2.trecode;
  
  
EXCEPTION
    WHEN OTHERS THEN
       GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
       CALL etl.edw_proc_error_log(P_DATA_DATE,V_START_TIME,NOW(),v_proc_name,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
	END;
/

DROP PROCEDURE IF EXISTS adm.p_trs_comprehensive_payout_month_payoutmm;

CREATE PROCEDURE adm.p_trs_comprehensive_payout_month_payoutmm(IN V_DATA_DATE VARCHAR(10))
AS
v_proc_name VARCHAR(50) := 'adm.p_trs_comprehensive_payout_month_payoutmm';
V_STEP_ID   INT := '0';
P_DATA_DATE VARCHAR(50) := DATE_FORMAT(V_DATA_DATE,'%Y-%m');
V_START_TIME VARCHAR(50) := NOW();
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
/*综合查询收入季表*/
V_STEP_ID := 1;
DELETE FROM adm.trs_comprehensive_payout_month_payoutmm WHERE D_ACCT = CONCAT(YEAR(V_DATA_DATE),'Q',QUARTER(V_DATA_DATE));
V_STEP_ID := 2;
INSERT INTO adm.trs_comprehensive_payout_month_payoutmm
SELECT       
	a1.d_acct,
	a1.trecode,
	a1.tredscr,
	a1.subject_code,
	a1.subject_dscr,
	a1.this_amt,
	a1.this_amt_year,
	CASE WHEN a2.this_amt IS NULL OR a2.this_amt=0 OR a1.this_amt IS NULL
	THEN NULL
	ELSE ROUND(a1.this_amt/a2.this_amt,4) 
	END AS THIS_AMT_PPT,
	a1.year_amt,
	a1.year_amt_year,
	CASE WHEN a2.year_amt IS NULL OR a2.year_amt=0 OR a1.year_amt IS NULL
	THEN NULL
	ELSE ROUND(a1.year_amt/a2.year_amt,4) 
	END AS YEAR_AMT_PPT
FROM
  (
  SELECT
	 DATE_FORMAT(a.d_acct,'%Y-%m') 		AS D_ACCT,
	 d.pid AS TRECODE,
	 d.guoku_dscr AS TREDSCR,
	 a.subject_code AS SUBJECT_CODE,
	 a.subject_dscr AS SUBJECT_DSCR,
	 SUM(a.this_amt) AS THIS_AMT,
	 CASE WHEN b.this_amt IS NULL OR b.this_amt=0
	 THEN NULL
	 ELSE ROUND(((IFNULL(SUM(a.this_amt),0)-SUM(b.this_amt))/SUM(b.this_amt)),4) 
	 END AS THIS_AMT_YEAR,
	 a.year_amt AS YEAR_AMT,
	 CASE WHEN b.year_amt IS NULL OR b.year_amt=0
	 THEN NULL
	 ELSE ROUND(((IFNULL(a.year_amt,0)-b.year_amt)/b.year_amt),4) 
	 END AS YEAR_AMT_YEAR
  FROM stg.trs_tmis_budget_payout AS A
  LEFT JOIN stg.trs_tmis_budget_payout AS B
	 ON DATE_FORMAT(b.d_acct,'%Y-%m') = DATE_FORMAT(DATE_SUB(V_DATA_DATE,INTERVAL 1 YEAR),'%Y-%m')
	AND a.trecode=b.trecode
	AND a.subject_code=b.subject_code
	AND a.level=b.level
  JOIN (
	SELECT
		DISTINCT p.guoku_id AS PID,
		p.level,
		p.guoku_dscr,
		c.guoku_id AS CID
	FROM
	edw.cm_guoku_dimnsn p
	JOIN
	edw.cm_guoku_dimnsn c
	ON(
	     p.guoku_lvl_id_2 = c.guoku_lvl_id_1
	OR  p.guoku_lvl_id_3 = c.guoku_lvl_id_2
	OR  p.guoku_id = c.guoku_lvl_id_3	
		)
	) d 
	ON a.trecode = d.cid
  WHERE DATE_FORMAT(a.d_acct,'%Y-%m')=DATE_FORMAT(V_DATA_DATE,'%Y-%m')
  GROUP BY
	d.pid,
	a.subject_code
  )a1
  LEFT JOIN
  (
	SELECT
	 DATE_FORMAT(p.d_acct,'%Y-%m') 		AS D_ACCT,
         d.pid                                  AS TRECODE,
         SUM(THIS_AMT) 				AS THIS_AMT,
         SUM(YEAR_AMT) 				AS YEAR_AMT
       FROM stg.trs_tmis_budget_payout p
       LEFT JOIN (
	SELECT
		DISTINCT p.guoku_id AS PID,
		p.level,
		p.guoku_dscr,
		c.guoku_id AS CID
	FROM
	edw.cm_guoku_dimnsn p
	JOIN
	edw.cm_guoku_dimnsn c
	ON(
	     p.guoku_lvl_id_2 = c.guoku_lvl_id_1
	OR  p.guoku_lvl_id_3 = c.guoku_lvl_id_2
	OR  p.guoku_id = c.guoku_lvl_id_3	
		)
       ) d
       ON p.trecode=d.cid
       WHERE DATE_FORMAT(p.d_acct,'%Y-%m') = DATE_FORMAT(V_DATA_DATE,'%Y-%m')
       AND  SUBJECT_CODE IN ('T020101','T020201','T020601')
       GROUP BY
         DATE_FORMAT(p.d_acct,'%Y-%m'),
         d.pid
  )a2
  ON a1.d_acct=a2.d_acct
  AND a1.trecode=a2.trecode;
  
  
EXCEPTION
    WHEN OTHERS THEN
       GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
       CALL etl.edw_proc_error_log(P_DATA_DATE,V_START_TIME,NOW(),v_proc_name,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
	END;
/

DROP PROCEDURE IF EXISTS adm.p_trs_comprehensive_payout_quarter;

CREATE PROCEDURE adm.p_trs_comprehensive_payout_quarter(IN V_DATA_DATE  VARCHAR(10))
AS
    V_PROC_NAME     VARCHAR(255) := 'adm.p_trs_comprehensive_payout_quarter.PRC';
    V_START_TIME    CHAR(19) := NOW();
    V_STEP_ID       INT := 0;
    P_RESULT        INT := 0;
    V_DATES         VARCHAR(20) := 0;
    V_STATE CHAR(1);
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
    
V_STEP_ID := 1;    
DELETE FROM adm.trs_comprehensive_payout_quarter WHERE D_ACCT=CONCAT(YEAR(V_DATA_DATE),'Q',QUARTER(V_DATA_DATE));
	
V_STEP_ID := 2;   	
INSERT INTO adm.trs_comprehensive_payout_quarter
SELECT 
 D_ACCT,
 TRECODE,
 TREDSCR,
 SUBJECT_CODE,
 SUBJECT_DSCR,
 SUM(THIS_AMT),
 SUM(THIS_AMT_YEAR),
 SUM(THIS_AMT_PPT),
 SUM(YEAR_AMT),
 SUM(YEAR_AMT_YEAR),
 SUM(YEAR_AMT_PPT)
FROM 
(
-- 本期值
SELECT
	payout1.d_acct, 		
	payout1.trecode, 	
	payout1.tredscr,	
	payout1.subject_code,    
	payout1.subject_dscr,   	
	payout1.this_amt,        
	payout1.this_amt_year,
	payout1.this_amt /payout2.this_amt  	AS THIS_AMT_PPT,
	payout1.year_amt,
	payout1.year_amt_year,
	0				  	AS YEAR_AMT_PPT
FROM 
(
	SELECT
		CONCAT(YEAR(pay1.d_acct),'Q',QUARTER(pay1.d_acct)) AS D_ACCT,
		pay1.trecode AS TRECODE,
		pay1.tredscr AS TREDSCR,
		pay1.subject_code AS SUBJECT_CODE,
		pay1.subject_dscr AS SUBJECT_DSCR,
		SUM(pay1.this_amt) AS THIS_AMT,
		(SUM(pay1.this_amt)-SUM(pay2.this_amt))/SUM(pay2.this_amt) AS THIS_AMT_YEAR,
		0 AS YEAR_AMT,
		0 AS YEAR_AMT_YEAR
	FROM stg.trs_tmis_budget_payout PAY1
	LEFT JOIN stg.trs_tmis_budget_payout PAY2
	       ON pay2.d_acct = DATE_SUB(pay1.d_acct,INTERVAL 1 YEAR)
	      AND pay1.trecode =pay2.trecode
	      AND pay1.subject_code = pay2.subject_code
	      AND pay1.level = pay2.level
	WHERE CONCAT(YEAR(pay1.d_acct),'Q',QUARTER(pay1.d_acct)) = CONCAT(YEAR(V_DATA_DATE),'Q',QUARTER(V_DATA_DATE))
	GROUP BY
	      CONCAT(YEAR(pay1.d_acct),'Q',QUARTER(pay1.d_acct)),
	      pay1.trecode,
	      pay1.subject_code
) PAYOUT1         
LEFT JOIN 
(
	SELECT 
		CONCAT(YEAR(pay1.d_acct),'Q',QUARTER(pay1.d_acct)) AS D_ACCT,
		TRECODE,
		SUM(THIS_AMT) AS THIS_AMT,
		0	      AS YEAR_AMT
	FROM stg.trs_tmis_budget_payout AS PAY1
	WHERE CONCAT(YEAR(D_ACCT),'Q',QUARTER(D_ACCT)) = CONCAT(YEAR(V_DATA_DATE),'Q',QUARTER(V_DATA_DATE))
		AND SUBJECT_CODE IN ('T020101','T020201','T020601')		
	GROUP BY 
		CONCAT(YEAR(pay1.d_acct),'Q',QUARTER(pay1.d_acct)),
		TRECODE		
) PAYOUT2
       ON payout1.d_acct = payout2.d_acct
      AND payout1.trecode = payout2.trecode
      UNION ALL
-- 累计值
SELECT
	payout1.d_acct, 		
	payout1.trecode, 	
	payout1.tredscr,	
	payout1.subject_code,    
	payout1.subject_dscr,   	
	payout1.this_amt,        
	payout1.this_amt_year,
	0				  	AS THIS_AMT_PPT,
	payout1.year_amt,
	payout1.year_amt_year,
	payout1.year_amt / payout2.year_amt  	AS YEAR_AMT_PPT
FROM 
(
	SELECT
		CONCAT(YEAR(pay1.d_acct),'Q',QUARTER(pay1.d_acct)) AS D_ACCT,
		pay1.trecode AS TRECODE,
		pay1.tredscr AS TREDSCR,
		pay1.subject_code AS SUBJECT_CODE,
		pay1.subject_dscr AS SUBJECT_DSCR,
		0 		   AS THIS_AMT,
		0 		   AS THIS_AMT_YEAR,
		SUM(pay1.year_amt) AS YEAR_AMT,
		(SUM(pay1.year_amt)-SUM(pay2.year_amt))/SUM(pay2.year_amt) AS YEAR_AMT_YEAR
	FROM stg.trs_tmis_budget_payout PAY1
	LEFT JOIN stg.trs_tmis_budget_payout PAY2
	       ON pay2.d_acct = DATE_SUB(pay1.d_acct,INTERVAL 1 YEAR)
	      AND pay1.trecode =pay2.trecode
	      AND pay1.subject_code = pay2.subject_code
	      AND pay1.level = pay2.level
	WHERE pay1.d_acct =  CASE WHEN MONTH(V_DATA_DATE) IN ('1','2','3') THEN CONCAT(YEAR(V_DATA_DATE),'-03-01')
								    WHEN MONTH(V_DATA_DATE) IN ('4','5','6') THEN CONCAT(YEAR(V_DATA_DATE),'-06-01')
								    WHEN MONTH(V_DATA_DATE) IN ('7','8','9') THEN CONCAT(YEAR(V_DATA_DATE),'-09-01')
								    ELSE CONCAT(YEAR(V_DATA_DATE),'-12-01')  END
	GROUP BY
	      pay1.d_acct,
	      pay1.trecode,
	      pay1.subject_code
) PAYOUT1         
LEFT JOIN 
(
	SELECT 
		CONCAT(YEAR(pay1.d_acct),'Q',QUARTER(pay1.d_acct)) AS D_ACCT,
		TRECODE,
		SUM(THIS_AMT) AS THIS_AMT,
		SUM(YEAR_AMT) AS YEAR_AMT
	FROM stg.trs_tmis_budget_payout AS PAY1
	WHERE pay1.d_acct =  CASE WHEN MONTH(V_DATA_DATE) IN ('1','2','3') THEN CONCAT(YEAR(V_DATA_DATE),'-03-01')
							WHEN MONTH(V_DATA_DATE) IN ('4','5','6') THEN CONCAT(YEAR(V_DATA_DATE),'-06-01')
							WHEN MONTH(V_DATA_DATE) IN ('7','8','9') THEN CONCAT(YEAR(V_DATA_DATE),'-09-01')
							ELSE CONCAT(YEAR(V_DATA_DATE),'-12-01')  END
		AND SUBJECT_CODE IN ('T020101','T020201','T020601')		
	GROUP BY 
		pay1.d_acct,
		TRECODE		
) PAYOUT2
       ON payout1.d_acct = payout2.d_acct
      AND payout1.trecode = payout2.trecode
) A
      GROUP BY
            a.d_acct,
            a.trecode,
            a.subject_code;
CALL etl.edw_proc_trace_log(V_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
	
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
        CALL etl.edw_proc_error_log(date_format(V_DATA_DATE,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
	 END;
/

DROP PROCEDURE IF EXISTS adm.p_trs_comprehensive_payout_quarter_payoutqq;

CREATE PROCEDURE adm.p_trs_comprehensive_payout_quarter_payoutqq(IN V_DATA_DATE VARCHAR(10))
AS
v_proc_name VARCHAR(50) := 'adm.p_trs_comprehensive_payout_quarter_payoutqq';
V_STEP_ID   INT := '0';
P_DATA_DATE VARCHAR(50) := DATE_FORMAT(V_DATA_DATE,'%Y-%m');
V_START_TIME VARCHAR(50) := NOW();
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
/*综合查询收入季表*/
V_STEP_ID := 1;
DELETE FROM adm.trs_comprehensive_payout_quarter_payoutqq WHERE D_ACCT = CONCAT(YEAR(V_DATA_DATE),'Q',QUARTER(V_DATA_DATE));
V_STEP_ID := 2;
INSERT INTO adm.trs_comprehensive_payout_quarter_payoutqq
SELECT       
	a1.d_acct,
	a1.trecode,
	a1.tredscr,
	a1.subject_code,
	a1.subject_dscr,
	a1.this_amt,
	a1.this_amt_year,
	CASE WHEN a2.this_amt IS NULL OR a2.this_amt=0 OR a1.this_amt IS NULL
	THEN NULL
	ELSE ROUND(a1.this_amt/a2.this_amt,4) 
	END AS THIS_AMT_PPT,
	a1.year_amt,
	a1.year_amt_year,
	CASE WHEN a2.year_amt IS NULL OR a2.year_amt=0 OR a1.year_amt IS NULL
	THEN NULL
	ELSE ROUND(a1.year_amt/a2.year_amt,4) 
	END AS YEAR_AMT_PPT
FROM
  (
  SELECT
	 CONCAT(YEAR(a.d_acct),'Q',QUARTER(a.d_acct))  		AS D_ACCT,
	 d.pid AS TRECODE,
	 d.guoku_dscr AS TREDSCR,
	 a.subject_code AS SUBJECT_CODE,
	 a.subject_dscr AS SUBJECT_DSCR,
	 SUM(a.this_amt) AS THIS_AMT,
	 CASE WHEN b.this_amt IS NULL OR b.this_amt=0
	 THEN NULL
	 ELSE ROUND(((IFNULL(SUM(a.this_amt),0)-SUM(b.this_amt))/SUM(b.this_amt)),4) 
	 END AS THIS_AMT_YEAR,
	 a.year_amt AS YEAR_AMT,
	 CASE WHEN b.year_amt IS NULL OR b.year_amt=0
	 THEN NULL
	 ELSE ROUND(((IFNULL(a.year_amt,0)-b.year_amt)/b.year_amt),4) 
	 END AS YEAR_AMT_YEAR
  FROM stg.trs_tmis_budget_payout AS A
  LEFT JOIN stg.trs_tmis_budget_payout AS B
	 ON DATE_FORMAT(b.d_acct,'%Y-%m') = DATE_FORMAT(DATE_SUB(V_DATA_DATE,INTERVAL 1 YEAR),'%Y-%m')
	AND a.trecode=b.trecode
	AND a.subject_code=b.subject_code
	AND a.level=b.level
  JOIN (
	SELECT
		DISTINCT p.guoku_id AS PID,
		p.level,
		p.guoku_dscr,
		c.guoku_id AS CID
	FROM
	edw.cm_guoku_dimnsn p
	JOIN
	edw.cm_guoku_dimnsn c
	ON(
	     p.guoku_lvl_id_2 = c.guoku_lvl_id_1
	OR  p.guoku_lvl_id_3 = c.guoku_lvl_id_2
	OR  p.guoku_id = c.guoku_lvl_id_3	
		)
	) d 
	ON a.trecode = d.cid
  WHERE CONCAT(YEAR(a.d_acct),'Q',QUARTER(a.d_acct)) = CONCAT(YEAR(V_DATA_DATE),'Q',QUARTER(V_DATA_DATE))
  GROUP BY
	d.pid,
	a.subject_code
  )a1
  LEFT JOIN
  (
	SELECT
	 CONCAT(YEAR(p.d_acct),'Q',QUARTER(p.d_acct))	AS D_ACCT,
         d.pid                                  AS TRECODE,
         SUM(THIS_AMT) 				AS THIS_AMT,
         SUM(YEAR_AMT) 				AS YEAR_AMT
       FROM stg.trs_tmis_budget_payout p
       LEFT JOIN (
	SELECT
		DISTINCT p.guoku_id AS PID,
		p.level,
		p.guoku_dscr,
		c.guoku_id AS CID
	FROM
	edw.cm_guoku_dimnsn p
	JOIN
	edw.cm_guoku_dimnsn c
	ON(
	     p.guoku_lvl_id_2 = c.guoku_lvl_id_1
	OR  p.guoku_lvl_id_3 = c.guoku_lvl_id_2
	OR  p.guoku_id = c.guoku_lvl_id_3	
		)
       ) d
       ON p.trecode=d.cid
       WHERE CONCAT(YEAR(p.d_acct),'Q',QUARTER(p.d_acct)) = CONCAT(YEAR(V_DATA_DATE),'Q',QUARTER(V_DATA_DATE))
       AND  SUBJECT_CODE IN ('T020101','T020201','T020601')
       GROUP BY
         DATE_FORMAT(p.d_acct,'%Y-%m'),
         d.pid
  )a2
  ON a1.d_acct=a2.d_acct
  AND a1.trecode=a2.trecode;
  
EXCEPTION
    WHEN OTHERS THEN
       GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
       CALL etl.edw_proc_error_log(P_DATA_DATE,V_START_TIME,NOW(),v_proc_name,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
	END;
/

DROP PROCEDURE IF EXISTS adm.p_trs_kyd_enterprise;

CREATE PROCEDURE adm.p_trs_kyd_enterprise(IN V_DATA_DATE VARCHAR(10))
AS
BEGIN
/*分企业-当期and累计（凯盈达）*/
DELETE FROM adm.trs_kyd_enterprise WHERE D_ACCT = DATE_FORMAT(V_DATA_DATE,'%Y-%m') and mark = '0';
INSERT INTO adm.trs_kyd_enterprise
SELECT
	DATE_FORMAT(det.d_acct,'%Y-%m')   		AS D_ACCT,
	det.s_trecode     		AS S_TRECODE,
	det.s_tredscr 			AS S_TREDSCR,
	det.etpcode			AS ENTERPRISE_CODE,
	det.etpname			AS ENTERPRISE_NAME,
	SUM(CASE WHEN det.s_bdgsbtcode like '101%' THEN det.f_amt
	     ELSE 0 		END)    AS F_AMT_101,
	SUM(CASE WHEN det.s_bdgsbtcode like '101%' THEN det2.f_amt
	     ELSE 0 		END)	AS F_AMT_101_YEAR,
	SUM(CASE WHEN det.s_bdgsbtcode LIKE '10101%' THEN det.f_amt
	     ELSE 0 		END)	AS F_AMT_1010101,
	SUM(CASE WHEN det.s_bdgsbtcode LIKE '10101%' THEN det2.f_amt
	     ELSE 0 		END)	AS F_AMT_1010101_YEAR,
	SUM(CASE WHEN det.s_bdgsbtcode LIKE '10102%' THEN det.f_amt
	     ELSE 0 		END)	AS F_AMT_1010201,
	SUM(CASE WHEN det.s_bdgsbtcode LIKE '10102%' THEN det2.f_amt
	     ELSE 0 		END)	AS F_AMT_1010201_YEAR,
	SUM(CASE WHEN det.s_bdgsbtcode LIKE '10104%' THEN det.f_amt
	     ELSE 0 		END)	AS F_AMT_10104,
	SUM(CASE WHEN det.s_bdgsbtcode LIKE '10104%' THEN det2.f_amt
	     ELSE 0 		END)	AS F_AMT_10104_YEAR,
	SUM(CASE WHEN det.s_bdgsbtcode LIKE '10106%' THEN det.f_amt
	     ELSE 0 		END)	AS F_AMT_10106,
	SUM(CASE WHEN det.s_bdgsbtcode LIKE '10106%' THEN det2.f_amt
	     ELSE 0 		END)	AS F_AMT_10106_YEAR,
	SUM(CASE WHEN det.s_bdgsbtcode LIKE '10107%' THEN det.f_amt
	     ELSE 0 		END)	AS F_AMT_10107,
	SUM(CASE WHEN det.s_bdgsbtcode LIKE '10107%' THEN det2.f_amt
	     ELSE 0 		END)	AS F_AMT_10107_YEAR,
	SUM(CASE WHEN det.s_bdgsbtcode LIKE '10109%' THEN det.f_amt
	     ELSE 0 		END)	AS F_AMT_10109,
	SUM(CASE WHEN det.s_bdgsbtcode LIKE '10109%' THEN det2.f_amt
	     ELSE 0 		END)	AS F_AMT_10109_YEAR,
	SUM(CASE WHEN det.s_bdgsbtcode like '10110%' THEN det.f_amt
	     ELSE 0 		END)	AS F_AMT_10110,
	SUM(CASE WHEN det.s_bdgsbtcode like '10110%' THEN det2.f_amt
	     ELSE 0 		END)	AS F_AMT_10110_YEAR,
	SUM(CASE WHEN det.s_bdgsbtcode like '10111%' THEN det.f_amt
	     ELSE 0 		END)	AS F_AMT_10111,
	SUM(CASE WHEN det.s_bdgsbtcode like '10111%' THEN det2.f_amt
	     ELSE 0 		END)	AS F_AMT_10111_YEAR,
	SUM(CASE WHEN det.s_bdgsbtcode like '10112%' THEN det.f_amt
	     ELSE 0 		END)	AS F_AMT_10112,
	SUM(CASE WHEN det.s_bdgsbtcode like '10112%' THEN det2.f_amt
	     ELSE 0 		END)	AS F_AMT_10112_YEAR,
	SUM(CASE WHEN det.s_bdgsbtcode like '10113%' THEN det.f_amt
	     ELSE 0 		END)	AS F_AMT_10113,
	SUM(CASE WHEN det.s_bdgsbtcode like '10113%' THEN det2.f_amt
	     ELSE 0 		END)	AS F_AMT_10113_YEAR,
	SUM(CASE WHEN det.s_bdgsbtcode like '10116%' THEN det.f_amt
	     ELSE 0 		END)	AS F_AMT_10116,
	SUM(CASE WHEN det.s_bdgsbtcode like '10116%' THEN det2.f_amt
	     ELSE 0 		END)	AS F_AMT_10116_YEAR,
	SUM(CASE WHEN det.s_bdgsbtcode like '10114%' THEN det.f_amt
	     ELSE 0 		END)	AS F_AMT_10114,
	SUM(CASE WHEN det.s_bdgsbtcode like '10114%' THEN det2.f_amt
	     ELSE 0 		END)	AS F_AMT_10114_YEAR,
	SUM(CASE WHEN det.s_bdgsbtcode like '10118%' THEN det.f_amt
	     ELSE 0 		END)	AS F_AMT_10118,
	SUM(CASE WHEN det.s_bdgsbtcode like '10118%' THEN det2.f_amt
	     ELSE 0 		END)	AS F_AMT_10118_YEAR,
	SUM(CASE WHEN det.s_bdgsbtcode like '10119%' THEN det.f_amt
	     ELSE 0 		END)	AS F_AMT_10119,
	SUM(CASE WHEN det.s_bdgsbtcode like '10119%' THEN det2.f_amt
	     ELSE 0 		END)	AS F_AMT_10119_YEAR,
	SUM(CASE WHEN det.s_bdgsbtcode LIKE '10120%' THEN det.f_amt
	     ELSE 0 		END)	AS F_AMT_10120,
	SUM(CASE WHEN det.s_bdgsbtcode LIKE '10120%' THEN det2.f_amt
	     ELSE 0 		END)	AS F_AMT_10120_year,
	SUM(CASE WHEN det.s_bdgsbtcode like '10121%' THEN det.f_amt
	     ELSE 0 		END)	AS F_AMT_10121,
	SUM(CASE WHEN det.s_bdgsbtcode like '10121%' THEN det2.f_amt
	     ELSE 0 		END)	AS F_AMT_10121_YEAR,
	SUM(CASE WHEN det.s_bdgsbtcode LIKE '10199%'  THEN det.f_amt
	     ELSE 0 		END)	AS F_AMT_99999,
	SUM(CASE WHEN det.s_bdgsbtcode LIKE '10199%' THEN det2.f_amt
	     ELSE 0 		END)	AS F_AMT_99999_YEAR,
	'0' 				AS MARK
FROM edw.trs_kyd_industry DET
left join edw.trs_kyd_industry DET2
       ON det2.d_acct = DATE_SUB(det.d_acct,INTERVAL 1 YEAR)
			AND det.s_trecode = det2.s_trecode
		  AND det.etpname = det2.etpname
		  AND det.lev_4_id = det2.lev_4_id
			AND det.s_bdgsbtcode = det2.s_bdgsbtcode
WHERE det.d_acct LIKE CONCAT(DATE_FORMAT(V_DATA_DATE,'%Y%m'),'%')
and det.lev_4_id <> 'null'
GROUP BY
      DATE_FORMAT(det.d_acct,'%Y-%m'),
      det.s_trecode,
      det.etpname;
	
	commit;
	
DELETE FROM adm.trs_kyd_enterprise WHERE D_ACCT = DATE_FORMAT(V_DATA_DATE,'%Y-%m') AND mark = '1';
INSERT INTO adm.trs_kyd_enterprise
select 
	DATE_FORMAT(V_DATA_DATE,'%Y-%m') as d_acct,
	ent.s_trecode,
	ent.s_tredscr,
	ent.procode,
	ent.proname,
	sum(ent.f_amt_101),
	sum(ent.f_amt_101_year),
	SUM(ent.f_amt_1010101),
	SUM(ent.f_amt_1010101_year),
	SUM(ent.f_amt_1010201),
	SUM(ent.f_amt_1010201_year),
	SUM(ent.f_amt_10104),
	SUM(ent.f_amt_10104_year),
	SUM(ent.f_amt_10106),
	SUM(ent.f_amt_10106_year),
	SUM(ent.f_amt_10107),
	SUM(ent.f_amt_10107_year),
	SUM(ent.f_amt_10109),
	SUM(ent.f_amt_10109_year),
	SUM(ent.f_amt_10110),
	SUM(ent.f_amt_10110_year),
	SUM(ent.f_amt_10111),
	SUM(ent.f_amt_10111_year),
	SUM(ent.f_amt_10112),
	SUM(ent.f_amt_10112_year),
	SUM(ent.f_amt_10113),
	SUM(ent.f_amt_10113_year),
	SUM(ent.f_amt_10116),
	SUM(ent.f_amt_10116_year),
	SUM(ent.f_amt_10114),
	SUM(ent.f_amt_10114_year),
	SUM(ent.f_amt_10118),
	SUM(ent.f_amt_10118_year),
	SUM(ent.f_amt_10119),
	SUM(ent.f_amt_10119_year),
	SUM(ent.f_amt_10120),
	SUM(ent.f_amt_10120_year),
	SUM(ent.f_amt_10121),
	SUM(ent.f_amt_10121_year),
	SUM(ent.f_amt_99999),
	SUM(ent.f_amt_99999_year),
	'1'
from adm.trs_kyd_enterprise ent
where ent.d_acct between date_format(V_DATA_DATE,'%Y-01') and  DATE_FORMAT(V_DATA_DATE,'%Y-%m')
	and ent.mark = '0'
group by 
	ent.s_trecode,
	ent.proname;
COMMIT;
	END;
/

DROP PROCEDURE IF EXISTS adm.p_trs_kyd_enterprise_rank;

CREATE PROCEDURE adm.p_trs_kyd_enterprise_rank(IN V_DATA_DATE VARCHAR(10))
AS
BEGIN
/*企业排名（凯盈达）*/
DELETE FROM adm.trs_kyd_enterprise_rank WHERE D_ACCT = DATE_FORMAT(V_DATA_DATE,'%Y-%m');
INSERT INTO adm.trs_kyd_enterprise_rank
SELECT
	D_ACCT,
	ENTERPRISE_CODE,
	ENTERPRISE_NAME,
	SUM(F_AMT),
	SUM(F_AMT_TB),
	SUM(F_AMT_YEAR),
	SUM(F_AMT_YEAR_TB),
	LEV_1_ID,
        LEV_1_DSCR,
	LEV_2_ID,
	LEV_2_DSCR,
	LEV_4_ID,
	LEV_4_DSCR,
	S_TRECODE,
	S_TREDSCR
FROM
(
-- 当期值
select 
	DATE_FORMAT(V_DATA_DATE,'%Y-%m')   		AS D_ACCT,
	det.etpcode					AS ENTERPRISE_CODE,
	det.etpname					AS ENTERPRISE_NAME,
	sum(det.f_amt)					as F_AMT,
	''						as F_AMT_tb,
	''						as F_AMT_year,
	'' 						as F_AMT_year_tb,
	det.lev_1_id					AS LEV_1_ID,
	det.lev_1_dscr					AS LEV_1_DSCR,
	det.lev_2_id					AS LEV_2_ID,
	det.lev_2_dscr					AS LEV_2_DSCR,
	det.lev_4_id					AS LEV_4_ID,
	det.lev_4_dscr					as LEV_4_DSCR,
	det.s_trecode					as s_trecode,
	det.s_tredscr 					as s_tredscr
FROM edw.trs_kyd_industry DET
WHERE det.d_acct LIKE CONCAT(DATE_FORMAT(V_DATA_DATE,'%Y%m'),'%')
and det.lev_4_id <> 'null'
GROUP BY
      DATE_FORMAT(det.d_acct,'%Y-%m'),
      det.s_trecode,
      det.etpname,
      det.lev_1_id,
      det.lev_1_dscr,
      det.lev_2_id,
      det.lev_2_dscr,
      det.lev_4_id,
      det.lev_4_dscr
      
      union all
-- 累计值
SELECT 
	DATE_FORMAT(V_DATA_DATE,'%Y-%m')   		AS D_ACCT,
	det.etpcode					AS ENTERPRISE_CODE,
	det.etpname					AS ENTERPRISE_NAME,
	''						AS F_AMT,
	''						AS F_AMT_tb,
	SUM(det.f_amt)					AS F_AMT_year,
	''		 				AS F_AMT_year_tb,
	det.lev_1_id					AS LEV_1_ID,
	det.lev_1_dscr					AS LEV_1_DSCR,
	det.lev_2_id					AS LEV_2_ID,
	det.lev_2_dscr					AS LEV_2_DSCR,
	det.lev_4_id					AS LEV_4_ID,
	det.lev_4_dscr					AS LEV_4_DSCR,
	det.s_trecode					AS s_trecode,
	det.s_tredscr 					AS s_tredscr
FROM edw.trs_kyd_industry DET
WHERE DATE_FORMAT(det.d_acct,'%Y-%m') between DATE_FORMAT(V_DATA_DATE,'%Y-01') and date_format(V_DATA_DATE,'%Y-%m')
and det.lev_4_id <> 'null'
GROUP BY
      DATE_FORMAT(det.d_acct,'%Y'),
      det.s_trecode,
      det.etpname,
      det.lev_1_id,
      det.lev_1_dscr,
      det.lev_2_id,
      det.lev_2_dscr,
      det.lev_4_id,
      det.lev_4_dscr
) A
GROUP BY
	a.d_acct,
	a.enterprise_name,
        LEV_1_ID,
        LEV_1_DSCR,
	LEV_2_ID,
	LEV_2_DSCR,
	LEV_4_ID,
	LEV_4_DSCR,
	a.s_trecode;
	
	END;
/

DROP PROCEDURE IF EXISTS adm.p_trs_kyd_industry;

CREATE PROCEDURE adm.p_trs_kyd_industry(in V_DATA_DATE VARCHAR(10))
AS
BEGIN
/*凯盈达-分行业*/
DELETE FROM adm.trs_kyd_industry WHERE D_ACCT = DATE_FORMAT(V_DATA_DATE,'%Y-%m')  AND mark = '0';
