INSERT INTO adm.trs_mth_income_industry
SELECT
	DATE_FORMAT(q.d_acct,'%Y-%m'),
	q.procode,	 	
	q.project,		
	b.pid     				AS S_TRECODE,
	q.enterprise_code			AS ENTERPRISE_CODE,
	q.enterprise_name			AS ENTERPRISE_NAME,
	SUM(q.f_amt_101),
	SUM(q.f_amt_101_year)			AS F_AMT_101_YEAR,
	SUM(q.f_amt_10101),
	SUM(q.f_amt_10101_year)			AS F_AMT_10101_YEAR,
	SUM(q.f_amt_1010101),
	SUM(q.f_amt_1010101_year)		AS F_AMT_1010101_YEAR,
	SUM(q.f_amt_1010104),
	SUM(q.f_amt_1010104_year)		AS F_AMT_1010104_YEAR,
	SUM(q.f_amt_10102),
	SUM(q.f_amt_10102_year)			AS F_AMT_10102_YEAR,
	SUM(q.f_amt_1010201),
	SUM(q.f_amt_1010201_year)		AS F_AMT_1010201_YEAR,
	SUM(q.f_amt_10104),
	SUM(q.f_amt_10104_year)			AS F_AMT_10104_YEAR,
	SUM(q.f_amt_10106),		
	SUM(q.f_amt_10106_year)			AS F_AMT_10106_YEAR,
	SUM(q.f_amt_10107),		
	SUM(q.f_amt_10107_year)			AS F_AMT_10107_YEAR,
	SUM(q.f_amt_10109),		
	SUM(q.f_amt_10109_year)			AS F_AMT_10109_YEAR,
	SUM(q.f_amt_10110),		
	SUM(q.f_amt_10110_year)			AS F_AMT_10110_YEAR,
	SUM(q.f_amt_10111),		
	SUM(q.f_amt_10111_year)			AS F_AMT_10111_YEAR,
	SUM(q.f_amt_10112),		
	SUM(q.f_amt_10112_year)			AS F_AMT_10112_YEAR,
	SUM(q.f_amt_10113),		
	SUM(q.f_amt_10113_year)			AS F_AMT_10113_YEAR,
	SUM(q.f_amt_10116),		
	SUM(q.f_amt_10116_year)			AS F_AMT_10116_YEAR,
	SUM(q.f_amt_10115),		
	SUM(q.f_amt_10115_year)			AS F_AMT_10115_YEAR,
	SUM(q.f_amt_10114),		
	SUM(q.f_amt_10114_year)			AS F_AMT_10114_YEAR,
	SUM(q.f_amt_10117),		
	SUM(q.f_amt_10117_year)			AS F_AMT_10117_YEAR,
	SUM(q.f_amt_10118),		
	SUM(q.f_amt_10118_year)			AS F_AMT_10118_YEAR,
	SUM(q.f_amt_10119),		
	SUM(q.f_amt_10119_year)			AS F_AMT_10119_YEAR,
	SUM(q.f_amt_10121),		
	SUM(q.f_amt_10121_year)			AS F_AMT_10121_YEAR,
	SUM(q.f_amt_10120),
	SUM(q.f_amt_10120_year)			AS F_AMT_10120_YEAR,
	''					AS F_AMT_99999,
	''					AS F_AMT_99999_YEAR,
	'0' 					AS S_BELONGFLAG
from adm.trs_mth_income_industry Q
LEFT JOIN 
(
SELECT 
	DISTINCT 
	p.guoku_id AS PID,
	p.level,
	p.guoku_dscr,
	c.guoku_id AS CID
FROM edw.cm_guoku_dimnsn p
LEFT JOIN edw.cm_guoku_dimnsn c
ON p.guoku_lvl_id_2 = c.guoku_lvl_id_1 
OR  p.guoku_lvl_id_3 = c.guoku_lvl_id_2 
OR  p.guoku_id = c.guoku_lvl_id_3
) B 
     ON q.s_trecode = b.cid
WHERE DATE_FORMAT(q.d_acct,'%Y-%m') = DATE_FORMAT(V_DATA_DATE,'%Y-%m')
  AND q.s_belongflag = '1'
GROUP BY
      DATE_FORMAT(q.d_acct,'%Y-%m'),
      q.procode,
      b.pid,
      q.enterprise_code;
      
  
  -- 更新表中其他各税
UPDATE adm.trs_mth_income_industry A,
(
SELECT 
*
FROM adm.trs_mth_income_industry 
WHERE D_ACCT = DATE_FORMAT(DATE_SUB(V_DATA_DATE,INTERVAL 1 YEAR),'%Y-%m')
) B
SET a.f_amt_99999 = (a.f_amt_101-a.f_amt_10101-a.f_amt_10102-a.f_amt_10104-a.f_amt_10106-a.f_amt_10107-
	       a.f_amt_10109-a.f_amt_10110-a.f_amt_10111-a.f_amt_10112-a.f_amt_10113-a.f_amt_10116-
	       a.f_amt_10115-a.f_amt_10114-a.f_amt_10117-a.f_amt_10118-a.f_amt_10119-a.f_amt_10121-a.f_amt_10120),
    a.f_amt_99999_year = (b.f_amt_101-b.f_amt_10101-b.f_amt_10102-b.f_amt_10104-b.f_amt_10106-b.f_amt_10107-
	       b.f_amt_10109-b.f_amt_10110-b.f_amt_10111-b.f_amt_10112-b.f_amt_10113-b.f_amt_10116-
	       b.f_amt_10115-b.f_amt_10114-b.f_amt_10117-b.f_amt_10118-b.f_amt_10119-b.f_amt_10121-b.f_amt_10120)
WHERE a.d_acct = DATE_FORMAT(V_DATA_DATE,'%Y-%m')
  AND a.procode  = b.procode
  AND a.s_trecode  = b.s_trecode
  AND a.enterprise_code  = b.enterprise_code;
	END;
/

DROP PROCEDURE IF EXISTS adm.p_trs_sk_agentbankpay_back_detail;

CREATE PROCEDURE adm.p_trs_sk_agentbankpay_back_detail(IN v_data_date VARCHAR(10))
AS
V_STEP_ID       INT := 0; 
V_PROC_NAME     VARCHAR(80) := 'adm.p_trs_sk_agentbankpay_back_detail.prc';
V_START_TIME    CHAR(19) := NOW();
v_log_date      CHAR(10);
    V_RETURN_CODE TEXT;
    V_ERROR_MSG TEXT;
BEGIN
--     AUTHOR     : yeqian
--     NAME       : adm.p_trs_sk_agentbankpay_back_detail.HQL 
--     FUNCTIONS  : 
--     PURPOSE    : MONTHLY SAVING THE VARIATION DATA FROM stg
--     DATASOURCE : stg.trs_stat_agentbankpay_detail  -- -- ##集中支付退款业务多维度分析
--                : 
--     REVISIONS OR COMMENTS
--     VER        DATE       DEVELOPER       TESTER         DESCRIPTION
--   --------  ----------  -------------  -------------  ---------------------
--     1.0     2018-11-29   yeqian                      1.CREATE THE PROCEDURE
--
    /* EXCEPTION HANDLER  */
	
   v_log_date := DATE_FORMAT(v_data_date,'%Y-%m-%d');
   v_data_date := DATE_FORMAT(v_data_date,'%Y-%m-%d');
   
   
-- 删除当期的数据
V_STEP_ID := 1;
DELETE FROM adm.trs_sk_agentbankpay_back_detail where DATE_FORMAT(S_ENTRUSTDATE,'%Y-%m-%d') = v_data_date;
V_STEP_ID := 2;
  
-- 集中支付退款业务多维度分析
INSERT INTO adm.trs_sk_agentbankpay_back_detail
SELECT 
  SUBSTR(S_ENTRUSTDATE,1,4)      AS S_ENTRUSTYRAR,      -- -- #委托时间-年
  SUBSTR(S_ENTRUSTDATE,1,6)      AS S_ENTRUSTMOTH,      -- -- #委托时间-月
  S_ENTRUSTDATE                  AS S_ENTRUSTDATE,      -- -- #委托时间-日
  S_TRECODE                      AS S_TRECODE,          -- -- #国库代码
  S_PAYMODE                      AS S_PAYMODE,          -- -- #支付方式
  S_AGENTBANKCLASS               AS S_AGENTBANKCLASS,   -- -- #代理银行行别
  CONCAT(S_TRECODE,S_BDGORGCODE) AS S_BDGORGTRECODE,    -- -- #预算单位国库编码
  S_EXPFUNCCODE                  AS S_EXPFUNCCODE,      -- -- #支出功能科目编码
  F_PAYAMT                       AS F_PAYAMT,           -- -- #支付金额
  '1'                            AS F_AMOUNT            -- -- #支付笔数
FROM 
  ods.trs_stat_agentbankpay_back_detail WHERE DATE_FORMAT(S_ENTRUSTDATE,'%Y-%m-%d') = v_data_date;
COMMIT;
  CALL etl.edw_proc_trace_log(DATE_FORMAT(v_log_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
EXCEPTION
    WHEN OTHERS THEN
        GET DIAGNOSTICS CONDITION 1 V_RETURN_CODE = RETURNED_SQLSTATE ,V_ERROR_MSG = MESSAGE_TEXT;
         CALL etl.edw_proc_error_log(DATE_FORMAT(v_log_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,V_RETURN_CODE,V_ERROR_MSG);
         CALL etl.edw_proc_trace_log(DATE_FORMAT(v_log_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
	END;
/

