DROP PROCEDURE IF EXISTS adm.test_loop1;

CREATE PROCEDURE adm.test_loop1(IN s_date DATE,IN edate DATE)
AS
  V_START_TIME    CHAR(19) := NOW();
  V_PROC_NAME     VARCHAR(80) := 'adm.test_loop.PRC';
  V_STEP_ID       INT := 0;
  V_SQL_INSERT    LONGTEXT := ''; -- 插数语句SQL
  V_SQLTXT        LONGTEXT := ''; -- 执行SQL
BEGIN
  -- DECLARE  data_date DATE ;  -- 数据日期
  -- SET data_date =  '2018-01-01';
  WHILE s_date <= edate
  LOOP
  
  SELECT s_date;
-- 功能分类预算收入-日
-- DROP TABLE adm.trs_budget_function_income_daily
-- CREATE TABLE adm.trs_budget_function_income_daily AS
delete from adm.trs_budget_function_income_daily where D_REPORTDATE = s_date;
insert into adm.trs_budget_function_income_daily
SELECT
 DATE_FORMAT(aa.d_reportdate,'%Y-%m-%d') AS D_REPORTDATE,
 aa.s_trecode AS S_TRECODE,
 aa.c_budgetlevel AS C_BUDGETLEVEL,
 dt1.subject_code_4 AS SUBJECT_CODE_4,
 dt1.subject_dscr_4 AS SUBJECT_DSCR_4,
 dt1.fun_class_code_1 AS FUN_CLASS_CODE_1,
 dt1.fun_class_dscr_1 AS FUN_CLASS_DSCR_1,
 dt1.fun_class_code_2 AS FUN_CLASS_CODE_2,
 dt1.fun_class_dscr_2 AS FUN_CLASS_DSCR_2,
 dt1.fun_class_code_3 AS FUN_CLASS_CODE_3,
 dt1.fun_class_dscr_3 AS FUN_CLASS_DSCR_3,
 aa.f_dayamt AS THIS_PERIOD_AMT,
 bb.f_dayamt AS LAST_PERIOD_AMT,
 aa.f_yearamt AS THIS_PERIOD_YEARAMT,
 bb.f_yearamt AS LAST_PERIOD_YEARAMT,
 CURRENT_TIMESTAMP AS UPDATE_DATE
FROM
(
  -- -- 本期预算收入
	SELECT 
	 t1.d_reportdate AS D_REPORTDATE,
	 t1.s_trecode AS S_TRECODE,
	 t1.c_budgetlevel AS C_BUDGETLEVEL,
	 t1.s_budgetsubjectcode AS S_BUDGETSUBJECTCODE,
	 t1.s_budgetsubjectname AS S_BUDGETSUBJECTNAME,
	 SUM(t1.f_dayamt) AS F_DAYAMT,
	 SUM(t1.f_yearamt) AS F_YEARAMT
	FROM edw.trs_d003_tr_budget_income t1
	WHERE  D_REPORTDATE = s_date
-- 	AND S_TAXORGCODE NOT IN('000000000000','111111111111','222222222222','333333333333','444444444444','555555555555') 
	AND S_TAXORGCODE = 'XXXXXXXXXXXX'
	GROUP BY
	t1.d_reportdate,
	t1.s_trecode,
	t1.c_budgetlevel,
	t1.s_budgetsubjectcode,
	t1.s_budgetsubjectname
	UNION ALL
   -- -- 本期调拨收入（转移性收入）
	SELECT 
	 t1.d_reportdate AS D_REPORTDATE,
	 t1.s_trecode AS S_TRECODE,
	 t1.c_budgetlevel AS C_BUDGETLEVEL,
	 t1.s_budgetsubjectcode AS S_BUDGETSUBJECTCODE,
	 t1.s_budgetsubjectname AS S_BUDGETSUBJECTNAME,
	 SUM(t1.f_dayamt) AS F_DAYAMT,
	 SUM(t1.f_yearamt) AS F_YEARAMT
	FROM edw.trs_d003_tr_move_income t1
	WHERE  D_REPORTDATE = s_date
	GROUP BY
	t1.d_reportdate,
	t1.s_trecode,
	t1.c_budgetlevel,
	t1.s_budgetsubjectcode,
	t1.s_budgetsubjectname
) aa
LEFT JOIN
-- --去年同期
(
  -- -- 预算收入
	SELECT 
	 t1.d_reportdate AS D_REPORTDATE,
	 t1.s_trecode AS S_TRECODE,
	 t1.c_budgetlevel AS C_BUDGETLEVEL,
	 t1.s_budgetsubjectcode AS S_BUDGETSUBJECTCODE,
	 t1.s_budgetsubjectname AS S_BUDGETSUBJECTNAME,
	 SUM(t1.f_dayamt) AS F_DAYAMT,
	 SUM(t1.f_yearamt) AS F_YEARAMT
	FROM edw.trs_d003_tr_budget_income t1
	WHERE  D_REPORTDATE = DATE_SUB(s_date,INTERVAL 1 YEAR)
	AND S_TAXORGCODE NOT IN('000000000000','111111111111','222222222222','333333333333','444444444444','555555555555') 
	GROUP BY
	t1.d_reportdate,
	t1.s_trecode,
	t1.c_budgetlevel,
	t1.s_budgetsubjectcode,
	t1.s_budgetsubjectname
	UNION ALL
   -- -- 调拨收入（转移性收入）
	SELECT 
	 t1.d_reportdate AS D_REPORTDATE,
	 t1.s_trecode AS S_TRECODE,
	 t1.c_budgetlevel AS C_BUDGETLEVEL,
	 t1.s_budgetsubjectcode AS S_BUDGETSUBJECTCODE,
	 t1.s_budgetsubjectname AS S_BUDGETSUBJECTNAME,
	 SUM(t1.f_dayamt) AS F_DAYAMT,
	 SUM(t1.f_yearamt) AS F_YEARAMT
	FROM edw.trs_d003_tr_move_income t1
	WHERE  D_REPORTDATE = DATE_SUB(s_date,INTERVAL 1 YEAR)
	GROUP BY
	t1.d_reportdate,
	t1.s_trecode,
	t1.c_budgetlevel,
	t1.s_budgetsubjectcode,
	t1.s_budgetsubjectname
) bb
ON  aa.d_reportdate = DATE_ADD(bb.d_reportdate,INTERVAL 1 YEAR)
AND aa.s_trecode = bb.s_trecode
AND aa.c_budgetlevel = bb.c_budgetlevel
AND aa.s_budgetsubjectcode = bb.s_budgetsubjectcode
JOIN
(
SELECT
a.fun_class_code_1 AS FUN_CLASS_CODE_1,
a.fun_class_dscr_1 AS FUN_CLASS_DSCR_1,
a.fun_class_code_2 AS FUN_CLASS_CODE_2,
a.fun_class_dscr_2 AS FUN_CLASS_DSCR_2,
a.fun_class_code_3 AS FUN_CLASS_CODE_3,
a.fun_class_dscr_3 AS FUN_CLASS_DSCR_3,
b.subject_code_4 AS SUBJECT_CODE_4,
b.subject_dscr_4 AS SUBJECT_DSCR_4
FROM
edw.cm_guoku_functional_type a
LEFT JOIN
edw.cm_guoku_rcpt_dsb b
ON  a.fun_class_code_3 = b.t_class_code_3
WHERE
-- b.of_year = YEAR(s_date)
 a.fun_class_code_1 = 'T01'
) dt1
ON aa.s_budgetsubjectcode = dt1.subject_code_4
  
  
 
  
  
 ;
  
 
 CALL etl.edw_proc_trace_log(DATE_FORMAT(s_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  s_date := DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END LOOP;
END;
/

DROP PROCEDURE IF EXISTS adm.test_loop2;

CREATE PROCEDURE adm.test_loop2(IN s_date DATE,IN edate DATE)
AS
  V_START_TIME    CHAR(19) := NOW();
  V_PROC_NAME     VARCHAR(80) := 'adm.test_loop2.PRC';
  V_STEP_ID       INT := 0;
  V_SQL_INSERT    LONGTEXT := ''; -- 插数语句SQL
  V_SQLTXT        LONGTEXT := ''; -- 执行SQL
BEGIN
  -- DECLARE  data_date DATE ;  -- 数据日期
  -- SET data_date =  '2018-01-01';
  WHILE s_date <= edate
  LOOP
	  V_STEP_ID := 1;
	  delete from  adm.trs_sk_subject_income where  REPORTDATE=s_date;  
	  V_STEP_ID := 2;
	  INSERT INTO adm.trs_sk_subject_income
	SELECT
	 a.d_expfile                         AS REPORTDATE        -- 时间（日）
	,DATE_FORMAT(a.d_expfile,'%Y-%m')    AS D_MONTH           -- 时间（月）
	,DATE_FORMAT(a.d_expfile,'%Y')       AS D_YEAR            -- 时间（年）
	 --  ,b.guoku_lvl_id_1                    AS GUOKU_LVL_ID_1    -- 所属省国库代码
	 --  ,b.guoku_lvl_dscr_1                  AS GUOKU_LVL_DSCR_1  -- 所属省国库名称
	 --  ,b.guoku_lvl_id_2                    AS GUOKU_LVL_ID_2    -- 所属市国库代码
	 --  ,b.guoku_lvl_dscr_2                  AS GUOKU_LVL_DSCR_2  -- 所属市国库名称
	,a.s_trecode                         AS GUOKU_ID    -- 所属县国库代码
	 --  ,b.guoku_dscr                        AS GUOKU_LVL_DSCR_3  -- 所属县国库名称
	 --  ,c.subject_code_1                    AS SUBJECT_CODE_1    -- 科目类级代码
	 --  ,c.subject_dscr_1                    AS SUBJECT_DSCR_1    -- 科目类级名称
	 --  ,c.subject_code_2                    AS SUBJECT_CODE_2    -- 科目款级代码
	 --  ,c.subject_dscr_2                    AS SUBJECT_DSCR_2    -- 科目款级名称
	 --  ,c.subject_code_3                    AS SUBJECT_CODE_3    -- 科目项级代码
	 --  ,c.subject_dscr_3                    AS SUBJECT_DSCR_3    -- 科目项级名称
	,a.s_bdgsbtcode                      AS SUBJECT_CODE_4    -- 科目目级代码
	 -- ,c.subject_dscr_4                    AS SUBJECT_DSCR_4    -- 科目目级名称
	,a.s_bdglevel                        AS BUDGETLEVEL_CODE  -- 预算级次代码
	,d.budget_dscr                       AS BUDGETLEVEL_DSCR  -- 预算级次描述
	,a.f_dayamt                          AS F_DAYAMT          -- 日金额
	FROM edw.trs_d005_tr_bdgincm A
	 --  LEFT JOIN edw.cm_guoku_dimnsn B 
	 --  ON a.s_trecode=b.guoku_id
	 --  LEFT JOIN edw.cm_guoku_rcpt_dsb C
	 --  ON a.s_bdgsbtcode=c.subject_code_4
	LEFT JOIN edw.cm_guoku_budget_level D
	ON a.s_bdglevel=d.budget_code
	WHERE a.d_expfile = s_date
	UNION ALL
	SELECT
	 b.d_expfile                         AS REPORTDATE        -- 时间（日）
	,DATE_FORMAT(b.d_expfile,'%Y-%m')    AS D_MONTH           -- 时间（月）
	,DATE_FORMAT(b.d_expfile,'%Y')       AS D_YEAR            -- 时间（年）
	 --  ,c.guoku_lvl_id_1                    AS GUOKU_LVL_ID_1    -- 所属省国库代码
	 --  ,c.guoku_lvl_dscr_1                  AS GUOKU_LVL_DSCR_1  -- 所属省国库名称
	 --  ,c.guoku_lvl_id_2                    AS GUOKU_LVL_ID_2    -- 所属市国库代码
	 --  ,c.guoku_lvl_dscr_2                  AS GUOKU_LVL_DSCR_2  -- 所属市国库名称
	,b.s_trecode                         AS GUOKU_ID    -- 所属县国库代码
	 --  ,c.guoku_dscr                        AS GUOKU_LVL_DSCR_3  -- 所属县国库名称
	 --  ,d.subject_code_1                    AS SUBJECT_CODE_1    -- 科目类级代码
	 --  ,d.subject_dscr_1                    AS SUBJECT_DSCR_1    -- 科目类级名称
	 --  ,d.subject_code_2                    AS SUBJECT_CODE_2    -- 科目款级代码
	 --  ,d.subject_dscr_2                    AS SUBJECT_DSCR_2    -- 科目款级名称
	 --  ,d.subject_code_3                    AS SUBJECT_CODE_3    -- 科目项级代码
	 --  ,d.subject_dscr_3                    AS SUBJECT_DSCR_3    -- 科目项级名称
	,b.s_bdgsbtcode                      AS SUBJECT_CODE_4    -- 科目目级代码
	 --  ,d.subject_dscr_4                    AS SUBJECT_DSCR_4    -- 科目目级名称
	,b.s_bdglevel                        AS BUDGETLEVEL_CODE  -- 预算级次代码
	,e.budget_dscr                       AS BUDGETLEVEL_DSCR  -- 预算级次描述
	,b.f_dayamt                          AS F_DAYAMT          -- 日金额
	FROM edw.trs_d005_tr_movefundincm B
	 -- LEFT JOIN edw.cm_guoku_dimnsn C
	 -- ON b.s_trecode=c.guoku_id
	 -- LEFT JOIN edw.cm_guoku_rcpt_dsb D
	 -- ON b.s_bdgsbtcode=d.subject_code_4
	LEFT JOIN edw.cm_guoku_budget_level E
	ON b.s_bdglevel=e.budget_code
	WHERE b.d_expfile = s_date;
 
 CALL etl.edw_proc_trace_log(DATE_FORMAT(s_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  s_date := DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END LOOP;
END;
/

DROP PROCEDURE IF EXISTS adm.test_loop3;

CREATE PROCEDURE adm.test_loop3(IN s_date DATE,IN edate DATE)
AS
  V_START_TIME    CHAR(19) := NOW();
  V_PROC_NAME     VARCHAR(80) := 'adm.test_loop3.PRC';
