	 --  LEFT JOIN edw.cm_guoku_rcpt_dsb D
	 --  ON b.s_funcsbtcode=d.subject_code_4
	WHERE b.d_expfile =   s_date;
 
 CALL etl.edw_proc_trace_log(DATE_FORMAT(s_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  s_date := DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END LOOP;
END;
/

DROP PROCEDURE IF EXISTS adm.test_loop4;

CREATE PROCEDURE adm.test_loop4(IN s_date DATE,IN edate DATE)
AS
  V_START_TIME    CHAR(19) := NOW();
  V_PROC_NAME     VARCHAR(80) := 'adm.test_loop4.PRC';
  V_STEP_ID       INT := 0;
  V_SQL_INSERT    LONGTEXT := ''; -- 插数语句SQL
  V_SQLTXT        LONGTEXT := ''; -- 执行SQL
BEGIN
  -- DECLARE  data_date DATE ;  -- 数据日期
  -- SET data_date =  '2018-01-01';
  WHILE s_date <= edate
  LOOP
	 
-- 限额税收统计表-日
-- DROP TABLE adm.trs_budget_limit_income_daily
-- CREATE TABLE adm.trs_budget_limit_income_daily AS
select s_date;
delete from adm.trs_budget_limit_income_daily where D_ACCEPT = s_date;
insert into adm.trs_budget_limit_income_daily
SELECT
  c.lev_1_dscr AS INDUSTRY,
  aa.d_accept AS D_ACCEPT,
  aa.s_taxpaycode AS S_TAXPAYCODE,
  aa.s_taxpayname AS S_TAXPAYNAME,
  aa.s_etpname AS S_ETPNAME,
  aa.s_aimtrecode AS S_AIMTRECODE,
  dt3.guoku_dscr AS GUOKU_DSCR,
  aa.s_bdgsbtcode AS S_BDGSBTCODE,
  dt2.subject_dscr_4 AS S_BDGSBTNAME,
  aa.f_amt AS THIS_PERIOD_AMT,
  aa.taxdate AS TAXDATE,
  CURRENT_TIMESTAMP AS UPDATE_DATE
FROM
(
-- --电子税票
SELECT
  a.d_accept AS D_ACCEPT,
  a.s_payerorgcode AS S_PAYERORGCODE,
  a.s_payeracct AS S_PAYERACCT,
  a.s_payeropnbnkno AS S_PAYEROPNBNKNO,
  a.s_taxpaycode AS S_TAXPAYCODE,
  a.s_taxpayname AS S_TAXPAYNAME,
  a.s_etpcode AS S_ETPCODE,
  a.s_etpname AS S_ETPNAME,
  a.s_etptype AS S_ETPTYPE,
  a.s_aimtrecode AS S_AIMTRECODE,
  a.s_bdgsbtcode AS S_BDGSBTCODE,
  CONCAT(a.d_taxstartdate,'-',a.d_taxenddate) AS TAXDATE,
  a.f_amt AS F_AMT 
FROM
  edw.trs_d004_htv_import_incomeonline_detail a
WHERE
    a.d_accept = s_date
      AND a.c_bdgkind='1'
-- AND a.s_bdgsbtcode LIKE '101%'
  
  UNION ALL   
  -- --纸质税票
SELECT
  a.d_accept AS D_ACCEPT,
  a.s_payerorgcode AS S_PAYERORGCODE,
  '999999999999' AS S_PAYERACCT,
  NULL AS S_PAYEROPNBNKNO,
  '999999999999' AS S_TAXPAYCODE,
  '纸质税票' AS S_TAXPAYNAME,
  NULL AS S_ETPCODE,
  NULL AS S_ETPNAME,
  a.s_etptype AS S_ETPTYPE,
  a.s_aimtrecode AS S_AIMTRECODE,
  a.s_bdgsbtcode AS S_BDGSBTCODE,
  a.i_ofmonth AS TAXDATE,
  a.f_amt AS F_AMT 
FROM
  edw.trs_d004_htv_handbook_detail a
WHERE
 a.d_accept = s_date
  AND a.c_bdgkind='1'
-- AND a.s_bdgsbtcode LIKE '101%'
) aa
LEFT JOIN 
edw.cm_guoku_entpown_information_list dt1
ON aa.s_taxpaycode = dt1.s_taxpaycode
LEFT JOIN edw.cm_guoku_industry c ON dt1.lev_4_id=c.lev_4_id  
LEFT JOIN 
edw.cm_guoku_rcpt_dsb dt2
ON aa.s_bdgsbtcode = dt2.subject_code_4
LEFT JOIN
edw.cm_guoku_dimnsn dt3
ON aa.s_aimtrecode = dt3.guoku_id
;	 
	 
	 
	 
	 
	 
 
 CALL etl.edw_proc_trace_log(DATE_FORMAT(s_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  s_date := DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END LOOP;
END;
/

DROP PROCEDURE IF EXISTS adm.test_loop5;

CREATE PROCEDURE adm.test_loop5(IN s_date DATE,IN edate DATE)
AS
  V_START_TIME    CHAR(19) := NOW();
  V_PROC_NAME     VARCHAR(80) := 'adm.test_loop5.PRC';
  V_STEP_ID       INT := 0;
  V_SQL_INSERT    LONGTEXT := ''; -- 插数语句SQL
  V_SQLTXT        LONGTEXT := ''; -- 执行SQL
BEGIN
  -- DECLARE  data_date DATE ;  -- 数据日期
  -- SET data_date =  '2018-01-01';
  WHILE s_date <= edate
  LOOP
	  V_STEP_ID := 1;
	  delete from  adm.trs_sk_acct_stock where  REPORTDATE=s_date;
  
	  V_STEP_ID := 2;
		-- (多维)库存分账户统计表
	-- 2018年3月30日之后取(含30日)
	INSERT INTO adm.trs_sk_acct_stock
	SELECT
	 b.d_acct                          AS REPORTDATE        -- 时间（日）
	,DATE_FORMAT(b.d_acct,'%Y-%m')     AS D_MONTH           -- 时间（月）
	,DATE_FORMAT(b.d_acct,'%Y')        AS D_YEAR            -- 时间（年）
	 --  ,c.guoku_lvl_id_1                  AS GUOKU_LVL_ID_1      -- 所属省国库代码
	 --  ,c.guoku_lvl_dscr_1                AS GUOKU_LVL_DSCR_1    -- 所属省国库名称
	 --  ,c.guoku_lvl_id_2                  AS GUOKU_LVL_ID_2      -- 所属市国库代码
	 --  ,c.guoku_lvl_dscr_2                AS GUOKU_LVL_DSCR_2    -- 所属市国库名称
	,b.s_trecode                       AS GUOKU_ID      -- 所属县国库代码
	 --  ,c.guoku_dscr                      AS GUOKU_LVL_DSCR_3    -- 所属县国库名称
	,b.s_acct           AS ACCOUNT_CODE        -- 账户编码
	,b.s_acctname       AS ACCOUNT_NAME        -- 账户名称
	,b.f_predatebalance AS F_YESTERDAYBALANCE  -- 上期余额
	,b.f_dayincome      AS F_TODAYRECEIPT      -- 当期收入额
	,b.f_daypayout      AS F_TODAYPAY          -- 当期支出额
	,b.f_daybalance     AS F_TODAYBALANCE      -- 当期余额
	FROM edw.trs_d005_tr_stockday B
	 --  LEFT JOIN edw.cm_guoku_dimnsn C
	 --  ON b.s_trecode=c.guoku_id
	   WHERE b.d_acct =  s_date;
 
 CALL etl.edw_proc_trace_log(DATE_FORMAT(s_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  s_date := DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END LOOP;
END;
/

DROP PROCEDURE IF EXISTS adm.test_loop6;

CREATE PROCEDURE adm.test_loop6(IN s_date DATE,IN edate DATE)
AS
  V_START_TIME    CHAR(19) := NOW();
  V_PROC_NAME     VARCHAR(80) := 'adm.test_loop6.PRC';
  V_STEP_ID       INT := 0;
BEGIN
  -- DECLARE  data_date DATE ;  -- 数据日期
  -- SET data_date =  '2018-01-01';
  WHILE s_date <= edate
  LOOP
	  V_STEP_ID := 1;
    DELETE FROM adm.ana_trs_income_subject_struct WHERE D_DATE = s_date;
	  V_STEP_ID := 2;
-- 2018年3月30日之后（含30日）
INSERT INTO adm.ana_trs_income_subject_struct
-- 全辖
SELECT
DATE_FORMAT(s_date,'%Y-%m-%d') AS D_DATE -- 工具需要日期（该月第一天）
,DATE_FORMAT(s_date,'%Y-%m') AS D_YEAR_MTH   -- 数据日期（年-月）
,b.full_jue_guoku_id AS GUOKU_ID  -- 国库编码
,b.full_jue_guoku_dscr            -- 国库名称
,'1' AS FLAG_CODE          -- 辖属标志编码（1：全辖，2：本级）
,'全辖' AS FLAG            -- 辖属标志（1：全辖，2：本级）
,a.sub_lvl_code            -- 收入科目结构编码（01：税收收入，02：非税收入，03：社保收入，04：其他收入）
,a.sub_lvl_dscr            -- 收入科目结构名称（01：税收收入，02：非税收入，03：社保收入，04：其他收入）
,SUM(a.budget_income) AS BUDGET_INCOME -- 预算收入总金额（元）
FROM (
SELECT
m.s_trecode -- 国库编码
,m.sub_lvl_code -- 收入科目结构编码（01：税收收入，02：非税收入，03：社保收入，04：其他收入）
,m.sub_lvl_dscr -- 收入科目结构名称（01：税收收入，02：非税收入，03：社保收入，04：其他收入）
,SUM(m.budget_income) AS BUDGET_INCOME -- 预算收入金额（元）
FROM (
-- 本月-预算收入金额(正常期预算收入)
SELECT
m.s_trecode -- 国库编码
,CASE WHEN SUBSTR(m.s_bdgsbtcode,1,3)='101' THEN '01'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3)='102' THEN '02'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3)='103' THEN '03'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3) NOT IN ('101','102','103') THEN '04'
END AS SUB_LVL_CODE -- 收入科目结构编码
,CASE WHEN SUBSTR(m.s_bdgsbtcode,1,3)='101' THEN '税收收入'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3)='102' THEN '政府性基金预算收入'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3)='103' THEN '社保收入'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3) NOT IN ('101','102','103') THEN '其他收入'
END AS SUB_LVL_DSCR -- 收入科目结构名称
,m.f_monthamt AS BUDGET_INCOME   -- 预算收入金额（元）
FROM edw.trs_d005_tr_bdgincm M  -- 正常期预算收入报表
WHERE D_EXPFILE=s_date
UNION ALL
-- 本月-预算收入金额(正常期调拨收入)
SELECT
m.s_trecode -- 国库编码
,CASE WHEN SUBSTR(m.s_bdgsbtcode,1,3)='101' THEN '01'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3)='102' THEN '02'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3)='103' THEN '03'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3) NOT IN ('101','102','103') THEN '04'
END AS SUB_LVL_CODE -- 收入科目结构编码
,CASE WHEN SUBSTR(m.s_bdgsbtcode,1,3)='101' THEN '税收收入'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3)='102' THEN '政府性基金预算收入'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3)='103' THEN '社保收入'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3) NOT IN ('101','102','103') THEN '其他收入'
END AS SUB_LVL_DSCR -- 收入科目结构名称
,m.f_monthamt AS BUDGET_INCOME   -- 预算收入金额（元）
FROM edw.trs_d005_tr_movefundincm M  -- 正常期调拨收入报表
WHERE D_EXPFILE=s_date
) M
GROUP BY m.s_trecode,m.sub_lvl_code
) A
LEFT JOIN edw.cm_guoku_ana_whole_bank B
ON a.s_trecode=b.sub_guoku_id
GROUP BY 
DATE_FORMAT(s_date,'%Y-%m-01')
,DATE_FORMAT(s_date,'%Y-%m')
,s_date 
,b.full_jue_guoku_id 
,b.full_jue_guoku_dscr           
,a.sub_lvl_code           
,a.sub_lvl_dscr 
UNION ALL
-- 本级
SELECT
DATE_FORMAT(s_date,'%Y-%m-01') AS D_DATE -- 工具需要日期（该月第一天）
,DATE_FORMAT(s_date,'%Y-%m') AS D_YEAR_MTH   -- 数据日期（年-月）
,a.s_trecode AS GUOKU_ID   -- 国库编码
,b.guoku_dscr              -- 国库名称
,'2' AS FLAG_CODE          -- 辖属标志编码（1：全辖，2：本级）
,'本级' AS FLAG            -- 辖属标志（1：全辖，2：本级）
,a.sub_lvl_code            -- 收入科目结构编码（01：税收收入，02：非税收入，03：社保收入，04：其他收入）
,a.sub_lvl_dscr            -- 收入科目结构名称（01：税收收入，02：非税收入，03：社保收入，04：其他收入）
,SUM(a.budget_income) AS BUDGET_INCOME -- 预算收入总金额（元）
FROM (
-- 本月-预算收入金额(正常期预算收入)
SELECT
m.s_trecode -- 国库编码
,CASE WHEN SUBSTR(m.s_bdgsbtcode,1,3)='101' THEN '01'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3)='102' THEN '02'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3)='103' THEN '03'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3) NOT IN ('101','102','103') THEN '04'
END AS SUB_LVL_CODE -- 收入科目结构编码
,CASE WHEN SUBSTR(m.s_bdgsbtcode,1,3)='101' THEN '税收收入'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3)='102' THEN '政府性基金预算收入'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3)='103' THEN '社保收入'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3) NOT IN ('101','102','103') THEN '其他收入'
END AS SUB_LVL_DSCR -- 收入科目结构名称
,m.f_monthamt AS BUDGET_INCOME   -- 预算收入金额（元）
FROM edw.trs_d005_tr_bdgincm M  -- 正常期预算收入报表
WHERE D_EXPFILE=s_date
UNION ALL
-- 本月-预算收入金额(正常期调拨收入)
SELECT
m.s_trecode -- 国库编码
,CASE WHEN SUBSTR(m.s_bdgsbtcode,1,3)='101' THEN '01'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3)='102' THEN '02'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3)='103' THEN '03'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3) NOT IN ('101','102','103') THEN '04'
END AS SUB_LVL_CODE -- 收入科目结构编码
,CASE WHEN SUBSTR(m.s_bdgsbtcode,1,3)='101' THEN '税收收入'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3)='102' THEN '政府性基金预算收入'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3)='103' THEN '社保收入'
      WHEN SUBSTR(m.s_bdgsbtcode,1,3) NOT IN ('101','102','103') THEN '其他收入'
END AS SUB_LVL_DSCR -- 收入科目结构名称
,m.f_monthamt AS BUDGET_INCOME   -- 预算收入金额（元）
FROM edw.trs_d005_tr_movefundincm M  -- 正常期调拨收入报表
WHERE D_EXPFILE=s_date
) A
LEFT JOIN edw.cm_guoku_dimnsn B
ON a.s_trecode=b.guoku_id
GROUP BY a.s_trecode,a.sub_lvl_code;
 
 CALL etl.edw_proc_trace_log(DATE_FORMAT(s_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  s_date := DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END LOOP;
END;
/

DROP PROCEDURE IF EXISTS adm.test_loop7;

CREATE PROCEDURE adm.test_loop7(IN s_date DATE,IN edate DATE)
AS
  V_START_TIME    CHAR(19) := NOW();
  V_PROC_NAME     VARCHAR(80) := 'adm.test_loop7.PRC';
  V_STEP_ID       INT := 0;
BEGIN
  -- DECLARE  s_date DATE ;  -- 数据日期
  -- SET s_date =  '2018-01-01';
  WHILE s_date <= edate
  LOOP
	  V_STEP_ID := 1;
    DELETE FROM adm.trs_stock_change_monthly WHERE D_REPORTDATE = DATE_FORMAT(s_date,'%Y-%m');
	  V_STEP_ID := 2;
-- 2018年3月30日之后（含30日）
INSERT INTO adm.trs_stock_change_monthly
-- 全辖
SELECT 
  DATE_FORMAT(aa.d_reportdate,'%Y-%m') AS D_REPORTDATE,
  aa.s_trecode AS S_TRECODE,
  dt1.guoku_dscr AS GUOKU_DSCR,
  aa.s_acctcode AS S_ACCTCODE,
  aa.s_acctname AS S_ACCTNAME,
  aa.d_acctdate AS D_ACCTDATE,
  aa.sub_acctcode AS SUB_ACCTCODE,
  dt1.level AS LEVEL,
  aa.f_todaybalance AS THIS_PERIOD_AMT,
  bb.f_todaybalance AS LAST_PERIOD_AMT,
  CURRENT_TIMESTAMP AS UPDATE_DATE 
FROM
  (SELECT 
    a.d_reportdate AS D_REPORTDATE,
    a.s_trecode AS S_TRECODE,
    a.s_acctcode AS S_ACCTCODE,
    a.s_acctname AS S_ACCTNAME,
    a.d_acctdate AS D_ACCTDATE,
    b.acount_subject AS SUB_ACCTCODE,
    a.f_todaybalance AS F_TODAYBALANCE 
  FROM
    edw.trs_d003_tr_stock a 
   JOIN 
      (SELECT 
        MAX(tb.d_reportdate) AS D_REPORTDATE,      
        tb.s_trecode,
        tb.s_acctcode,
        MAX(tb.d_acctdate) AS D_ACCTDATE
      FROM
        edw.trs_d003_tr_stock tb
      WHERE tb.d_reportdate BETWEEN DATE_FORMAT(s_date,'%Y-%m-01') AND s_date
      GROUP BY tb.s_trecode,
        tb.s_acctcode
        )c
         ON a.d_reportdate = c.d_reportdate
        AND a.s_trecode = c.s_trecode
        AND a.s_acctcode = c.s_acctcode
        AND a.d_acctdate = c.d_acctdate
    LEFT JOIN 
      (SELECT DISTINCT 
        t.guoku_id AS GUOKU_ID,
        t.acount_code AS ACOUNT_CODE,
        t.acount_subject AS ACOUNT_SUBJECT 
      FROM
        edw.cm_guoku_trecode_account t) b 
      ON a.s_acctcode = b.acount_code 
      AND a.s_trecode = b.guoku_id
  ) aa 
  LEFT JOIN 
    (SELECT 
      a.d_reportdate AS D_REPORTDATE,
      a.s_trecode AS S_TRECODE,
      a.s_acctcode AS S_ACCTCODE,
      a.s_acctname AS S_ACCTNAME,
      a.d_acctdate AS D_ACCTDATE,
      b.acount_subject AS SUB_ACCTCODE,
      a.f_todaybalance AS F_TODAYBALANCE 
    FROM
      edw.trs_d003_tr_stock a 
      JOIN 
      (SELECT 
        MAX(tb.d_reportdate) AS D_REPORTDATE,      
        tb.s_trecode,
        tb.s_acctcode,
        MAX(tb.d_acctdate) AS D_ACCTDATE
      FROM
        edw.trs_d003_tr_stock tb
      WHERE tb.d_reportdate BETWEEN DATE_SUB(DATE_FORMAT(s_date,'%Y-%m-01'), INTERVAL 1 YEAR) AND DATE_SUB(s_date, INTERVAL 1 YEAR)
      GROUP BY tb.s_trecode,
        tb.s_acctcode
        )c
         ON a.d_reportdate = c.d_reportdate
        AND a.s_trecode = c.s_trecode
        AND a.s_acctcode = c.s_acctcode
        AND a.d_acctdate = c.d_acctdate
      LEFT JOIN 
        (SELECT DISTINCT 
          t.guoku_id AS GUOKU_ID,
          t.acount_code AS ACOUNT_CODE,
          t.acount_subject AS ACOUNT_SUBJECT 
        FROM
          edw.cm_guoku_trecode_account t) b 
        ON a.s_acctcode = b.acount_code 
        AND a.s_trecode = b.guoku_id 
    ) bb 
    ON  aa.d_reportdate = DATE_ADD(bb.d_reportdate,INTERVAL 1 YEAR)
    AND aa.s_trecode = bb.s_trecode 
    AND aa.s_acctcode = bb.s_acctcode 
    AND aa.s_acctname = bb.s_acctname 
    AND aa.d_acctdate = bb.d_acctdate 
    AND aa.sub_acctcode = bb.sub_acctcode 
  LEFT JOIN edw.cm_guoku_dimnsn dt1 
    ON aa.s_trecode = dt1.guoku_id
    ;
 
  CALL etl.edw_proc_trace_log(DATE_FORMAT(s_date,'%Y-%m-%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  s_date := DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END LOOP;
END;
/

DROP PROCEDURE IF EXISTS adm.test_loop8;

CREATE PROCEDURE adm.test_loop8(IN s_date DATE,IN edate DATE)
AS
  V_START_TIME    CHAR(19) := NOW();
  V_PROC_NAME     VARCHAR(80) := 'adm.test_loop8.PRC';
  V_STEP_ID       INT := 0;
BEGIN
  -- DECLARE  s_date DATE ;  -- 数据日期
  -- SET s_date =  '2018-01-01';
  WHILE s_date <= edate
  LOOP
	  V_STEP_ID := 1;
 -- DELETE FROM adm.trs_budget_function_income_daily WHERE D_REPORTDATE = DATE_FORMAT(s_date,'%Y-%m');
	  V_STEP_ID := 2;
-- 2018年3月30日之后（含30日）
INSERT INTO adm.trs_budget_function_income_daily
-- 功能分类预算收入-日
-- DROP TABLE adm.trs_budget_function_income_daily
-- CREATE TABLE adm.trs_budget_function_income_daily AS
SELECT
 DATE_FORMAT(aa.d_reportdate,'%Y-%m-%d') AS D_REPORTDATE,
 aa.s_trecode AS S_TRECODE,
 aa.c_budgetlevel AS C_BUDGETLEVEL,
 dt1.subject_code_4 AS SUBJECT_CODE_4,
 dt1.subject_dscr_4 AS SUBJECT_DSCR_4,
 dt1.fun_class_code_1 AS FUN_CLASS_CODE_1,
 dt1.fun_class_dscr_1 AS FUN_CLASS_DSCR_1,
 dt1.fun_class_code_2 AS FUN_CLASS_CODE_2,
 dt1.fun_class_dscr_2 AS FUN_CLASS_DSCR_2,
 dt1.fun_class_code_3 AS FUN_CLASS_CODE_3,
 dt1.fun_class_dscr_3 AS FUN_CLASS_DSCR_3,
 aa.f_dayamt AS THIS_PERIOD_AMT,
 bb.f_dayamt AS LAST_PERIOD_AMT,
 aa.f_yearamt AS THIS_PERIOD_YEARAMT,
 bb.f_yearamt AS LAST_PERIOD_YEARAMT,
 CURRENT_TIMESTAMP AS UPDATE_DATE
FROM
(
    -- -- 本期预算收入
 SELECT 
D_REPORTDATE,
'2200000000' AS S_TRECODE,
C_BUDGETLEVEL,
S_BUDGETSUBJECTCODE,
S_BUDGETSUBJECTNAME,
SUM(F_DAYAMT) AS F_DAYAMT,
SUM(F_YEARAMT) AS F_YEARAMT FROM 
(SELECT 
  D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME,
  SUM(F_DAYAMT) AS F_DAYAMT,
  SUM(F_YEARAMT) AS F_YEARAMT 
FROM
  edw.trs_d003_tr_budget_income 
WHERE D_REPORTDATE = s_date 
  AND C_BUDGETTYPE = '1' 
  AND S_TAXORGCODE = '000000000000' 
  AND S_TRECODE='2200000000'
GROUP BY D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME 
UNION ALL 
SELECT 
  D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME,
  - 1 * SUM(F_DAYAMT) AS F_DAYAMT,
  - 1 * SUM(F_YEARAMT) AS F_YEARAMT 
FROM
  edw.trs_d003_tr_budget_income 
WHERE D_REPORTDATE = s_date 
  AND S_TRECODE <> '2200000000'
  AND    C_BUDGETTYPE = '1' 
  AND S_TAXORGCODE <>  '000000000000'
GROUP BY D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME
  
  UNION ALL 
SELECT 
  D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME,
  - 1 * SUM(F_DAYAMT) AS F_DAYAMT,
  - 1 * SUM(F_YEARAMT) AS F_YEARAMT 
FROM
  edw.trs_d003_tr_budget_income 
WHERE D_REPORTDATE = s_date 
  AND S_TRECODE <> '2200000000'
  AND    C_BUDGETTYPE = '1' 
  AND   C_BUDGETLEVEL='4'
  AND S_TAXORGCODE <>  '000000000000'
GROUP BY D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME
  
    UNION ALL 
SELECT 
  D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME,
  - 1 * SUM(F_DAYAMT) AS F_DAYAMT,
  - 1 * SUM(F_YEARAMT) AS F_YEARAMT 
FROM
  edw.trs_d003_tr_budget_income 
WHERE D_REPORTDATE = s_date 
  AND S_TRECODE <> '2200000000'
  AND    C_BUDGETTYPE = '1' 
  AND   C_BUDGETLEVEL='5'
  AND S_TAXORGCODE <>  '000000000000'
GROUP BY D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME
  ) a 
  GROUP BY D_REPORTDATE,
 S_TRECODE,
C_BUDGETLEVEL,
S_BUDGETSUBJECTCODE,
S_BUDGETSUBJECTNAME
	UNION ALL
   -- -- 本期调拨收入（转移性收入）
	SELECT 
	 t1.d_reportdate AS D_REPORTDATE,
	 t1.s_trecode AS S_TRECODE,
	 t1.c_budgetlevel AS C_BUDGETLEVEL,
	 t1.s_budgetsubjectcode AS S_BUDGETSUBJECTCODE,
	 t1.s_budgetsubjectname AS S_BUDGETSUBJECTNAME,
	 SUM(t1.f_dayamt) AS F_DAYAMT,
	 SUM(t1.f_yearamt) AS F_YEARAMT
	FROM edw.trs_d003_tr_move_income t1
	WHERE  D_REPORTDATE = s_date
	AND S_TRECODE = '2200000000'
	GROUP BY
	t1.d_reportdate,
	t1.s_trecode,
	t1.c_budgetlevel,
	t1.s_budgetsubjectcode,
	t1.s_budgetsubjectname
) aa
LEFT JOIN
-- --去年同期
(
    -- -- 本期预算收入
 SELECT 
D_REPORTDATE,
'2200000000' AS S_TRECODE,
C_BUDGETLEVEL,
S_BUDGETSUBJECTCODE,
S_BUDGETSUBJECTNAME,
SUM(F_DAYAMT) AS F_DAYAMT,
SUM(F_YEARAMT) AS F_YEARAMT FROM 
(SELECT 
  D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME,
  SUM(F_DAYAMT) AS F_DAYAMT,
  SUM(F_YEARAMT) AS F_YEARAMT 
FROM
  edw.trs_d003_tr_budget_income 
WHERE D_REPORTDATE = DATE_SUB(s_date,INTERVAL 1 YEAR) 
  AND C_BUDGETTYPE = '1' 
  AND S_TAXORGCODE = '000000000000' 
  AND S_TRECODE='2200000000'
GROUP BY D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME 
UNION ALL 
SELECT 
  D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME,
  - 1 * SUM(F_DAYAMT) AS F_DAYAMT,
  - 1 * SUM(F_YEARAMT) AS F_YEARAMT 
FROM
  edw.trs_d003_tr_budget_income 
WHERE D_REPORTDATE = DATE_SUB(s_date,INTERVAL 1 YEAR) 
  AND S_TRECODE <> '2200000000'
  AND    C_BUDGETTYPE = '1' 
  AND S_TAXORGCODE <>  '000000000000'
GROUP BY D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME
  
  UNION ALL 
SELECT 
  D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME,
  - 1 * SUM(F_DAYAMT) AS F_DAYAMT,
  - 1 * SUM(F_YEARAMT) AS F_YEARAMT 
FROM
  edw.trs_d003_tr_budget_income 
WHERE D_REPORTDATE = DATE_SUB(s_date,INTERVAL 1 YEAR) 
  AND S_TRECODE <> '2200000000'
  AND    C_BUDGETTYPE = '1' 
  AND   C_BUDGETLEVEL='4'
  AND S_TAXORGCODE <>  '000000000000'
GROUP BY D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME
  
    UNION ALL 
SELECT 
  D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME,
  - 1 * SUM(F_DAYAMT) AS F_DAYAMT,
  - 1 * SUM(F_YEARAMT) AS F_YEARAMT 
FROM
  edw.trs_d003_tr_budget_income 
WHERE D_REPORTDATE = DATE_SUB(s_date,INTERVAL 1 YEAR) 
  AND S_TRECODE <> '2200000000'
  AND    C_BUDGETTYPE = '1' 
  AND   C_BUDGETLEVEL='5'
  AND S_TAXORGCODE <>  '000000000000'
GROUP BY D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME
  ) a 
  GROUP BY D_REPORTDATE,
 S_TRECODE,
C_BUDGETLEVEL,
S_BUDGETSUBJECTCODE,
S_BUDGETSUBJECTNAME 
	UNION ALL
   -- -- 调拨收入（转移性收入）
	SELECT 
	 t1.d_reportdate AS D_REPORTDATE,
	 t1.s_trecode AS S_TRECODE,
	 t1.c_budgetlevel AS C_BUDGETLEVEL,
	 t1.s_budgetsubjectcode AS S_BUDGETSUBJECTCODE,
	 t1.s_budgetsubjectname AS S_BUDGETSUBJECTNAME,
	 SUM(t1.f_dayamt) AS F_DAYAMT,
	 SUM(t1.f_yearamt) AS F_YEARAMT
	FROM edw.trs_d003_tr_move_income t1
	WHERE  D_REPORTDATE = DATE_SUB(s_date,INTERVAL 1 YEAR)
	AND S_TRECODE = '2200000000'
	GROUP BY
	t1.d_reportdate,
	t1.s_trecode,
	t1.c_budgetlevel,
	t1.s_budgetsubjectcode,
	t1.s_budgetsubjectname
) bb
ON  aa.d_reportdate = DATE_ADD(bb.d_reportdate,INTERVAL 1 YEAR)
AND aa.s_trecode = bb.s_trecode
AND aa.c_budgetlevel = bb.c_budgetlevel
AND aa.s_budgetsubjectcode = bb.s_budgetsubjectcode
JOIN
(
SELECT
a.fun_class_code_1 AS FUN_CLASS_CODE_1,
a.fun_class_dscr_1 AS FUN_CLASS_DSCR_1,
a.fun_class_code_2 AS FUN_CLASS_CODE_2,
a.fun_class_dscr_2 AS FUN_CLASS_DSCR_2,
a.fun_class_code_3 AS FUN_CLASS_CODE_3,
a.fun_class_dscr_3 AS FUN_CLASS_DSCR_3,
b.subject_code_4 AS SUBJECT_CODE_4,
b.subject_dscr_4 AS SUBJECT_DSCR_4
FROM
edw.cm_guoku_functional_type a
LEFT JOIN
-- edw.cm_guoku_rcpt_dsb_fuc b
-- ON  a.fun_class_code_3 = b.fun_class_code_3
edw.cm_guoku_rcpt_dsb b
ON  a.fun_class_code_3 = b.t_class_code_3
WHERE
-- b.of_year = YEAR(s_date) AND 
a.fun_class_code_1 = 'T01'
) dt1
ON aa.s_budgetsubjectcode = dt1.subject_code_4;
 
  CALL etl.edw_proc_trace_log(DATE_FORMAT(s_date,'%Y-%m-%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  s_date := DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END LOOP;
END;
/

