	AND S_TRECODE <> '2200000000'
	GROUP BY
	t1.d_reportdate,
	t1.s_trecode,
	t1.c_budgetlevel,
	t1.s_budgetsubjectcode,
	t1.s_budgetsubjectname
	
	UNION ALL
	-- 重庆分库的本级
	SELECT 
	 t1.d_reportdate AS D_REPORTDATE,
	 t1.s_trecode AS S_TRECODE,
	 t1.c_budgetlevel AS C_BUDGETLEVEL,
	 t1.s_budgetsubjectcode AS S_BUDGETSUBJECTCODE,
	 t1.s_budgetsubjectname AS S_BUDGETSUBJECTNAME,
	 SUM(t1.f_dayamt) AS F_DAYAMT,
	 SUM(t1.f_yearamt) AS F_YEARAMT
	FROM edw.trs_d003_tr_budget_income t1
	WHERE  D_REPORTDATE = s_date
	AND S_TAXORGCODE  IN('XXXXXXXXXXXX') 
	AND S_TRECODE = '2200000000'
	GROUP BY
	t1.d_reportdate,
	t1.s_trecode,
	t1.c_budgetlevel,
	t1.s_budgetsubjectcode,
	t1.s_budgetsubjectname
	
	UNION ALL
   -- -- 本期调拨收入（转移性收入）
	SELECT 
	 t1.d_reportdate AS D_REPORTDATE,
	 t1.s_trecode AS S_TRECODE,
	 t1.c_budgetlevel AS C_BUDGETLEVEL,
	 t1.s_budgetsubjectcode AS S_BUDGETSUBJECTCODE,
	 t1.s_budgetsubjectname AS S_BUDGETSUBJECTNAME,
	 SUM(t1.f_dayamt) AS F_DAYAMT,
	 SUM(t1.f_yearamt) AS F_YEARAMT
	FROM edw.trs_d003_tr_move_income t1
	WHERE  D_REPORTDATE = s_date
-- 	AND S_TAXORGCODE NOT IN('000000000000','XXXXXXXXXXXX') 
-- 	AND S_TRECODE = '2200000000'
	GROUP BY
	t1.d_reportdate,
	t1.s_trecode,
	t1.c_budgetlevel,
	t1.s_budgetsubjectcode,
	t1.s_budgetsubjectname
) aa
JOIN
(
SELECT
a.fun_class_code_1 AS FUN_CLASS_CODE_1,
a.fun_class_dscr_1 AS FUN_CLASS_DSCR_1,
a.fun_class_code_2 AS FUN_CLASS_CODE_2,
a.fun_class_dscr_2 AS FUN_CLASS_DSCR_2,
a.fun_class_code_3 AS FUN_CLASS_CODE_3,
a.fun_class_dscr_3 AS FUN_CLASS_DSCR_3,
b.subject_code_4 AS SUBJECT_CODE_4,
b.subject_dscr_4 AS SUBJECT_DSCR_4
FROM
edw.cm_guoku_functional_type a
LEFT JOIN
edw.cm_guoku_rcpt_dsb b
ON  a.fun_class_code_3 = b.t_class_code_3
WHERE
-- b.of_year = YEAR(s_date)
 a.fun_class_code_1 = 'T01'
) dt1
ON aa.s_budgetsubjectcode = dt1.subject_code_4
  
  
 
  
  
 ;
  
 
 CALL etl.edw_proc_trace_log(DATE_FORMAT(s_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  s_date := DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END LOOP;
END;
/

DROP PROCEDURE IF EXISTS adm.test_loop_stock;

CREATE PROCEDURE adm.test_loop_stock(IN s_date DATE,IN edate DATE)
AS
  V_START_TIME    CHAR(19) := NOW();
  V_PROC_NAME     VARCHAR(80) := 'adm.test_loop_stock.PRC';
  V_STEP_ID       INT := 0;
  V_SQL_INSERT    LONGTEXT := ''; -- 插数语句SQL
  V_SQLTXT        LONGTEXT := ''; -- 执行SQL
BEGIN
  -- DECLARE  data_date DATE ;  -- 数据日期
  -- SET data_date =  '2018-01-01';
  WHILE s_date <= edate
  LOOP
	  V_STEP_ID := 1;
	  DELETE FROM  adm.trs_stock_change_daily WHERE  D_REPORTDATE=s_date;  
	  V_STEP_ID := 2;
	-- 库存变动情况-日
-- drop table adm.trs_stock_change_daily
-- CREATE TABLE adm.trs_stock_change_daily AS
INSERT INTO adm.trs_stock_change_daily
 (
D_REPORTDATE,
S_TRECODE,
GUOKU_DSCR,
S_ACCTCODE,
S_ACCTNAME,
D_ACCTDATE,
SUB_ACCTCODE,
LEVEL,
THIS_PERIOD_AMT,
LAST_PERIOD_AMT,
UPDATE_DATE 
 )
SELECT
  aa.d_reportdate AS D_REPORTDATE,
  aa.s_trecode AS S_TRECODE,
  dt1.guoku_dscr AS GUOKU_DSCR,
  aa.s_acctcode AS S_ACCTCODE,
  aa.s_acctname AS S_ACCTNAME,
  aa.d_acctdate AS D_ACCTDATE,
  aa.sub_acctcode AS SUB_ACCTCODE,
  dt1.level AS LEVEL,
  aa.f_todaybalance AS THIS_PERIOD_AMT,
  bb.f_todaybalance AS LAST_PERIOD_AMT,
  CURRENT_TIMESTAMP AS UPDATE_DATE
FROM
(

	SELECT
	  a.d_reportdate AS D_REPORTDATE,
	  a.s_trecode AS S_TRECODE,
	  a.s_acctcode AS S_ACCTCODE,
	  a.s_acctname AS S_ACCTNAME,
	  a.d_acctdate AS D_ACCTDATE,
	  b.acount_subject AS SUB_ACCTCODE,
	  a.f_todaybalance AS F_TODAYBALANCE
	FROM
	  edw.trs_d003_tr_stock a
	LEFT JOIN 
	  (
		SELECT DISTINCT
		t.guoku_id AS GUOKU_ID,
		t.acount_code AS ACOUNT_CODE,
		t.acount_subject AS ACOUNT_SUBJECT
		FROM
		edw.cm_guoku_trecode_account t
	  ) b
	ON a.s_acctcode = b.acount_code
	AND a.s_trecode = b.guoku_id
	WHERE 
	  a.d_reportdate = s_date
) aa
LEFT JOIN
(
	SELECT
	  a.d_reportdate AS D_REPORTDATE,
	  a.s_trecode AS S_TRECODE,
	  a.s_acctcode AS S_ACCTCODE,
	  a.s_acctname AS S_ACCTNAME,
	  a.d_acctdate AS D_ACCTDATE,
	  b.acount_subject AS SUB_ACCTCODE,
	  a.f_todaybalance AS F_TODAYBALANCE
	FROM
	  edw.trs_d003_tr_stock a
	LEFT JOIN 
	  (
		SELECT DISTINCT
		t.guoku_id AS GUOKU_ID,
		t.acount_code AS ACOUNT_CODE,
		t.acount_subject AS ACOUNT_SUBJECT
		FROM
		edw.cm_guoku_trecode_account t
	  ) b
	ON a.s_acctcode = b.acount_code
	AND a.s_trecode = b.guoku_id
	WHERE 
	  a.d_reportdate = DATE_SUB(s_date, INTERVAL 1 YEAR)
) bb
ON  bb.d_reportdate = DATE_SUB((aa.d_reportdate),INTERVAL 1 YEAR)
AND aa.s_trecode = bb.s_trecode
AND aa.s_acctcode = bb.s_acctcode
AND aa.s_acctname = bb.s_acctname
-- AND aa.d_acctdate = bb.d_acctdate
AND bb.d_reportdate = DATE_SUB((aa.d_acctdate),INTERVAL 1 YEAR)
AND aa.sub_acctcode = bb.sub_acctcode
LEFT JOIN
edw.cm_guoku_dimnsn_fact dt1
ON aa.s_trecode = dt1.guoku_id

;
 
 
 CALL etl.edw_proc_trace_log(DATE_FORMAT(s_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  s_date := DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END LOOP;
END;
/

DROP FUNCTION IF EXISTS adm.num_char;

CREATE FUNCTION adm.num_char(Varstring VARCHAR(1000)) RETURNS varchar(500)
AS $function$
DECLARE
    len INT := 0;
    Tmp VARCHAR(1000) := '';
BEGIN
    len := CHAR_LENGTH(Varstring);
    WHILE len > 0 LOOP
        IF NOT (MID(Varstring, len, 1) REGEXP '^[u0391-uFFE5]') THEN
            Tmp := CONCAT(Tmp, MID(Varstring, len, 1));
        END IF;
        len := len - 1;
    END LOOP;
    RETURN REVERSE(Tmp);
END;
$function$
LANGUAGE plpgsql;
DROP FUNCTION IF EXISTS adm.py_cx_getchildorglistbypid;

CREATE FUNCTION adm.py_cx_getchildorglistbypid(rootId VARCHAR(50)) RETURNS varchar(20000)
AS $function$
DECLARE
    sTemp VARCHAR(20000);
    sTempChd VARCHAR(20000);
BEGIN
    sTemp := '$';
    sTempChd := rootId;
    WHILE sTempChd != '' LOOP
        sTemp := CONCAT(sTemp, ',', sTempChd);
        SELECT GROUP_CONCAT(org_id)
          INTO sTempChd
          FROM dmcode.t_org_biz_lvl
         WHERE PARENT_ORG_ID <> org_id
           AND FIND_IN_SET(PARENT_ORG_ID, sTempChd) > 0;
    END LOOP;
    RETURN sTemp;
END;
$function$
LANGUAGE plpgsql;